  ui_story_5038_50380001_7_dialog_content = "¡Ja ja! Bien, buena marcha. Debe ser duro trabajar en lugares extranjeros?",
  ui_story_5038_50380001_8_dialog_content = "¡No es problema! ¡Nada tan pequeño me detendrá!",
  ui_story_5038_50380001_9_dialog_content = "¿Te estoy manteniendo alejado de cosas importantes, Nawoxel?",
  ui_story_5038_50380001_10_dialog_content = "No no. Para nada. No tengo prisa hoy.",
