  ui_story_5038_50380001_14_dialog_content = "<size=50>¡¿Eh?! 30 artículos?!!</size>",
  ui_story_5038_50380001_15_dialog_content = "Esos son solo los urgentes. Encontrarás otros 50 normales en la parte de atrás.",
