  ui_story_5038_50380001_29_dialog_content = "¡Muy bien! Entonces debería prepararme para... Obtener... ¡VAMOS!",
  ui_story_5038_50380001_30_dialog_content = "<color=#e8d9bb>5 días después</color>",
