  ui_story_5038_50380001_32_dialog_content = "<size=50>PlayerName! ¡H-Ayúdame!</size>",
  ui_story_5038_50380001_33_dialog_content = "¿Eh? ¿Piolín? ¡¿Qué ocurre?!",
