  ui_story_5038_50380001_37_dialog_content = "Así que, verá, recientemente Umbwaton contrató a Courier Union para ayudar a eliminar un montón de <color=#FFB400>papel rojo</color>.",
  ui_story_5038_50380001_38_dialog_content = "Debido a que es un pedido grande y muy urgente, he estado trabajando horas extras para entregarlos todos...",
