  ui_story_5038_50380001_46_dialog_content = "¡¿Tan drástico?!",
  ui_story_5038_50380001_47_dialog_content = "Así que... ¡Piolín quiere pedirte ayuda, señor!",
  ui_story_5038_50380001_48_dialog_content = "¿Puedo contratar a Sowoz para que me haga twansport?",
  ui_story_5038_50380001_49_dialog_content = "¡Pagaré! ¡Cuando tenga el salawy de este mes, te lo daré todo!",
  ui_story_5038_50380001_50_dialog_content = "No tienes que preocuparte por pagar. Estaré encantado de ayudarte.",
  ui_story_5038_50380001_51_dialog_content = "Como el tiempo parece ser esencial, ¡podríamos ponernos en marcha ahora!",
  ui_story_5038_50380001_52_dialog_content = "¿Adónde te diriges?",
  ui_story_5038_50380001_53_dialog_content = "Una ciudad portuaria llamada Twin Pavilions Bay.",
  ui_story_5038_50380001_54_dialog_content = "Soroz está justo encima de la cuenca del río Gold en este momento.",
  ui_story_5038_50380001_55_dialog_content = "Si seguimos el río río abajo hasta que veamos el océano, allí estará Twin Pavilions Bay.",
  ui_story_5038_50380001_56_dialog_content = "¿Has estado allí?",
  ui_story_5038_50380001_57_dialog_content = "No, no personalmente. Acabo de leer sobre ello en la biblioteca de Lumopolis.",
  ui_story_5038_50380001_58_dialog_content = "Se encuentra a lo largo del estuario del río Gold y tiene su propia cultura única. A menudo se cita en muchos libros diferentes.",
  ui_story_5038_50380001_59_dialog_content = "Además, es posible que esté familiarizado con sus orígenes.",
  ui_story_5038_50380001_60_dialog_content = "¿Cómo es eso?",
  ui_story_5038_50380001_61_dialog_content = "<color=#FFB400>El gremio Lin</color> fundó la ciudad.",
  ui_story_5038_50380001_62_dialog_content = "¿El gremio Lin? ¿No están en Umbraton?",
  ui_story_5038_50380001_63_dialog_content = "Umbraton es el lugar donde hacen negocios, pero Twin Pavilions Bay es el lugar al que llaman hogar.",
  ui_story_5038_50380001_64_dialog_content = "No olvides que Lin Guild proviene de otro continente muy al este.",
  ui_story_5038_50380001_65_dialog_content = "Antes de que aparecieran, el estuario del río Gold solo albergaba unas pocas aldeas pesqueras pequeñas y empobrecidas.",
  ui_story_5038_50380001_66_dialog_content = "Un día, un gran barco llegó a sus costas y trajo algunos miembros del Gremio Lin a Astra.",
  ui_story_5038_50380001_67_dialog_content = "Descargaron un montón de mercancías del Lejano Oriente, que luego procedieron a transportar a lo largo del Río Dorado hasta Umbraton.",
  ui_story_5038_50380001_68_dialog_content = "Tuvieron que contratar trabajadores y necesitaban lugares para alojarse y comer. Con el tiempo, los aldeanos locales encontraron gradualmente nuevos trabajos.",
  ui_story_5038_50380001_69_dialog_content = "El puerto prosperó con el dinero que ganó Lin Guild.",
  ui_story_5038_50380001_70_dialog_content = "Los lugareños dieron la bienvenida a la influencia de las culturas orientales y construyeron una ciudad al estilo de Longzhou.",
  ui_story_5038_50380001_71_dialog_content = "A partir de entonces, Lin Guild se estableció y vivió junto a los lugareños en armonía hasta el día de hoy.",
  ui_story_5038_50380001_72_dialog_content = "Así que ese es Twin Pavilions Bay, nuestro destino.",
  ui_story_5038_50380001_73_dialog_content = "¡Vaya, una ciudad construida por comerciantes! Nunca antes había visto un lugar así.",
  ui_story_5038_50380001_74_dialog_content = "¿Será realmente caro allí? No tenemos muchos ahorros.",
  ui_story_5038_50380001_75_dialog_content = "Escuché que en lugares ricos, tienes que pagar por estacionar vehículos y esas cosas. ¿Te imaginas cuánto costaría aparcar algo como Soroz?",
  ui_story_5038_50380001_76_dialog_content = "Bueno, no me preocuparía por las tarifas de estacionamiento, pero para evitar problemas innecesarios...",
  ui_story_5038_50380001_77_dialog_content = "Recomendaría aterrizar a Soroz en algún lugar fuera de la ciudad, PlayerName.",
  ui_story_5038_50380001_78_dialog_content = "Buen punto.",
  ui_story_5038_50380001_79_dialog_content = "¡Mirar! ¡Creo que ya casi llegamos!",
  ui_story_5038_50380001_80_dialog_content = "Vaya... ¡Incluso las calles son hermosas!",
  ui_story_5038_50380001_81_dialog_content = "¡Sí! ¡Hay rojo por todas partes, tan bonito!",
  ui_story_5038_50380001_82_dialog_content = "Parece un lugar muy alegre y animado.",
  ui_story_5038_50380001_83_dialog_content = "Sí. Según los libros, toda la ciudad tiene el estilo de un continente completamente diferente.",
  ui_story_5038_50380001_84_dialog_content = "En algún lugar al otro lado del océano, así es como se ven sus casas y calles.",
  ui_story_5038_50380001_85_dialog_content = "Es como si el continente del otro lado fuera un mundo completamente diferente.",
  ui_story_5038_50380001_86_dialog_content = "¡Y apuesto a que también tienen vacaciones totalmente diferentes!",
  ui_story_5038_50380001_87_dialog_content = "Todo este papel rojo que estoy entregando estos días debe ser para el festival tradicional.",
  ui_story_5038_50380001_88_dialog_content = "¿Cómo se llamaba de nuevo...?",
  ui_story_5038_50380001_89_dialog_content = "¡Feliz año nuevo! ¿Estás aquí para el Festival de Primavera?",
  ui_story_5038_50380001_90_dialog_content = "¡Oh sí! ¡Se llama el Festival Spwing!",
  ui_story_5038_50380001_91_dialog_content = "No tenemos muchas caras desconocidas en Twin Pavilions Bay en estos días. ¿Eres de fuera de la ciudad?",
  ui_story_5038_50380001_92_dialog_content = "Puedo decirlo con solo mirar tu ropa.",
  ui_story_5038_50380001_93_dialog_content = "Momento perfecto, señor! Aquí está el papel rojo que ordenó su tienda. ¡Por favor, firme aquí!",
  ui_story_5038_50380001_94_dialog_content = "Oh gracias. ¡Y ahí estaba yo, preocupada de que no llegara a tiempo!",
  ui_story_5038_50380001_95_dialog_content = "Disculpe por preguntar, pero me preguntaba por qué ordenó tanto papel rojo de Umbraton.",
  ui_story_5038_50380001_96_dialog_content = "Son importantes para dar la bienvenida al nuevo año.",
  ui_story_5038_50380001_97_dialog_content = "Es una tradición en Longzhou colgar dos pedazos de papel rojo con la palabra \"Bendición\" en sus puertas para el Festival de Primavera.",
  ui_story_5038_50380001_98_dialog_content = "Nos ayudan a orar por buena suerte y prosperidad en el año que viene.",
  ui_story_5038_50380001_99_dialog_content = "Longzhou, ¿es ese el nombre del continente oriental?",
  ui_story_5038_50380001_100_dialog_content = "Correcto. Parece que ustedes no están muy familiarizados con muchos de nosotros.",
  ui_story_5038_50380001_101_dialog_content = "Aquellos de nosotros que vivimos aquí en Twin Pavilions Bay somos bastante autosuficientes y no interactuamos a menudo con lugares más al interior.",
  ui_story_5038_50380001_102_dialog_content = "Podríamos haber comprado fácilmente, y lo habríamos hecho, este papel rojo en nuestras propias tiendas locales.",
  ui_story_5038_50380001_103_dialog_content = "Pero este año... hubo un poco de situación.",
  ui_story_5038_50380001_104_dialog_content = "¿Qué tipo de situación?",
  ui_story_5038_50380001_105_dialog_content = "Nuestras tiendas están completamente agotadas. No solo del papel, sino de todo, incluidas las necesidades.",
  ui_story_5038_50380001_106_dialog_content = "¿Cómo es que... te has quedado sin reservas?",
  ui_story_5038_50380001_107_dialog_content = "Por lo general, el Lin Guild <color=#FFB400>barco de suministro</color> viene una vez cada pocos meses desde Longzhou.",
  ui_story_5038_50380001_108_dialog_content = "Pero no hemos visto ningún rastro de él durante el último medio año. No tenemos idea de lo que ha pasado.",
  ui_story_5038_50380001_109_dialog_content = "Las tiendas que dependen del barco de suministro para comprar inventario no pueden aguantar para siempre.",
  ui_story_5038_50380001_110_dialog_content = "El papel rojo es parte de lo que falta. Así que no tuvimos más remedio que pedir algunos de Umbraton.",
  ui_story_5038_50380001_111_dialog_content = "(Ah, entonces eso es lo que pasó. Suena preocupante...)",
  ui_story_5038_50380001_112_dialog_content = "(El Lin Guild incluso me ayudó antes, pero no tengo idea de cómo les va).",
  ui_story_5038_50380001_113_dialog_content = "Oh... Conozco el sentimiento. Debe extrañar mucho el sabor del hogar, señor.",
  ui_story_5038_50380001_114_dialog_content = "<color=#e8d9bb>BOCINA... BOCINA...</color>",
  ui_story_5038_50380001_115_dialog_content = "¿Qué es eso?",
  ui_story_5038_50380001_116_dialog_content = "Suena como una bocina que viene del puerto...",
  ui_story_5038_50380001_117_dialog_content = "¡Eso es... la sirena de niebla de un barco!",
  ui_story_5038_50380001_118_dialog_content = "¡Seguro es! ¡Reconocería una sirena de niebla en cualquier lugar!",
  ui_story_5038_50380001_119_dialog_content = "¡Hay un barco en el puerto! ¿Podría ser el Lin Guild?",
  ui_story_5038_50380001_120_dialog_content = "¿Es el barco de suministro de Lin Guild?",
  ui_story_5038_50380001_121_dialog_content = "Parece que hemos llegado en el momento justo.",
  ui_story_5038_50380001_122_dialog_content = "¡Es el barco de suministro, realmente lo es!",
  ui_story_5038_50380001_123_dialog_content = "¡Oh, gracias a Dios! ¡Me preocupaba no poder conseguir nada para el Festival de Primavera!",
  ui_story_5038_50380001_124_dialog_content = "¡Alguien viene!",
  ui_story_5038_50380001_125_dialog_content = "...",
  ui_story_5038_50380001_126_dialog_content = "(Hay un hombre extraño allí, que no parece ni un poco emocionado).",
  ui_story_5038_50380001_127_dialog_content = "¡Fuera del camino! ¡Déjalo pasar! ¡Haz espacio para el viejo, débil, enfermo y discapacitado!",
  ui_story_5038_50380001_128_dialog_content = "¡Tú, joven! ¡Estás bloqueando las ruedas!",
  ui_story_5038_50380001_129_dialog_content = "E-Esa cosa en la que está sentado es... ¡¿una silla de ruedas?!",
  ui_story_5038_50380001_130_dialog_content = "¡Lo siento! ¿Donde estan mis modales?",
  ui_story_5038_50380001_131_dialog_content = "No te molestes. Te lo he dicho muchas veces, Liqing, muchacho, no me etiquetes todo eso...",
  ui_story_5038_50380001_132_dialog_content = "Todavía no estoy muerto, mi cerebro está funcionando bien.",
  ui_story_5038_50380001_133_dialog_content = "Jajajaja! ¡Solo quería que atravesáramos la multitud más rápido!",
  ui_story_5038_50380001_134_dialog_content = "¡He estado esperando por siempre para comprar las increíbles hierbas medicinales de Longzhou!",
  ui_story_5038_50380001_135_dialog_content = "¡Déjame pasar! ¡Yo primero! ¡Traje Nightium!",
  ui_story_5038_50380001_136_dialog_content = "¡Ascender! ¡Continuar!",
  ui_story_5038_50380001_137_dialog_content = "¿Eh? ¡No empujes!",
  ui_story_5038_50380001_138_dialog_content = "Silencio, todos.",
  ui_story_5038_50380001_139_dialog_content = "...",
  ui_story_5038_50380001_140_dialog_content = "Shadowind realmente ha tenido un cambio de imagen. Incluso el capitán es una cara nueva.",
  ui_story_5038_50380001_141_dialog_content = "Soy Yuebai, el nuevo capitán del barco mercante del Lin Guild, el Shadowind.",
  ui_story_5038_50380001_142_dialog_content = "... Parece que todos ustedes reconocen a los miembros de Lin que normalmente viajan con este barco.",
  ui_story_5038_50380001_143_dialog_content = "El último medio año vio algunos cambios estratégicos en la familia Lin, lo que resultó en que no pudieran enviar el barco al mar.",
  ui_story_5038_50380001_144_dialog_content = "Estoy seguro de que la separación de la ruta entre Longzhou y Astra durante tanto tiempo ha sido difícil.",
  ui_story_5038_50380001_145_dialog_content = "Pero eso es ahora todo en el pasado. Ahora que Shadowind me tiene al timón,",
  ui_story_5038_50380001_146_dialog_content = "la ruta Longzhou-Astra será oficialmente <color=#FFB400>reanudar el negocio</color>.",
  ui_story_5038_50380001_147_dialog_content = "... ¡Realmente lo hicieron, Zhong Xu! ¡De verdad vinieron!",
  ui_story_5038_50380001_148_dialog_content = "¡Ya podemos volver!",
  ui_story_5038_50380001_149_dialog_content = "...",
  ui_story_5038_50380001_150_dialog_content = "¿Podemos volver a Longzhou? ¿Así? Pero no me he preparado...",
  ui_story_5038_50380001_151_dialog_content = "Sí, ya tengo reuniones programadas con mis socios comerciales. Dudo que pueda salir de ellos...",
  ui_story_5038_50380001_152_dialog_content = "Cualquiera que desee regresar a Longzhou solo necesita comprar un boleto.",
  ui_story_5038_50380001_153_dialog_content = "Sin embargo, debido a que la ruta de regreso ha cambiado, tenga en cuenta ciertas <color=#FFB400>riesgos</color>.",
  ui_story_5038_50380001_154_dialog_content = "¡Olvida eso! ¡Cualquier nave Lin es confiable! ¡Tres boletos para mí, por favor!",
  ui_story_5038_50380001_155_dialog_content = "¡Dame uno primero! No quiero tener que pelear por ellos...",
  ui_story_5038_50380001_156_dialog_content = "Por favor, todos, cálmense. No hay necesidad de entrar en pánico.",
  ui_story_5038_50380001_157_dialog_content = "Todavía queda un tiempo antes de nuestro viaje de regreso.",
  ui_story_5038_50380001_158_dialog_content = "Me di cuenta de que todos aquí eran buenas personas desde el momento en que desembarqué.",
  ui_story_5038_50380001_159_dialog_content = "¿Algún caballero o mujer desearía que mi humilde yo leyera su fortuna, tal vez ilumine un poco su camino?",
  ui_story_5038_50380001_160_dialog_content = "Y Tianxian, el estafador, ataca de nuevo, engañando a la gente con su lengua de plata...",
  ui_story_5038_50380001_161_dialog_content = "¡Por qué, princesa Dantang! Uno no es mentiroso, te lo aseguro.",
  ui_story_5038_50380001_162_dialog_content = "... ¡Cuidado, princesa!",
  ui_story_5038_50380001_163_dialog_content = "¡Oooooooh!",
  ui_story_5038_50380001_164_dialog_content = "¡Guau! ¡Shadowind se ve incluso mejor que antes!",
  ui_story_5038_50380001_165_dialog_content = "Mucho más espacioso también...",
  ui_story_5038_50380001_166_dialog_content = "Jejeje... Reflejos impresionantemente rápidos, Jiu.",
  ui_story_5038_50380001_167_dialog_content = "<color=#e8d9bb>*multitud murmurando*</color>",
  ui_story_5038_50380001_168_dialog_content = "Suspiro...",
  ui_story_5038_50380001_169_dialog_content = "¿Estás bien, Piolín?",
  ui_story_5038_50380001_170_dialog_content = "Yo también quiero ir a ver a Shadowind...",
  ui_story_5038_50380001_171_dialog_content = "Apuesto a que hay montones de cosas geniales para ver.",
  ui_story_5038_50380001_172_dialog_content = "¿Quieres decir así, pequeño mensajero?",
  ui_story_5038_50380001_173_dialog_content = "¡¡GUAU!! ¡Una pila enorme de papel de vaca rojo!",
  ui_story_5038_50380001_174_dialog_content = "Eso es wight! Eso es justo lo que estoy buscando!",
  ui_story_5038_50380001_175_dialog_content = "Escuché que Twin Pavilions Bay se estaba quedando sin suministros incluso antes de que nos fuéramos, con el Festival de Primavera acercándose rápidamente, nada menos.",
  ui_story_5038_50380001_176_dialog_content = "No tuvieron más remedio que obtener suministros de los gremios del interior y luego organizar un grupo de mensajeros para entregar todo.",
  ui_story_5038_50380001_177_dialog_content = "Sin embargo, ahora que el periódico de Longzhou está aquí, las cosas no serán tan complicadas para ti.",
  ui_story_5038_50380001_178_dialog_content = "<size=50>¡HURRA! ¡¡Ya estoy libre!!</size>",
  ui_story_5038_50380001_179_dialog_content = "Tweety finalmente está fuera del reloj.",
  ui_story_5038_50380001_180_dialog_content = "¿Son ustedes tres del interior de Astra?",
  ui_story_5038_50380001_181_dialog_content = "Puedes darte cuenta con solo mirar nuestra ropa, ¿verdad?",
  ui_story_5038_50380001_182_dialog_content = "Espero su hospitalidad, entonces.",
  ui_story_5038_50380001_183_dialog_content = "Shadowind permanecerá en las aguas de Astra por un tiempo.",
  ui_story_5038_50380001_184_dialog_content = "Vamos a conocernos durante este tiempo.",
  ui_story_5038_50380001_185_dialog_content = "(¡Wow! ¡Qué mujer tan estoica e imponente!)",
  ui_story_5038_50380001_186_dialog_content = "S-Claro. Yo soy PlayerName.",
  ui_story_5038_50380001_187_dialog_content = "¡Bienvenidos a Astra, invitados de Longzhou!",
  ui_story_5038_50380101_1_dialog_content = "<color=#e8d9bb>Twin Pavilions Bay Calles</color>",
  ui_story_5038_50380101_2_dialog_content = "(Nuestro tiempo aquí ha sido como unas largas y raras vacaciones...)",
  ui_story_5038_50380101_3_dialog_content = "(Twin Pavilions Bay es un lugar tan relajante durante el Festival de Primavera).",
  ui_story_5038_50380101_4_dialog_content = "¿En qué estás pensando? PlayerName?",
  ui_story_5038_50380101_5_dialog_content = "Estaba pensando en lo rápido que pasa el tiempo. Ni siquiera sé cuánto tiempo hemos estado aquí.",
  ui_story_5038_50380101_6_dialog_content = "Sí. Llevo un diario muy detallado.",
  ui_story_5038_50380101_7_dialog_content = "Déjeme ver... PlayerName y Tianxian pasó los primeros tres días deambulando por la Calle de Bocadillos Especiales del Este...",
  ui_story_5038_50380101_8_dialog_content = "Pasamos los días cuatro a seis participando en varios juegos de ajedrez de Twin Pavilions Bay...",
  ui_story_5038_50380101_9_dialog_content = "Días siete a diez, perdiendo miserablemente en el concurso de caligrafía del Festival de Primavera de Dantang...",
  ui_story_5038_50380101_10_dialog_content = "Días diez a quince—",
  ui_story_5038_50380101_11_dialog_content = "Está bien, está bien... ¡Eso servirá!",
  ui_story_5038_50380101_12_dialog_content = "De todos modos, probablemente deberíamos empezar a planificar nuestra partida pronto.",
  ui_story_5038_50380101_13_dialog_content = "Tome todo el tiempo que sea necesario, PlayerName... Pero tengo que irme a Illumina mañana.",
  ui_story_5038_50380101_14_dialog_content = "¿Qué? ¡¿Muy pronto?!",
  ui_story_5038_50380101_15_dialog_content = "Bueno, es hora de que la cadena de suministro especial de invierno de Illumina se ponga en marcha.",
  ui_story_5038_50380101_16_dialog_content = "Tengo que ir a ayudar con la distribución.",
  ui_story_5038_50380101_17_dialog_content = "Y debo ir a Northland según la tradición, para pasar el año nuevo con la Reina Belén.",
  ui_story_5038_50380101_18_dialog_content = "Si no ha habido ningún retraso, mi entrenador de Northland debería llegar aquí esta noche.",
  ui_story_5038_50380101_19_dialog_content = "¿Tú también, Carleen?",
  ui_story_5038_50380101_20_dialog_content = "Bueno, hasta luego, vacaciones. Ha sido divertido...",
  ui_story_5038_50380101_21_dialog_content = "¡Guau! ¡Mira a quién encontre!",
  ui_story_5038_50380101_22_dialog_content = "¡Buenos días, señor navegante, señorita antivicio, señorita Carween!",
  ui_story_5038_50380101_23_dialog_content = "¡Mañana Piolín!",
  ui_story_5038_50380101_24_dialog_content = "¿Cómo va el trabajo? ¿Sigues ocupado?",
  ui_story_5038_50380101_25_dialog_content = "¡Bien ahora! ¡Ya de vuelta a la normalidad!",
  ui_story_5038_50380101_26_dialog_content = "¡Solo hay una cosa que tejer para dewiver!",
  ui_story_5038_50380101_27_dialog_content = "¿Aún necesitas ayuda? Todavía tengo tiempo antes de tener que despegar.",
  ui_story_5038_50380101_28_dialog_content = "¡Gracias, señorita Vice, pero tengo esto! ¿Y adivina qué?",
  ui_story_5038_50380101_29_dialog_content = "Compré un <color=#FFB400>boleto</color> para el Shadowind!",
  ui_story_5038_50380101_30_dialog_content = "¿Lo agradecerías? ¡Esta es una carta de larga distancia! ¡Necesita ser entregado a Longzhou!",
  ui_story_5038_50380101_31_dialog_content = "¡Tuve mucho cuidado de despojar a todos los demás antes, para no perder el barco!",
  ui_story_5038_50380101_32_dialog_content = "Parece una gran oportunidad para viajar.",
  ui_story_5038_50380101_33_dialog_content = "Jeje! ¡Estoy deseando que llegue!",
  ui_story_5038_50380101_34_dialog_content = "Parece que todo lo que se puede hablar recientemente es la partida inminente de Shadowind.",
  ui_story_5038_50380101_35_dialog_content = "Sí, algunas personas están un poco ansiosas.",
  ui_story_5038_50380101_36_dialog_content = "Ya sabes... tengo el <color=#FFB400>primicia interior</color> ¡sobre por qué los Lin tuvieron que suspender sus rutas durante seis meses!",
  ui_story_5038_50380101_37_dialog_content = "Eh... ¿quién eres?",
  ui_story_5038_50380101_38_dialog_content = "¡Oh, lo recuerdo! ¡Eres el tipo bueno que ayudó al viejo en la silla de ruedas!",
  ui_story_5038_50380101_39_dialog_content = "¡Ja ja! ¡No soy solo un tipo agradable! Zhong Xu es mi amigo, además de mi paciente.",
  ui_story_5038_50380101_40_dialog_content = "Éramos pasajeros juntos en el mismo barco cuando llegamos de Longzhou.",
  ui_story_5038_50380101_41_dialog_content = "Mi nombre es Liqing. ¡Soy un médico de gatos errante, dando vueltas y salvando vidas!",
  ui_story_5038_50380101_42_dialog_content = "¡Miaauu!",
  ui_story_5038_50380101_43_dialog_content = "¡Waah!",
  ui_story_5038_50380101_44_dialog_content = "¡E-E-Eso es un gatito!",
  ui_story_5038_50380101_45_dialog_content = "¡Vamos, Tinytail, compórtate! Lo siento, solo estaba jugando.",
  ui_story_5038_50380101_46_dialog_content = "Ven aquí, Tinytail.",
  ui_story_5038_50380101_47_dialog_content = "Está claro que prefiere mi compañía a la tuya.",
  ui_story_5038_50380101_48_dialog_content = "Solo por todos los otros gatos que andan a tu alrededor...",
  ui_story_5038_50380101_49_dialog_content = "Disculpe, estoy aquí para confirmar los detalles del pasajero.",
  ui_story_5038_50380101_50_dialog_content = "¿Podrían los presentes, que son Tweety, Zhong Xu y Liqing, confirmar su reserva de regreso a Longzhou?",
  ui_story_5038_50380101_51_dialog_content = "¡Sip!",
  ui_story_5038_50380101_52_dialog_content = "Muy bien. Antes de partir, tengo algunos anuncios más.",
  ui_story_5038_50380101_53_dialog_content = "Residentes de Longzhou, estoy seguro de que han oído hablar de la legendaria brújula oceánica de la familia Lin.",
  ui_story_5038_50380101_54_dialog_content = "Solían depender de este objeto para mantener su supremacía marítima.",
  ui_story_5038_50380101_55_dialog_content = "Desafortunadamente, este tesoro único se perdió y hasta ahora aún no se ha recuperado.",
  ui_story_5038_50380101_56_dialog_content = "Mencioné esto antes, pero asegúrese de comprender los riesgos de nuestro viaje inminente.",
  ui_story_5038_50380101_57_dialog_content = "Realmente no tenemos ninguna experiencia navegando sin la brújula, por lo que, en cierto modo, será una aventura marítima.",
  ui_story_5038_50380101_58_dialog_content = "Tuvimos condiciones favorables en el camino aquí, lo que hizo que el viaje fuera seguro y sin incidentes.",
  ui_story_5038_50380101_59_dialog_content = "Sin embargo, no puedo garantizar que el viaje de regreso sea el mismo. Necesito asegurarme de que todos los pasajeros sean plenamente conscientes de esto.",
  ui_story_5038_50380101_60_dialog_content = "personalmente, lo haría <color=#FFB400>no aconsejar</color> abordar el Shadowind sin una buena razón.",
  ui_story_5038_50380101_61_dialog_content = "(¿Fue este uno de los incidentes con los que los Lin estuvieron lidiando el último medio año...?)",
  ui_story_5038_50380101_62_dialog_content = "¡No estoy asustado! ¡Creo en la señorita Yuebai!",
  ui_story_5038_50380101_63_dialog_content = "Eres un atrevido, ¿no?",
  ui_story_5038_50380101_64_dialog_content = "Tal vez sea una coincidencia, pero como he estado diciéndoles a todos sobre esto...",
  ui_story_5038_50380101_65_dialog_content = "Cada persona que tenía un boleto cancelado de inmediato.",
  ui_story_5038_50380101_66_dialog_content = "Algunos decían que tenían que quedarse por motivos familiares, otros que había habido un cambio repentino de planes.",
  ui_story_5038_50380101_67_dialog_content = "Sospecho que es porque nadie está realmente dispuesto a arriesgar sus vidas, cuando se trata de empujar.",
  ui_story_5038_50380101_68_dialog_content = "Pero en ese caso, ¡usted también está arruinando su vida, señorita Yuebai!",
  ui_story_5038_50380101_69_dialog_content = "... Tengo fe en mi capacidad para manejar las cosas. Y de todos modos, este es mi trabajo.",
  ui_story_5038_50380101_70_dialog_content = "No pareces estar particularmente lleno de confianza.",
  ui_story_5038_50380101_71_dialog_content = "¿No tienes curiosidad acerca de dónde <color=#FFB400>La brújula</color> ¿terminó?",
  ui_story_5038_50380101_72_dialog_content = "?!?",
  ui_story_5038_50380101_73_dialog_content = "¿Eres uno de los Lins? O...",
  ui_story_5038_50380101_74_dialog_content = "¡Es genial, señora capitana! En realidad estuvimos allí durante el <color=#FFB400>incidente</color> hace seis meses.",
  ui_story_5038_50380101_75_dialog_content = "Imposible... Que yo sepa, ni un alma logró escapar de las garras de los piratas...",
  ui_story_5038_50380101_76_dialog_content = "Si ni siquiera lo sabías, ¡entonces los piratas ciertamente no lo sabrían!",
  ui_story_5038_50380101_77_dialog_content = "Y de todos modos, estoy bastante seguro de que no fuimos solo yo y el viejo Zhong Xu quienes no caímos a las profundidades del océano en ese entonces.",
  ui_story_5038_50380101_78_dialog_content = "Usted es el Sr. Zhong Xu, supongo.",
  ui_story_5038_50380101_79_dialog_content = "Sí, señora.",
  ui_story_5038_50380101_80_dialog_content = "El Guildmaster ha estado muy preocupado por su seguridad. Le complacerá saber que estás viva.",
  ui_story_5038_50380101_81_dialog_content = "Jeje, así que se las arregló para escapar también, ¿eh?",
  ui_story_5038_50380101_82_dialog_content = "Eres un capitán notablemente valiente. Admiro tu tenacidad en retomar la ruta.",
  ui_story_5038_50380101_83_dialog_content = "¡Me imagino que no estás aquí solo en un viaje de entrega de mercancías! ¿Seguro que tu misión es buscar también a La Brújula?",
  ui_story_5038_50380101_84_dialog_content = "... Correcto.",
  ui_story_5038_50380101_85_dialog_content = "Si aún está decidido a subir a bordo, por favor, ayúdeme.",
  ui_story_5038_50380101_86_dialog_content = "¡Por supuesto! Hablemos más una vez que estemos a bordo, no deberíamos dejar a nuestros invitados del interior parados aquí.",
  ui_story_5038_50380101_87_dialog_content = "¿Te refieres a nosotros? No nos hagas caso, de verdad...",
  ui_story_5038_50380101_88_dialog_content = "De todos modos, partimos dentro de dos días. Supongo que te veré entonces, en el puerto.",
  ui_story_5038_50380101_89_dialog_content = "<color=#e8d9bb>Dos días después</color>",
  ui_story_5038_50380101_90_dialog_content = "Vaya, si no lo es PlayerName!",
  ui_story_5038_50380101_91_dialog_content = "Ven a despedirnos, ¿verdad?",
  ui_story_5038_50380101_92_dialog_content = "Así un poco. Carleen y Vice ya se fueron, pero querían que les pasara un mensaje.",
  ui_story_5038_50380101_93_dialog_content = "\"Le deseamos un viaje tranquilo y seguro, y esperamos que vuelva a visitar Astra pronto\".",
  ui_story_5038_50380101_94_dialog_content = "Eso es básicamente lo que quería decir también.",
  ui_story_5038_50380101_95_dialog_content = "Sé que nos conocimos hace poco, pero todavía me entristece un poco que tengamos que despedirnos tan pronto.",
  ui_story_5038_50380101_96_dialog_content = "Jeje... Ustedes, la gente de Astra, siempre llevan el corazón en la manga.",
  ui_story_5038_50380101_97_dialog_content = "Princesa Dantang, ¿le gustaría tratar de decir algo en respuesta?",
  ui_story_5038_50380101_98_dialog_content = "Eh... ¿M-Yo? Oh...",
  ui_story_5038_50380101_99_dialog_content = "Yo también te recordaré con cariño, PlayerName.",
  ui_story_5038_50380101_100_dialog_content = "Zhong Xu y Tianxian ya están a bordo. Nosotros también deberíamos irnos.",
  ui_story_5038_50380101_101_dialog_content = "¡Vaya! Eso me recuerda... ¿Dónde está ese pajarito blanco del otro día?",
  ui_story_5038_50380101_102_dialog_content = "... ¿Derecho? Yo también quería despedirme de Piolín.",
  ui_story_5038_50380101_103_dialog_content = "<size=50>Wahhhhhhhh—</size>",
  ui_story_5038_50380101_104_dialog_content = "<size=50>PlayerName! ¡H-Ayúdame!</size>",
  ui_story_5038_50380101_105_dialog_content = "¡Ay! ¡Ahí estás, Piolín!",
  ui_story_5038_50380101_106_dialog_content = "¡No puedo terminar de entregar todas mis publicaciones!",
  ui_story_5038_50380101_107_dialog_content = "¡De repente recibí una entrega urgente en Northland! ¡La Unión Couwier no puede enviar a nadie más!",
  ui_story_5038_50380101_108_dialog_content = "Está sibilante en esas partes, y la visibilidad es muy baja. ¡Soy el único lo suficientemente familiarizado con el área!",
  ui_story_5038_50380101_109_dialog_content = "Entonces... ¿Estás diciendo que...",
  ui_story_5038_50380101_110_dialog_content = "Así que... vine a preguntarte si me ayudarías de nuevo, PlayerName?",
  ui_story_5038_50380101_111_dialog_content = "¡Estaba pensando que podría contratarte para que fueras a Wongzhou por mí!",
  ui_story_5038_50380101_112_dialog_content = "¡Puedo pagar! ¡Espera hasta que tenga el Salawy del próximo mes! ¡Te lo daré todo!",
  ui_story_5038_50380101_113_dialog_content = "(Esto suena familiar...)",
  ui_story_5038_50380101_114_dialog_content = "¡Me encantaría ayudarte, de verdad, y el dinero no es importante!",
  ui_story_5038_50380101_115_dialog_content = "Pero la cosa es, ¿tu boleto es transferible?",
  ui_story_5038_50380101_116_dialog_content = "¿Qué pasa?",
  ui_story_5038_50380101_117_dialog_content = "¡¡Señorita Yuebai!!",
  ui_story_5038_50380101_118_dialog_content = "Oh... Mmhmm... Entiendo.",
  ui_story_5038_50380101_119_dialog_content = "Normalmente, los boletos no son reembolsables ni transferibles.",
  ui_story_5038_50380101_120_dialog_content = "Oh... Ya veo...",
  ui_story_5038_50380101_121_dialog_content = "Iré a pedirle ayuda a uno de los pasajeros del barco...",
  ui_story_5038_50380101_122_dialog_content = "Sin embargo, como capitán, estaría encantado de invitarle a bordo. PlayerName.",
  ui_story_5038_50380101_123_dialog_content = "¡¿Eh?! Es una sorpresa agradable, pero repentina...",
  ui_story_5038_50380101_124_dialog_content = "Tienes que agradecerle a Zhong Xu por esto.",
  ui_story_5038_50380101_125_dialog_content = "Solo decidí buscar The Compass nuevamente, desde nuestra conversación hace un par de días.",
  ui_story_5038_50380101_126_dialog_content = "Zhong Xu dijo que las cosas podrían ir un poco más tranquilas con la ayuda de Caelestite.",
  ui_story_5038_50380101_127_dialog_content = "(¿Ir más suave...? ¿Se supone que mi habilidad psíquica puede sentir tal objeto?)",
  ui_story_5038_50380101_128_dialog_content = "Al menos podemos aprovechar nuestra experiencia viniendo aquí para el viaje de regreso.",
  ui_story_5038_50380101_129_dialog_content = "También tenemos a Zhong Xu y Liqing con nosotros, que estaban allí cuando desapareció The Compass.",
  ui_story_5038_50380101_130_dialog_content = "La princesa Dantang, Jiu y Tianxian harán todo lo posible para mantener el barco a salvo.",
  ui_story_5038_50380101_131_dialog_content = "Si confías en mí para navegar, agradecería tu ayuda.",
  ui_story_5038_50380101_132_dialog_content = "(Tuve varios encuentros con Lin Guild en el pasado, e incluso me hice amigo de varios de ellos...)",
  ui_story_5038_50380101_133_dialog_content = "(Así que esta vez si puedo serles de ayuda...)",
  ui_story_5038_50380101_134_option_content = "¡Lo haré!",
  ui_story_5038_50380101_135_dialog_content = "Gracias por estar tan dispuesto, PlayerName. Te espero a bordo.",
  ui_story_5038_50380101_136_dialog_content = "¡G-Gracias, Sr. Navegante!",
  ui_story_5038_50380101_137_dialog_content = "¿Que estas esperando? ¡Vamos arriba!",
  ui_story_5038_50380101_138_dialog_content = "¡A-bien! ¡Ya voy!",
  ui_story_5038_50380101_139_dialog_content = "¡Miau!",
  ui_story_5038_50380101_140_dialog_content = "¡Oh! Tinytail ve peces!",
  ui_story_5038_50380101_141_dialog_content = "No, Colita. ¡No saltar!",
  ui_story_5038_50380101_142_dialog_content = "Miau...",
  ui_story_5038_50380101_143_dialog_content = "Los vientos de Astra parecen ser mucho más fuertes que los de Longzhou...",
  ui_story_5038_50380101_144_dialog_content = "Simplemente perfecto para zarpar.",
  ui_story_5038_50380101_145_dialog_content = "Ya está cogiendo las velas del Shadowind. Parece ser del... suroeste.",
  ui_story_5038_50380101_146_dialog_content = "Voy a limpiar las cubiertas. ¡Por favor, siéntense tranquilos, todos!",
  ui_story_5038_50380101_147_dialog_content = "¡Shadowind, zarpa!",
  ui_story_5038_50380201_1_dialog_content = "(¡Qué barco tan increíble! Es más grande que cualquiera en el que haya estado).",
  ui_story_5038_50380201_2_dialog_content = "(Incluso el diseño de la cubierta es rico en carácter del Lejano Oriente).",
  ui_story_5038_50380201_3_dialog_content = "(La vista también es magnífica...)",
  ui_story_5038_50380201_4_dialog_content = "(¡Ahhh! Cielos azules, olas, brisa marina...)",
  ui_story_5038_50380201_5_dialog_content = "¿Ah?",
  ui_story_5038_50380201_6_dialog_content = "Zhong Xu, ¿por qué estás aquí solo, mirando al mar, perdido en tus pensamientos?",
  ui_story_5038_50380201_7_dialog_content = "Estoy mirando las olas.",
  ui_story_5038_50380201_8_dialog_content = "¿Hay... algo que ver allí?",
  ui_story_5038_50380201_9_dialog_content = "Las olas del océano son las mismas, vayas donde vayas. Y así, mirarlos me recuerda a mi hogar.",
  ui_story_5038_50380201_10_dialog_content = "Debes extrañarlo mucho.",
  ui_story_5038_50380201_11_dialog_content = "Oh, eso me recuerda. Antes de irnos, tenía la impresión de que muchos de los residentes a largo plazo de Twin Pavilions Bay vendrían con nosotros.",
  ui_story_5038_50380201_12_dialog_content = "Nunca hubiera esperado que terminaran siendo solo tú y Liqing a bordo.",
  ui_story_5038_50380201_13_dialog_content = "Cuando deambulas demasiado tiempo en tierras extranjeras, a menudo deseas volver a casa.",
  ui_story_5038_50380201_14_dialog_content = "Los que devolvieron sus boletos aún extrañan su tierra natal, pero las semillas de pertenencia ya echaron raíces para ellos en Twin Pavilions Bay.",
  ui_story_5038_50380201_15_dialog_content = "Ahora tienen familia en Twin Pavilions Bay y nuevos amigos. La nostalgia por su tierra natal es más nostalgia melancólica que otra cosa.",
  ui_story_5038_50380201_16_dialog_content = "Solo la gente como yo puede ir y venir tan libremente como el viento sin que nada los ate.",
  ui_story_5038_50380201_17_dialog_content = "Creo que entiendo lo que quieres decir...",
  ui_story_5038_50380201_18_dialog_content = "Je... joven amigo, me extraña que alguien tan joven sea feliz escuchando las divagaciones de un anciano.",
  ui_story_5038_50380201_19_dialog_content = "Disfruto conversar contigo, así que no es necesario que me trates como a tu superior.",
  ui_story_5038_50380201_20_dialog_content = "Espero que podamos ser amigos. Acabemos con las formalidades, ¿de acuerdo?",
  ui_story_5038_50380201_21_dialog_content = "Al igual que con Liqing, somos iguales.",
  ui_story_5038_50380201_22_dialog_content = "¡Gran! Me siento honrado y feliz de...",
  ui_story_5038_50380201_23_dialog_content = "<color=#e8d9bb>¡Chapoteo!</color>",
  ui_story_5038_50380201_24_dialog_content = "¡Whoa!",
  ui_story_5038_50380201_25_dialog_content = "¡¿Qué fue eso?! ¡Me acabo de empapar!",
  ui_story_5038_50380201_26_dialog_content = "Era un banco de peces.",
  ui_story_5038_50380201_27_dialog_content = "Si ves uno con una cola como la de una serpiente, entonces es un <color=#FFB400>pez serpiente</color>!",
  ui_story_5038_50380201_28_dialog_content = "E-Salieron de la nada... ¡Estoy asombrado de que el agua me salpique en la cara desde allí abajo!",
  ui_story_5038_50380201_29_dialog_content = "Bueno, eso es porque el invierno es cuando están más activos, ya que es su temporada de apareamiento.",
  ui_story_5038_50380201_30_dialog_content = "Se agrupan en escuelas y nadan en las profundidades del mar tan pronto como nacen.",
  ui_story_5038_50380201_31_dialog_content = "No importa qué tan lejos puedan nadar, cuando llega el invierno, invariablemente se fusionan con otras escuelas cercanas.",
  ui_story_5038_50380201_32_dialog_content = "Luego migran de regreso a los puertos de Longzhou, donde ponen sus huevos en las aguas poco profundas... Y el ciclo comienza de nuevo.",
  ui_story_5038_50380201_33_dialog_content = "¿Cómo es que sabes tanto sobre este pez?",
  ui_story_5038_50380201_34_dialog_content = "Jeje! Porque el pez serpiente es una especie sagrada para Lin Guild.",
  ui_story_5038_50380201_35_dialog_content = "¿Como un tótem?",
  ui_story_5038_50380201_36_dialog_content = "Si algo como eso. Los Lin esperan ser como esos peces, regresando sanos y salvos a su tierra natal después de cada viaje.",
  ui_story_5038_50380201_37_dialog_content = "Master Bu dice que se pueden cultivar brotes con potencial. Inteligente PlayerName!",
  ui_story_5038_50380201_38_dialog_content = "¡No seas tan condescendiente como si fueras el adulto aquí!",
  ui_story_5038_50380201_39_dialog_content = "No juzgues un libro por su portada, PlayerName. Quién sabe, podría ser el mayor aquí.",
  ui_story_5038_50380201_40_dialog_content = "Así que es mejor que te dirijas a mí con el respeto que mereces, jeje.",
  ui_story_5038_50380201_41_dialog_content = "¿Hmm? *Sniff sniff* ¡Huelo a pescado!",
  ui_story_5038_50380201_42_dialog_content = "Tal vez porque es la hora del almuerzo.",
  ui_story_5038_50380201_43_dialog_content = "Es nuestro primer día en el mar, así que necesitamos un poco de ánimo.",
  ui_story_5038_50380201_44_dialog_content = "Ven a probar un poco, PlayerName. Este es <color=#FFB400>pez ardilla</color>, una especialidad de Longzhou.",
  ui_story_5038_50380201_45_dialog_content = "Deshuesamos un pescado recién pescado y luego cortamos su carne en forma de sombreado cruzado. Luego se fríe hasta que esté crujiente y dorado, antes de finalmente cubrirse con una salsa agridulce...",
  ui_story_5038_50380201_46_dialog_content = "¡Esperar! ¡¿Con qué pescado lo hiciste?!",
  ui_story_5038_50380201_47_dialog_content = "Un pez serpiente. Es bastante delicioso y tierno.",
  ui_story_5038_50380201_48_dialog_content = "¡¡¿Qué?!!",
  ui_story_5038_50380201_49_dialog_content = "Jaja, te tengo! Estoy bromeando, era solo un pescado comercial ordinario de la bodega.",
  ui_story_5038_50380201_50_dialog_content = "Ven conmigo a la zona de pasajeros. Los demás ya están allí.",
  ui_story_5038_50380201_51_dialog_content = "<color=#e8d9bb>Cabina de pasajeros Shadowind</color>",
  ui_story_5038_50380201_52_dialog_content = "¡Guau! Tienes mucho talento, princesa Dantang. ¡Este pescado está perfectamente cocinado y sabe como en casa!",
  ui_story_5038_50380201_53_dialog_content = "No vale la pena aceptar los cumplidos de un estafador.",
  ui_story_5038_50380201_54_dialog_content = "De todos modos, Jiu preparó todos estos platos.",
  ui_story_5038_50380201_55_dialog_content = "La señorita ayudó mucho.",
  ui_story_5038_50380201_56_dialog_content = "¡Dudo que puedas encontrar otra relación empleador-empleado en todo Ji que sea tan respetuosa como estas dos!",
  ui_story_5038_50380201_57_dialog_content = "...",
  ui_story_5038_50380201_58_dialog_content = "Oh, lo siento, pero creo que la princesa preferiría no hablar de ese lugar.",
  ui_story_5038_50380201_59_dialog_content = "¿Por qué no les pedimos a los dos miembros del Lin Guild aquí que nos cuenten lo que sucedió? <color=#FFB400>ese día</color>.",
  ui_story_5038_50380201_60_dialog_content = "Om nom nom nom... ¡Delicioso!",
  ui_story_5038_50380201_61_dialog_content = "Aquí, Colita. ¡Tú también puedes tener un poco!",
  ui_story_5038_50380201_62_dialog_content = "¡Miau!",
  ui_story_5038_50380201_63_dialog_content = "Bueno, eso lo mantendrá ocupado por un tiempo.",
  ui_story_5038_50380201_64_dialog_content = "Si lo desea, Sr. Zhong.",
  ui_story_5038_50380201_65_dialog_content = "Me encantaría, capitán. Pero recuerde que ya ha pasado más de medio año, por lo que algunos de los detalles pueden ser un poco confusos.",
  ui_story_5038_50380201_66_dialog_content = "Pero, sin embargo, permítanme contar todo el calvario, de principio a fin.",
  ui_story_5038_50380201_67_dialog_content = "¡Justo lo que estaba esperando! Dondequiera que me lleven mis viajes, lo que más me gusta es escuchar las historias de la gente.",
  ui_story_5038_50380201_68_dialog_content = "Ah, pero la historia que estoy a punto de contar puede ser más oscura de lo que estás acostumbrado a escuchar.",
  ui_story_5038_50380201_69_dialog_content = "Técnicamente hablando, Liqing y yo no somos técnicamente Lins, aunque nuestro buen capitán ciertamente lo es.",
  ui_story_5038_50380201_70_dialog_content = "No hay necesidad de tal formalidad, mi señor.",
  ui_story_5038_50380201_71_dialog_content = "Con un apellido como Mu, ¿qué tipo de Lin soy realmente?",
  ui_story_5038_50380201_72_dialog_content = "¡Oh, mis disculpas! no pensé No quise llamar la atención sobre tu apellido.",
  ui_story_5038_50380201_73_dialog_content = "De todos modos, solo soy un viejo amigo de la familia Lin, donde Liqing fue un invitado durante mucho tiempo.",
  ui_story_5038_50380201_74_dialog_content = "En realidad, nuestras identidades fueron lo único que nos salvó la vida después del incidente.",
  ui_story_5038_50380201_75_dialog_content = "Entonces, ¿qué pasó hace seis meses?",
  ui_story_5038_50380201_76_dialog_content = "Todo comenzó y terminó con The Compass.",
  ui_story_5038_50380201_77_dialog_content = "Esta brújula es lo que permitió a Lins dominar el comercio marítimo, lo que naturalmente atrajo la atención maliciosa.",
  ui_story_5038_50380201_78_dialog_content = "Varios pequeños grupos se unieron bajo el liderazgo de uno de los gremios, con la intención de derrotar a los Lins.",
  ui_story_5038_50380201_79_dialog_content = "Sabían que no podían igualar el poder de los Lin, pero no tenían miedo de rebajarse a trucos sucios y tácticas desvergonzadas.",
  ui_story_5038_50380201_80_dialog_content = "Un día, Liqing y yo íbamos camino a un banquete en Lin Manor, al que asistieron muchos de los amigos más cercanos de la familia.",
  ui_story_5038_50380201_81_dialog_content = "Justo cuando la noche estaba en su apogeo, los ladrones irrumpieron con intenciones asesinas...",
  ui_story_5038_50380202_1_dialog_content = "¡Zhong Xu! ¡Aqui!",
  ui_story_5038_50380202_2_dialog_content = "¿Estás bien?",
  ui_story_5038_50380202_3_dialog_content = "Solo un rasguño, no es nada.",
  ui_story_5038_50380202_4_dialog_content = "Al menos logramos sacar al Guildmaster Lin de manera segura.",
  ui_story_5038_50380202_5_dialog_content = "¡¿El maestro del gremio está bien?! ¡Qué alivio!",
  ui_story_5038_50380202_6_dialog_content = "Escapó, pero los demás...",
  ui_story_5038_50380202_7_dialog_content = "Me temo que, después de esta noche, los Lin ya no tendrán presencia en el reino de los mercaderes.",
  ui_story_5038_50380202_8_dialog_content = "¿Cómo pudieron asaltar la mansión tan descaradamente?",
  ui_story_5038_50380202_9_dialog_content = "Eran matones a sueldo. No les importa el peligro.",
  ui_story_5038_50380202_10_dialog_content = "Alguien debe haber pagado generosamente para que arriesgaran sus vidas.",
  ui_story_5038_50380202_11_dialog_content = "Si no me equivoco, vinieron por The Compass.",
  ui_story_5038_50380202_12_dialog_content = "¿La brújula? Pero ni siquiera está en Lin Manor...",
  ui_story_5038_50380202_13_dialog_content = "Todavía no lo saben.",
  ui_story_5038_50380202_14_dialog_content = "Guildmaster Lin tiene un plan de contingencia para garantizar la seguridad de The Compass.",
  ui_story_5038_50380202_15_dialog_content = "Si falla... vengaré a los Lin.",
  ui_story_5038_50380202_16_dialog_content = "Sígueme, Liqing.",
  ui_story_5038_50380202_17_dialog_content = "Después de eso... Apenas escapamos con vida.",
  ui_story_5038_50380202_18_dialog_content = "Fue solo en ese momento que nos dimos cuenta de que su objetivo esa noche no era el maestro del gremio.",
  ui_story_5038_50380202_19_dialog_content = "Para salvaguardar The Compass y evitar que sea destruido o robado, Guildmaster Lin decidió que sus parientes cercanos se lo llevaran.",
  ui_story_5038_50380202_20_dialog_content = "El Compass fue cargado en un viejo barco, que inmediatamente salió del puerto y se dirigió a mar abierto. Fuimos con eso.",
  ui_story_5038_50380202_21_dialog_content = "¿Navegaron CON el Compás? No lo entiendo... ¿Seguramente es más peligroso en el mar?",
  ui_story_5038_50380202_22_dialog_content = "¿No sería mejor haberlo guardado bajo llave en una bóveda o algo así?",
  ui_story_5038_50380202_23_dialog_content = "Para algo nacido del mar, el mar es donde más seguro se está.",
  ui_story_5038_50380202_24_dialog_content = "¿Eh? ¿Qué quieres decir?",
  ui_story_5038_50380202_25_dialog_content = "Mientras The Compass esté guiando un barco, nunca se perderá y siempre habrá vientos favorables, aguas tranquilas y sin accidentes.",
  ui_story_5038_50380202_26_dialog_content = "Pero...",
  ui_story_5038_50380202_27_dialog_content = "Ah, pero The Compass aún desapareció, ¿no es así? ¿Es eso lo que iba a preguntar, capitán?",
  ui_story_5038_50380202_28_dialog_content = "No se perdió debido a los elementos.",
  ui_story_5038_50380202_29_dialog_content = "...",
  ui_story_5038_50380202_30_dialog_content = "Los piratas estaban pisándoles los talones al Shadowind.",
  ui_story_5038_50380202_31_dialog_content = "Los dos caímos por la borda en medio del alboroto y nunca volvimos a subir.",
  ui_story_5038_50380202_32_dialog_content = "Como sabes, esos pícaros nunca pusieron sus manos en The Compass. De lo contrario, la ruta marítima no habría estado cortada tanto tiempo.",
  ui_story_5038_50380202_33_dialog_content = "Poco después, tanto los piratas como nosotros quedamos atrapados en un <color=#FFB400>poderosa tempestad</color>.",
  ui_story_5038_50380202_34_dialog_content = "Todas las almas a bordo se perdieron, excepto el joven Liqing y yo.",
  ui_story_5038_50380202_35_dialog_content = "Fue también cuando mis piernas se lesionaron.",
  ui_story_5038_50380202_36_dialog_content = "¿En qué lugar sucedió todo esto?",
  ui_story_5038_50380202_37_dialog_content = "No tengo ni idea. No tengo el sentido de la orientación de un marinero.",
  ui_story_5038_50380202_38_dialog_content = "De todos modos, tal vez sea la naturaleza espiritual de un diablillo, pero Liqing me trajo a Astra.",
  ui_story_5038_50380202_39_dialog_content = "Espera... ¿Qué tipo de cosa es un <color=#FFB400>diabólico</color>?",
  ui_story_5038_50380202_40_dialog_content = "Bueno, eso no es educado, PlayerName. los amigos no son cosas.",
  ui_story_5038_50380202_41_dialog_content = "Déjame iluminarte. En resumen, los fiendlings son aurorianos como yo que tienen características animales.",
  ui_story_5038_50380202_42_dialog_content = "Mientras estamos en el tema, Tinytail es en realidad mi hermano mayor.",
  ui_story_5038_50380202_43_dialog_content = "Silbido-!",
  ui_story_5038_50380202_44_dialog_content = "Vaya. Creo que lo entiendo.",
  ui_story_5038_50380202_45_dialog_content = "(Básicamente son aurorianos con sangre semihumana, ¿no es así? Tal vez así es como llaman a los semihumanos en Longzhou).",
  ui_story_5038_50380202_46_dialog_content = "Según los registros de la familia Lin, perder The Compass es un evento sin precedentes.",
  ui_story_5038_50380202_47_dialog_content = "Aunque nunca lo he visto con mis propios ojos, he oído que es un tesoro que <color=#FFB400>vive y muere con su nave</color>.",
  ui_story_5038_50380202_48_dialog_content = "Todavía quiero intentarlo, todos. Incluso si solo encontramos un naufragio, al menos sabré dónde cayó.",
  ui_story_5038_50380202_49_dialog_content = "No deseo que nos encontremos con el tipo de peligros de los que habló Zhong Xu.",
  ui_story_5038_50380202_50_dialog_content = "Entiendo. Por el bien de todos a bordo, no podemos perder la esperanza de encontrarlo.",
  ui_story_5038_50380202_51_dialog_content = "Incluso si el Capitán no lo hubiera dicho, todavía habría querido encontrar la cosa.",
  ui_story_5038_50380202_52_dialog_content = "Se está haciendo tarde, así que busquemos un lugar para anclar para pasar la noche.",
  ui_story_5038_50380202_53_dialog_content = "Por favor, tenga una buena noche de descanso. Mantendré la vigilia con la tripulación.",
  ui_story_5038_50380202_54_dialog_content = "¡Yo también!",
  ui_story_5038_50380202_55_dialog_content = "Los niños deben dormir bien.",
  ui_story_5038_50380202_56_dialog_content = "¡Te lo he dicho, no soy un niño!",
  ui_story_5038_50380202_57_dialog_content = "Y de todos modos, Tinytail y yo no nos quedamos dormidos tan fácilmente por la noche.",
  ui_story_5038_50380202_58_dialog_content = "Déjalo ir. De lo contrario, terminará molestando a todos.",
  ui_story_5038_50380202_59_dialog_content = "¡Vamos! ¡Yo no haría eso!",
  ui_story_5038_50380202_60_dialog_content = "Bien. En ese caso, sígueme hasta la cubierta en un rato, Liqing.",
  ui_story_5038_50380202_61_dialog_content = "Las camas se han hecho en la cabina de pasajeros; cada uno tiene su propio espacio. Si me sigues, por favor.",
  ui_story_5038_50380301_1_dialog_content = "<color=#e8d9bb>Medianoche</color>",
  ui_story_5038_50380301_2_dialog_content = "Zzz...",
  ui_story_5038_50380301_3_dialog_content = "<color=#e8d9bb>*retumbando*</color>",
  ui_story_5038_50380301_4_dialog_content = "(¿Eh? ¿Fue un trueno...?)",
  ui_story_5038_50380301_5_dialog_content = "(Esta lloviendo...?)",
  ui_story_5038_50380301_6_dialog_content = "<color=#e8d9bb>¡¡¡RUIDO SORDO!!!</color>",
  ui_story_5038_50380301_7_dialog_content = "¡Waaaaah!",
  ui_story_5038_50380301_8_dialog_content = "¡¿Qué fue eso?!",
  ui_story_5038_50380301_9_dialog_content = "<color=#e8d9bb>¡Maullar!</color>",
  ui_story_5038_50380301_10_dialog_content = "<color=#e8d9bb>¡¡Maullar!!</color>",
  ui_story_5038_50380301_11_dialog_content = "Ahí ahí. No hay nada que temer.",
  ui_story_5038_50380301_12_dialog_content = "Perdón por despertarte, joven amigo.",
  ui_story_5038_50380301_13_dialog_content = "Yixin, Yimeng y Yinuo... Han estado conmigo toda su vida, e incluso sobrevivieron al incidente en el antiguo Shadowind...",
  ui_story_5038_50380301_14_dialog_content = "Clima como este les trae recuerdos de pesadilla.",
  ui_story_5038_50380301_15_dialog_content = "¡Olvídate de los gritos de gato! ¡¿No escuchaste ese ruido?!",
  ui_story_5038_50380301_16_dialog_content = "<color=#e8d9bb>¡¡¡RUIDO SORDO!!!</color>",
  ui_story_5038_50380301_17_dialog_content = "¿Todos despiertos? ¿Todo bien?",
  ui_story_5038_50380301_18_dialog_content = "Jiu lo escuchó primero. Estuve dando vueltas con ella, despertando a quienquiera que lograra dormir durante el alboroto.",
  ui_story_5038_50380301_19_dialog_content = "Entonces, ¿qué pasó exactamente?",
  ui_story_5038_50380301_20_dialog_content = "No lo sé, ¡pero se siente como si algo estuviera golpeando el casco!",
  ui_story_5038_50380301_21_dialog_content = "Y... no creo que sea <color=#FFB400>Una cosa</color>.",
  ui_story_5038_50380301_22_dialog_content = "(No podrían ser Eclipsitas, ¿o sí? ¡¡¿Todo el camino en el mar, en medio de la noche?!!)",
  ui_story_5038_50380301_23_dialog_content = "¡Iré a ver qué pasa en la cubierta!",
  ui_story_5038_50380301_24_dialog_content = "Déjame ir contigo, PlayerName.",
  ui_story_5038_50380301_25_dialog_content = "Sr. Zhong Xu, ¿tal vez le gustaría unirse a Dantang ya mí y buscar refugio?",
  ui_story_5038_50380301_26_dialog_content = "Si no recuerdo mal, debería haber un tobogán entre las cabinas de pasajeros en el piso debajo de este.",
  ui_story_5038_50380301_27_dialog_content = "¿eh? como pudiste...",
  ui_story_5038_50380301_28_dialog_content = "Este Shadowind está estructurado igual que el anterior, después de todo.",
  ui_story_5038_50380301_29_dialog_content = "Vamos entonces, apresurémonos.",
  ui_story_5038_50380301_30_dialog_content = "Sólo tengo una cosa que decir, joven amigo. Si ustedes dos no pueden ayudar a Liqing y Yuebai,",
  ui_story_5038_50380301_31_dialog_content = "luego sal de ahí, y ve a refugiarte debajo de las cubiertas. No seas un héroe.",
  ui_story_5038_50380301_32_dialog_content = "Lo haré, no te preocupes.",
  ui_story_5038_50380301_33_dialog_content = "<color=#e8d9bb>en las cubiertas</color>",
  ui_story_5038_50380301_34_dialog_content = "Está lloviendo tan fuerte...",
  ui_story_5038_50380301_35_dialog_content = "Yuebai! Liqing!",
  ui_story_5038_50380301_36_dialog_content = "¡Capitán Yuebai! ¡Gatito!",
  ui_story_5038_50380301_37_dialog_content = "Bueno, esto no está funcionando. Nunca nos escucharán con este aguacero.",
  ui_story_5038_50380301_38_dialog_content = "¿Crees que podrías encontrarlos psíquicamente, Sr. Legendary Caelestite?",
  ui_story_5038_50380301_39_option_content = "¡Potencia de fuerza!",
  ui_story_5038_50380301_40_dialog_content = "Urgh... No es bueno. Solo obtengo un leve rastro de Lumina y Darkflow.",
  ui_story_5038_50380301_41_dialog_content = "¡¿Eh?!",
  ui_story_5038_50380301_42_dialog_content = "Hay algo más... algo que nunca me había encontrado antes...",
  ui_story_5038_50380301_43_dialog_content = "El asistente de Dantang tenía razón... ¡Hay todo un grupo de lo que sean!",
  ui_story_5038_50380301_44_dialog_content = "Y no solo eso... Puedo sentir una energía poderosa...",
  ui_story_5038_50380301_45_dialog_content = "¡Intenta encontrarlos de nuevo!",
  ui_story_5038_50380301_46_dialog_content = "No sirve de nada. No puedo sentirlos en absoluto...",
  ui_story_5038_50380301_47_dialog_content = "<color=#e8d9bb>¡¡¡GOLPE!!!</color>",
  ui_story_5038_50380301_48_dialog_content = "<size=50><color=#e8d9bb>¡¡¡RUIDO SORDO!!!</color></size>",
  ui_story_5038_50380301_49_dialog_content = "¡Cuidado!",
  ui_story_5038_50380301_50_dialog_content = "¡Vamos a averiguar qué está haciendo ese sonido!",
  ui_story_5038_50380301_51_dialog_content = "Bien...",
  ui_story_5038_50380301_52_dialog_content = "Es... Es un...",
  ui_story_5038_50380301_53_dialog_content = "¡Pequeña cola! ¡Para! ¡Deja de retorcerte!",
  ui_story_5038_50380301_54_dialog_content = "¡No puedo aguantar!",
  ui_story_5038_50380301_55_dialog_content = "¡Capitán! ¡¿Estás bien allí?!",
  ui_story_5038_50380301_56_dialog_content = "¡Cuídate primero, Liqing! ¡Agárrate a algo! ¡Intenta no moverte!",
  ui_story_5038_50380301_57_dialog_content = "Liqing! Yuebai!",
  ui_story_5038_50380301_58_dialog_content = "¡Guau! Es PlayerName y Tianxian!",
  ui_story_5038_50380301_59_dialog_content = "¡¿Qué están haciendo aquí?!",
  ui_story_5038_50380301_60_dialog_content = "¡Tomen Liqing y pónganse a salvo, rápido!",
  ui_story_5038_50380301_61_dialog_content = "<size=50><color=#e8d9bb>¡¡¡RUIDO SORDO!!!</color></size>",
  ui_story_5038_50380301_62_dialog_content = "Su... <color=#FFB400>pez serpiente</color>!",
  ui_story_5038_50380301_63_dialog_content = "¡Están embistiendo nuestro casco! ¡¡Carpintero de barcos!!",
  ui_story_5038_50380301_64_dialog_content = "¿Sí, capitán?",
  ui_story_5038_50380301_65_dialog_content = "¡Lleve a alguien debajo de la cubierta e inicie un protocolo de emergencia para evitar roturas y fugas en el casco!",
  ui_story_5038_50380301_66_dialog_content = "¡Sí!",
  ui_story_5038_50380301_67_dialog_content = "Pez serpiente...",
  ui_story_5038_50380301_68_dialog_content = "Pero por qué...? ¿Por qué embestirían al Shadowind?",
  ui_story_5038_50380301_69_dialog_content = "(Estos son los peces de los que hablaba Liqing...)",
  ui_story_5038_50380301_70_dialog_content = "(Son innegablemente hermosos cuando están en masa... ¡Pero su fuerza combinada es aterradora!)",
  ui_story_5038_50380301_71_dialog_content = "<size=50><color=#e8d9bb>¡¡¡RUIDO SORDO!!!</color></size>",
  ui_story_5038_50380301_72_dialog_content = "¡Concéntrate, gatito! ¡Manténgase alejado de la barandilla o podría caerse por la borda!",
  ui_story_5038_50380301_73_dialog_content = "¿Cómo podemos detenerlos, Liqing?",
  ui_story_5038_50380301_74_dialog_content = "Nosotros... No podemos. Sin The Compass, no hay nada que podamos hacer...",
  ui_story_5038_50380301_75_dialog_content = "<size=50><color=#e8d9bb>¡GOLPE!</color></size>",
  ui_story_5038_50380301_76_dialog_content = "Oh no...",
  ui_story_5038_50380301_77_dialog_content = "¡Sal de aquí! ¡Intentaré mantenerla firme y ganarte algo de tiempo!",
  ui_story_5038_50380301_78_dialog_content = "¡Empezamos a cotizar! ¡Llega a los botes salvavidas!",
  ui_story_5038_50380301_79_dialog_content = "¡Espera!",
  ui_story_5038_50380301_80_dialog_content = "¿¿Qué??",
  ui_story_5038_50380301_81_dialog_content = "¡Algo más está haciendo la lista Shadowind! ¡Puedo sentirlo! Es como...",
  ui_story_5038_50380301_82_dialog_content = "Algo ha subido a bordo en grandes cantidades...",
  ui_story_5038_50380301_83_dialog_content = "Grah...",
  ui_story_5038_50380301_84_dialog_content = "¡Graaagh!",
  ui_story_5038_50380301_85_dialog_content = "¡Por supuesto que son Eclipsitas!",
  ui_story_5038_50380301_86_dialog_content = "... Tenemos suerte de tenerte con nosotros, PlayerName.",
  ui_story_5038_50380301_87_dialog_content = "¡Vamos a cuidarlos!",
  ui_story_5038_50380302_1_dialog_content = "¡Los eliminaremos a todos de una vez!",
  ui_story_5038_50380302_2_dialog_content = "Estoy agradecido por su ayuda, PlayerName.",
  ui_story_5038_50380302_3_dialog_content = "Sin embargo, parece que el barco sigue escorándose...",
  ui_story_5038_50380302_4_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5038_50380302_5_dialog_content = "¡Trae objetos pesados y mercancías a la popa para equilibrar el barco, marinero!",
  ui_story_5038_50380302_6_dialog_content = "¡Sí!",
  ui_story_5038_50380302_7_dialog_content = "Los peces están tirando de una cuerda en la proa, así fue como los Eclipsites pudieron subir a bordo.",
  ui_story_5038_50380302_8_dialog_content = "PlayerName, Liqing, Tianxian! Si puedes, sigue al barquero a popa.",
  ui_story_5038_50380302_9_dialog_content = "¡Está bien!",
  ui_story_5038_50380302_10_dialog_content = "Aquí, PlayerName, ¡toma esto!",
  ui_story_5038_50380302_11_dialog_content = "Vaya, eso es pesado!! ¿Qué es?",
  ui_story_5038_50380302_12_dialog_content = "¡Un cofre lleno de pesas de hierro desde Longzhou!",
  ui_story_5038_50380302_13_dialog_content = "... ¡¿Qué diablos está haciendo algo así a bordo?!",
  ui_story_5038_50380302_14_dialog_content = "Para contabilidad, pesaje de mercancías, etc. Te sorprendería la frecuencia con la que son útiles.",
  ui_story_5038_50380302_15_dialog_content = "Quiero decir, evidentemente, los necesitamos ahora mismo.",
  ui_story_5038_50380302_16_dialog_content = "Cogeré un cofre también. Llevémoslos a popa, para arreglar la escora del barco.",
  ui_story_5038_50380302_17_dialog_content = "No necesitas llevar nada, gatito. Probablemente te harías daño.",
  ui_story_5038_50380302_18_dialog_content = "Me quedo aquí.",
  ui_story_5038_50380302_19_dialog_content = "¿Estás tratando de ser gracioso? Vamos, muévete.",
  ui_story_5038_50380302_20_dialog_content = "Dije, me quedo aquí.",
  ui_story_5038_50380302_21_dialog_content = "(Liqing ha estado escudriñando el agua durante mucho tiempo, casi como si estuviera buscando algo...)",
  ui_story_5038_50380302_22_dialog_content = "¿Has pensado en algo, Liqing? ¿Sabes por qué atacan los peces serpiente?",
  ui_story_5038_50380302_23_dialog_content = "No. Ni idea...",
  ui_story_5038_50380302_24_dialog_content = "¡Pero el pez serpiente nunca ataca a las personas sin razón!",
  ui_story_5038_50380302_25_dialog_content = "Deben estar siguiendo las órdenes de su líder escolar, el pez alfa.",
  ui_story_5038_50380302_26_dialog_content = "Pero, ¿por qué querría atacar nuestra nave? ¿Qué quiere...?",
  ui_story_5038_50380302_27_dialog_content = "¿Estás tratando de encontrar este pez alfa?",
  ui_story_5038_50380302_28_dialog_content = "Al menos... necesito ver claramente de dónde <color=#FFB400>dirección</color> ellos vienen.",
  ui_story_5038_50380302_29_dialog_content = "<color=#e8d9bb>¡¡¡GOLPE!!!</color>",
  ui_story_5038_50380302_30_dialog_content = "(Los peces serpiente se están poniendo cada vez más nerviosos. Si esto continúa por mucho más tiempo...)",
  ui_story_5038_50380302_31_option_content = "¡Potencia de fuerza!",
  ui_story_5038_50380302_32_dialog_content = "¡¿Eso funcionará?!",
  ui_story_5038_50380302_33_dialog_content = "¡Realmente no lo sé! ¡Pero no puede hacer daño intentarlo!",
  ui_story_5038_50380302_34_dialog_content = "(Intentaré hacer lo que hice antes...)",
  ui_story_5038_50380302_35_dialog_content = "(Estas criaturas parecen venir del este... Déjame tratar de calmarlas...)",
  ui_story_5038_50380302_36_dialog_content = "(¡Maldita sea, no está funcionando esta vez!)",
  ui_story_5038_50380302_37_dialog_content = "Parece que se detienen. ¡Mirar!",
  ui_story_5038_50380302_38_dialog_content = "¿En serio? ¡¿Mi loca idea funcionó?!",
  ui_story_5038_50380302_39_dialog_content = "De repente se dieron la vuelta todos a la vez, formando un largo cinturón de peces...",
  ui_story_5038_50380302_40_dialog_content = "... ¡No, espera! ¡¡Algo esta mal!!",
  ui_story_5038_50380302_41_dialog_content = "¿Q-Qué quieres decir?",
  ui_story_5038_50380302_42_dialog_content = "¡Tipo! ¡Agárrate de la barandilla y tírate al suelo!",
  ui_story_5038_50380302_43_dialog_content = "¡Están... acusándonos!",
  ui_story_5038_50380302_44_dialog_content = "¡Capitán! ¡Gira la nave, rápido!",
  ui_story_5038_50380302_45_dialog_content = "(Esos peces serpiente ya causaron daños graves. Sin mencionar esta tormenta...)",
  ui_story_5038_50380302_46_dialog_content = "(Apenas puedo mover el timón...)",
  ui_story_5038_50380302_47_dialog_content = "¡Prepárense todos! ¡Agárrense y protejan sus cabezas!",
  ui_story_5038_50380302_48_dialog_content = "(¿Va a sucumbir Shadowind al poder del océano una vez más?)",
  ui_story_5038_50380302_49_dialog_content = "<size=45><color=#e8d9bb>¡¡¡RUIDO SORDO!!!</color></size>",
  ui_story_5038_50380402_1_dialog_content = "¡Uf!",
  ui_story_5038_50380402_2_dialog_content = "(Me duele todo el cuerpo... Mi espalda está en agonía...)",
  ui_story_5038_50380402_3_dialog_content = "(Aunque estoy vivo... solo.)",
  ui_story_5038_50380402_4_dialog_content = "¿Estás bien, PlayerName?",
  ui_story_5038_50380402_5_dialog_content = "Yuebai! ¡Estas vivo!",
  ui_story_5038_50380402_6_dialog_content = "¿Qué pasa con... todos los demás?",
  ui_story_5038_50380402_7_dialog_content = "Levántate antes de que el sol te queme la piel, PlayerName.",
  ui_story_5038_50380402_8_dialog_content = "Pareces relativamente ileso, jovencito.",
  ui_story_5038_50380402_9_dialog_content = "Nos tenías preocupados por un segundo allí.",
  ui_story_5038_50380402_10_dialog_content = "Todavía me duele la cabeza... ¿Qué pasó exactamente anoche?",
  ui_story_5038_50380402_11_dialog_content = "Perdimos el control del Shadowind después de que lo embistieran violentamente.",
  ui_story_5038_50380402_12_dialog_content = "Terminamos golpeando algunos arrecifes.",
  ui_story_5038_50380402_13_dialog_content = "El viento y las olas se calmaron gradualmente, después de que el pez serpiente se hubo dispersado.",
  ui_story_5038_50380402_14_dialog_content = "Usted y Tianxian quedaron inconscientes en todo el caos, por lo que la tripulación los llevó a la cabina de pasajeros.",
  ui_story_5038_50380402_15_dialog_content = "Afortunadamente, nuestro pequeño doctor Liqing estaba presente. Ya les ha recetado a ambos la medicina adecuada.",
  ui_story_5038_50380402_16_dialog_content = "También fue idea mía traeros aquí para tomar el sol.",
  ui_story_5038_50380402_17_dialog_content = "Es agradable y cálido aquí...",
  ui_story_5038_50380402_18_dialog_content = "¡¿Eh?!",
  ui_story_5038_50380402_19_dialog_content = "¡Eww! ¿Q-Qué hay en mi boca? ¡Es realmente amargo!",
  ui_story_5038_50380402_20_dialog_content = "Oye, no lo escupas todavía. Es algo para el mareo.",
  ui_story_5038_50380402_21_dialog_content = "Aliento del diablo, madreselva y un poco de menta.",
  ui_story_5038_50380402_22_dialog_content = "Si es amargo entonces es bueno para ti, PlayerName. ¡Cuelga ahí!",
  ui_story_5038_50380402_23_dialog_content = "E-Está bien...",
  ui_story_5038_50380402_24_dialog_content = "Ya que puedes levantarte y moverte bien, entonces no hay mucho de qué preocuparte.",
  ui_story_5038_50380402_25_dialog_content = "Más importante aún, ¿cómo está Shadowind? Después de todo lo que pasó anoche.",
  ui_story_5038_50380402_26_dialog_content = "No muy bien.",
  ui_story_5038_50380402_27_dialog_content = "La tormenta rompió el mástil y la bodega está goteando.",
  ui_story_5038_50380402_28_dialog_content = "Se podría decir que está en soporte vital. Sería cauteloso acerca de llevarla a aguas ligeramente picadas.",
  ui_story_5038_50380402_29_dialog_content = "¡¿Así de mal?!",
  ui_story_5038_50380402_30_dialog_content = "Entonces es demasiado arriesgado zarpar, ¿no?",
  ui_story_5038_50380402_31_dialog_content = "... La historia se repite. Esto es exactamente lo que sucedió la última vez.",
  ui_story_5038_50380402_32_dialog_content = "Deseé obstinadamente retomar la ruta marítima, y fui lo suficientemente tonto como para creer que podría llegar hasta Astra con mis propias habilidades marineras.",
  ui_story_5038_50380402_33_dialog_content = "Estaba tan seguro de que incluso sin The Compass, tendría la suerte de volver con vida.",
  ui_story_5038_50380402_34_dialog_content = "Mirando las cosas ahora... Supongo que los Lins realmente necesitan su protección.",
  ui_story_5038_50380402_35_dialog_content = "Pensando en la noche anterior, esos peces serpiente eran realmente extraños.",
  ui_story_5038_50380402_36_dialog_content = "Capitán, usted es miembro de Lin, debe saber cómo se comporta normalmente el pez serpiente.",
  ui_story_5038_50380402_37_dialog_content = "Son animales extremadamente sociales y nunca habrían atacado sin las órdenes de algún líder.",
  ui_story_5038_50380402_38_dialog_content = "Eso es lo que solíamos pensar.",
  ui_story_5038_50380402_39_dialog_content = "El temperamento de estos vagabundos del océano ha cambiado durante el último medio año.",
  ui_story_5038_50380402_40_dialog_content = "Han comenzado a atacar barcos sin ninguna provocación, sin cesar hasta que el barco y todos a bordo perecen.",
  ui_story_5038_50380402_41_dialog_content = "Ahora, se sabe que me obsesiono con mis objetivos singulares, pero no voy a arriesgarme con un barco lleno de vidas.",
  ui_story_5038_50380402_42_dialog_content = "Me temo que el resto del viaje...",
  ui_story_5038_50380402_43_dialog_content = "¿Q-Qué? Si no podemos seguir adelante, ni podemos sentarnos aquí para siempre...",
  ui_story_5038_50380402_44_dialog_content = "¿No somos patos sentados esperando a morir?",
  ui_story_5038_50380402_45_dialog_content = "...",
  ui_story_5038_50380402_46_dialog_content = "Capitán...",
  ui_story_5038_50380402_47_dialog_content = "Apenas es mediodía, ¿qué pasa con todo el pesimismo?",
  ui_story_5038_50380402_48_dialog_content = "Tengo tres fortunas aquí para contar. ¿Quién está listo para eso?",
  ui_story_5038_50380402_49_dialog_content = "Nadie está de humor para tus tonterías supersticiosas en un momento como este.",
  ui_story_5038_50380402_50_dialog_content = "Definitivamente no es una tontería. Puede que los demás no estén interesados, Capitán, pero creo que definitivamente debería escucharme.",
  ui_story_5038_50380402_51_dialog_content = "¿Por qué yo?",
  ui_story_5038_50380402_52_dialog_content = "Me desperté del sueño más extraño, luego tuve la premonición de que algo estaba a punto de suceder.",
  ui_story_5038_50380402_53_dialog_content = "Cada vez que recuerdo los eventos de anoche, recuerdo que las revelaciones tienden a llegar en medio de la adversidad.",
  ui_story_5038_50380402_54_dialog_content = "¿Puedes ir al grano, por favor?",
  ui_story_5038_50380402_55_dialog_content = "Bien, bien. Básicamente, me encargué de escudriñar las brumas del futuro de Shadowind.",
  ui_story_5038_50380402_56_dialog_content = "Las herramientas simples de mi Adivinación Hexagrama Celestial, el símbolo yin-yang y los animales del zodiaco, hablan sabiduría para aquellos que se preocupan por escuchar.",
  ui_story_5038_50380402_57_dialog_content = "Desafortunadamente, aunque soy hábil para predecir el futuro y calcular destinos, no estoy familiarizado con la nave.",
  ui_story_5038_50380402_58_dialog_content = "Así que requiero la guía de nuestro buen Capitán, para que me ayude a descifrar las respuestas proporcionadas.",
  ui_story_5038_50380402_59_dialog_content = "Basta de teatro. Solo ve al grano.",
  ui_story_5038_50380402_60_dialog_content = "La situación de Shadowind es grave. Solo podemos hacer lo que podamos y rezar para que la fortuna esté de nuestro lado.",
  ui_story_5038_50380402_61_dialog_content = "Me presentaron un grupo muy extraño de tres animales: el ratón vacilante, el mono tonto y el conejo astuto.",
  ui_story_5038_50380402_62_dialog_content = "En todos mis años diciendo fortunas a lo largo y ancho, nunca me había encontrado con una combinación tan enigmática.",
  ui_story_5038_50380402_63_dialog_content = "Los tres aparecieron con las mismas combinaciones de hexagramas yin-yang, lo que parece que todos insinuaban lo mismo.",
  ui_story_5038_50380402_64_dialog_content = "¿Un ratón, un mono y un conejo...?",
  ui_story_5038_50380402_65_dialog_content = "¿Cuál es su interpretación, entonces?",
  ui_story_5038_50380402_66_dialog_content = "No soy un experto, pero mi conclusión es que se refieren a algo relacionado con el intercambio de una mercancía por otra.",
  ui_story_5038_50380402_67_dialog_content = "\"Lo que es ilusión se vuelve real, cuando lo real se vuelve ilusión\". Esencialmente, nos está diciendo que <color=#FFB400>reemplazar</color> lo que hemos perdido.",
  ui_story_5038_50380402_68_dialog_content = "Reemplazar...?",
  ui_story_5038_50380402_69_dialog_content = "¡Vaya! ¡Creo que lo entiendo!",
  ui_story_5038_50380402_70_dialog_content = "La costumbre de nuestra patria es nombrar las partes importantes del casco de un barco con los 12 animales del zodíaco.",
  ui_story_5038_50380402_71_dialog_content = "Oramos para que esto nos traiga buena fortuna, que podamos navegar a través del mar tan firmemente como las criaturas que pisan la tierra.",
  ui_story_5038_50380402_72_dialog_content = "Muchas secciones del casco resultaron dañadas en la tormenta de anoche.",
  ui_story_5038_50380402_73_dialog_content = "Incluyendo la cola de ratón en la popa y la cabeza de mono en la proa. El primero está totalmente perdido y el otro dañado.",
  ui_story_5038_50380402_74_dialog_content = "Pero las barandillas laterales, las orejas de conejo, están bien.",
  ui_story_5038_50380402_75_dialog_content = "Hmm... Entonces meditaré más sobre las orejas de conejo.",
  ui_story_5038_50380402_76_dialog_content = "Pero si encuentras algo que reemplace a los dos primeros, ¿el Shadowind al menos podrá navegar?",
  ui_story_5038_50380402_77_dialog_content = "Ayudará a que esté en condiciones de navegar, pero no es suficiente.",
  ui_story_5038_50380402_78_dialog_content = "El casco está dañado en varios lugares, por lo que no podemos darnos el lujo de tomar atajos. Tenemos que reparar el barco, sección por sección.",
  ui_story_5038_50380402_79_dialog_content = "Además, ¿dónde exactamente debo encontrar los reemplazos para estas piezas?",
  ui_story_5038_50380402_80_dialog_content = "Puedo tener una idea.",
  ui_story_5038_50380402_81_dialog_content = "Justo debajo de nosotros se encuentra una de las mayores bóvedas del tesoro: el mar.",
  ui_story_5038_50380501_1_dialog_content = "(Zhong Xu y Yuebai decidieron al final no usar los botes salvavidas y permanecer en Shadowind).",
  ui_story_5038_50380501_2_dialog_content = "(Incluso han levantado el ancla).",
  ui_story_5038_50380501_3_dialog_content = "(... ¿Está realmente bien zarpar de nuevo tan pronto?)",
  ui_story_5038_50380501_4_dialog_content = "Hicimos una elección arriesgada.",
  ui_story_5038_50380501_5_dialog_content = "Sin embargo, el océano se ha tragado innumerables barcos. Si tan solo pudiéramos llegar a donde los piratas nos atacaron hace medio año...",
  ui_story_5038_50380501_6_dialog_content = "Quizá podamos salvar algunas piezas útiles.",
  ui_story_5038_50380501_7_dialog_content = "Aunque sé que esto es equivalente a buscar una aguja en un pajar.",
  ui_story_5038_50380501_8_dialog_content = "Sin embargo, estamos en nuestro último recurso.",
  ui_story_5038_50380501_9_dialog_content = "Estoy de acuerdo.",
  ui_story_5038_50380501_10_dialog_content = "De todos modos, los botes salvavidas a bordo no serían capaces de soportar una tormenta.",
  ui_story_5038_50380501_11_dialog_content = "Tampoco podemos flotar en el agua para siempre.",
  ui_story_5038_50380501_12_dialog_content = "Es mejor al menos remar cuando hace buen tiempo que sentarse y pudrirse.",
  ui_story_5038_50380501_13_dialog_content = "Muy bien, tripulación. Traiga la vela dañada y extienda los remos.",
  ui_story_5038_50380501_14_dialog_content = "Seguiremos las cartas náuticas y remaremos hasta el lugar del naufragio.",
  ui_story_5038_50380501_15_dialog_content = "Aunque estas son órdenes del Capitán, sigo pensando que es demasiado arriesgado...",
  ui_story_5038_50380501_16_dialog_content = "Cuida tu lengua, muchacho. Es mejor no decir esas cosas mientras aún esté a bordo.",
  ui_story_5038_50380501_17_dialog_content = "Incluso si nos encontramos con un desastre, no es como si tuviéramos algún control sobre nuestras vidas.",
  ui_story_5038_50380501_18_dialog_content = "¿Es el Capitán Yuebai alguien cuyo juicio debería cuestionar?",
  ui_story_5038_50380501_19_dialog_content = "P-Princesa Dantang...",
  ui_story_5038_50380501_20_dialog_content = "Si tienes quejas, su puerta siempre está abierta. Estoy seguro de que estaría feliz de trabajar juntos para encontrar una solución.",
  ui_story_5038_50380501_21_dialog_content = "Sobre estas aguas turbulentas, si uno no teme ni a la muerte, ¿qué miedo tendrías de insultar a alguien en su cara?",
  ui_story_5038_50380501_22_dialog_content = "¿Qué está pasando acá?",
  ui_story_5038_50380501_23_dialog_content = "Ah, Yubai. Estos tipos tienen algo que les gustaría decirte.",
  ui_story_5038_50380501_24_dialog_content = "N-No, no lo hago. No. Nada.",
  ui_story_5038_50380501_25_dialog_content = "Yo tampoco. Por favor, princesa... Perdónanos.",
  ui_story_5038_50380501_26_dialog_content = "...",
  ui_story_5038_50380501_27_dialog_content = "<color=#e8d9bb>¡Chasquido, chapoteo!</color>",
  ui_story_5038_50380501_28_dialog_content = "¡Ten piedad de nosotros, Capitán! Nosotros...",
  ui_story_5038_50380501_29_dialog_content = "Giro de vuelta.",
  ui_story_5038_50380501_30_dialog_content = "¿Eh...?",
  ui_story_5038_50380501_31_dialog_content = "Graah...",
  ui_story_5038_50380501_32_dialog_content = "¿Embarcar en un barco a plena luz del día? ¡Qué terriblemente grosero!",
  ui_story_5038_50380501_33_dialog_content = "No puedes enseñar modales a esas cosas.",
  ui_story_5038_50380501_34_dialog_content = "Pónganse detrás de mí, ustedes dos.",
  ui_story_5038_50380501_35_dialog_content = "No dejaré que te mueras.",
  ui_story_5038_50380501_36_dialog_content = "¡A-Sí, capitán!",
  ui_story_5038_50380602_1_dialog_content = "Cola de ratón, cabeza de mono, orejas de conejo...",
  ui_story_5038_50380602_2_dialog_content = "Qué críptico. Los nombres realmente no ofrecen muchas pistas sobre lo que son, miau.",
  ui_story_5038_50380602_3_dialog_content = "En pocas palabras, representan una veleta, una polea y una tabla.",
  ui_story_5038_50380602_4_dialog_content = "<color=#FFB400>Veletas</color> debe instalarse justo en la parte superior del mástil.",
  ui_story_5038_50380602_5_dialog_content = "La cuerda atada a la popa se parece un poco a la cola de un ratón.",
  ui_story_5038_50380602_6_dialog_content = "Flota, debido a que es tan ligero.",
  ui_story_5038_50380602_7_dialog_content = "<color=#FFB400>poleas</color> son bastante estándar, ya que son necesarios para manejar las velas.",
  ui_story_5038_50380602_8_dialog_content = "Se les llama \"cabezas de mono\" por su tamaño y forma.",
  ui_story_5038_50380602_9_dialog_content = "Si podemos encontrar reemplazos para esos dos, podremos usar nuestras velas nuevamente.",
  ui_story_5038_50380602_10_dialog_content = "¡Vaya, lo haces sonar tan fácil!",
  ui_story_5038_50380602_11_dialog_content = "Entonces, ¿qué pasa con las orejas de conejo?",
  ui_story_5038_50380602_12_dialog_content = "... Esos son especiales y no se reemplazan fácilmente.",
  ui_story_5038_50380602_13_dialog_content = "Afortunadamente, nuestras orejas de conejo no se dañaron, así que concentrémonos primero en las otras dos.",
  ui_story_5038_50380602_14_dialog_content = "¡Entendido!",
  ui_story_5038_50380602_15_dialog_content = "¿Podrías echarnos una mano, PlayerName, dantang?",
  ui_story_5038_50380602_16_dialog_content = "¡Claro!",
  ui_story_5038_50380602_17_dialog_content = "(¡N-no tengo idea de lo que está pasando...!)",
  ui_story_5038_50380602_18_dialog_content = "No tiene necesidad de fingir, Su Alteza. En casa, rara vez te aventurabas fuera de los terrenos, después de todo.",
  ui_story_5038_50380602_19_dialog_content = "Es natural que no entiendas estas cosas.",
  ui_story_5038_50380602_20_dialog_content = "... Puede ser como dices, pero aún quiero ayudar.",
  ui_story_5038_50380602_21_dialog_content = "Bueno, dado que no crees que deba probarme a mí mismo, creo que no es necesario que me sigas a todas partes.",
  ui_story_5038_50380602_22_dialog_content = "P-princesa...",
  ui_story_5038_50380602_23_dialog_content = "¡Qué terco, miau!",
  ui_story_5038_50380602_24_dialog_content = "Por favor, evite evaluaciones tan descorteses de la princesa.",
  ui_story_5038_50380602_25_dialog_content = "¡Bien bien! Vamos a movernos, PlayerName.",
  ui_story_5038_50380602_26_dialog_content = "Pero... No tengo ni idea de adónde debemos ir, o cómo debemos empezar a buscar.",
  ui_story_5038_50380602_27_dialog_content = "Mmm vamos a ver...",
  ui_story_5038_50380602_28_dialog_content = "Tinytail y yo iremos a olfatear cosas primero. ¡Vamos a olfatear la cubierta!",
  ui_story_5038_50380602_29_dialog_content = "¡Los gatos podemos captar el olor de la cola de un ratón a una milla de distancia!",
  ui_story_5038_50380602_30_dialog_content = "¡Um, no estoy seguro de que estemos hablando de lo mismo...!",
  ui_story_5038_50380602_31_dialog_content = "<color=#e8d9bb>Cabina de pasajeros Shadowind</color>",
  ui_story_5038_50380602_32_dialog_content = "Hrrgh...",
  ui_story_5038_50380602_33_dialog_content = "(Tengo que buscar en todas partes...)",
  ui_story_5038_50380602_34_dialog_content = "¿Qué estás buscando, princesa?",
  ui_story_5038_50380602_35_dialog_content = "Nada que sea de tu incumbencia.",
  ui_story_5038_50380602_36_dialog_content = "¡Oye, no te apresures a rechazarme! En lugar de mirar a ciegas, ¿por qué no me dejas adivinar por ti, hmm?",
  ui_story_5038_50380602_37_dialog_content = "... Estás realmente comprometido con tu estafa.",
  ui_story_5038_50380602_38_dialog_content = "Bueno, seguramente los acontecimientos recientes han demostrado que esto no es una estafa.",
  ui_story_5038_50380602_39_dialog_content = "Concedo eso... Aunque podría haber sido una suposición afortunada.",
  ui_story_5038_50380602_40_dialog_content = "Estoy buscando la cola de ratón que el capitán dijo que faltaba.",
  ui_story_5038_50380602_41_dialog_content = "¿Estás mirando el barco?",
  ui_story_5038_50380602_42_dialog_content = "Sí, considerando todas las cosas, esa es mi conclusión tentativa.",
  ui_story_5038_50380602_43_dialog_content = "El Capitán dijo que esta cola de ratón era muy liviana y que flotaría si se arrojara al agua.",
  ui_story_5038_50380602_44_dialog_content = "La tripulación ha estado patrullando el barco constantemente desde el incidente de anoche.",
  ui_story_5038_50380602_45_dialog_content = "Los marineros de Lin Guild son legendarios en lo que hacen. Se darían cuenta incluso de un alfiler que cayera por la borda.",
  ui_story_5038_50380602_46_dialog_content = "Así que, sea lo que sea esta cosa, todavía tiene que estar en el barco.",
  ui_story_5038_50380602_47_dialog_content = "¡Muy perspicaz, princesa! Coincido con tu línea de pensamiento.",
  ui_story_5038_50380602_48_dialog_content = "Siendo ese el caso, registremos la nave.",
  ui_story_5038_50380602_49_dialog_content = "¡Graznido! ¡Farfullar!",
  ui_story_5038_50380602_50_dialog_content = "Lo sé, lo sé.",
  ui_story_5038_50380602_51_dialog_content = "Deja de empujar, deja de empujar.",
  ui_story_5038_50380602_52_dialog_content = "¿Estorninos parlantes?",
  ui_story_5038_50380602_53_dialog_content = "Los entrené para imitar el habla humana.",
  ui_story_5038_50380602_54_dialog_content = "Vayan ahora, Squawk y Jabber, vean si pueden encontrar esta misteriosa veleta con forma de ratón.",
  ui_story_5038_50380602_55_dialog_content = "Tengo golosinas esperándote.",
  ui_story_5038_50380602_56_dialog_content = "<color=#e8d9bb>*Aleteo*... *Aleteo*...</color>",
  ui_story_5038_50380602_57_dialog_content = "¿No vas a confiar en tu fiel adivinación esta vez?",
  ui_story_5038_50380602_58_dialog_content = "Los buenos pájaros eligen buenos maestros. Y de todos modos, en momentos como este, una vista de pájaro es mejor que la adivinación.",
  ui_story_5038_50380602_59_dialog_content = "Vamos, princesa. Sigamos a nuestros dos cazadores de tesoros.",
  ui_story_5038_50380602_60_dialog_content = "Esta pequeña cola de ratón no permanecerá escondida por mucho más tiempo.",
  ui_story_5038_50380602_61_dialog_content = "<color=#e8d9bb>¡Graznar! ¡Graznar!</color>",
  ui_story_5038_50380602_62_dialog_content = "¡Dame dátiles regordetes y dulces, graznido!",
  ui_story_5038_50380602_63_dialog_content = "¡Dame deliciosas y dulces semillas de melón, graznido!",
  ui_story_5038_50380602_64_dialog_content = "Sé que sé. Recibirás tus delicias. ¿Lo encontraste?",
  ui_story_5038_50380602_65_dialog_content = "Eso es...",
  ui_story_5038_50380602_66_dialog_content = "Se parece mucho a una cola... ¡Debe ser esto!",
  ui_story_5038_50380602_67_dialog_content = "¡Sí! Parece que tienes toda la razón.",
  ui_story_5038_50380602_68_dialog_content = "Suerte que ustedes dos pudieron encontrarlo en medio de toda esa porquería.",
  ui_story_5038_50380602_69_dialog_content = "¡Pronto tendrás tus sabrosos dátiles y semillas de melón!",
  ui_story_5038_50380602_70_dialog_content = "Tómalo, princesa.",
  ui_story_5038_50380602_71_dialog_content = "Ve a llevárselo al capitán Yuebai.",
  ui_story_5038_50380701_1_dialog_content = "(Después de que Dantang le diera la \"cola de ratón\" a Yuebai...)",
  ui_story_5038_50380701_2_dialog_content = "(Las reparaciones del barco van muy bien y el mástil está casi restaurado).",
  ui_story_5038_50380701_3_dialog_content = "(Está navegando mucho más suavemente, casi como si el accidente nunca hubiera ocurrido).",
  ui_story_5038_50380701_4_dialog_content = "(Es solo...)",
  ui_story_5038_50380701_5_dialog_content = "El viento ha cambiado. ¡Prepárate para dejar de remar y echar el ancla!",
  ui_story_5038_50380701_6_dialog_content = "¡Sí!",
  ui_story_5038_50380701_7_dialog_content = "(Excepto que todavía tenemos que parar de repente de vez en cuando).",
  ui_story_5038_50380701_8_dialog_content = "Pareces preocupado, joven.",
  ui_story_5038_50380701_9_dialog_content = "No soy. Supongo... Confío en el juicio de Yuebai.",
  ui_story_5038_50380701_10_dialog_content = "No hay necesidad de ocultar cómo te sientes. Sospecho que estamos pensando lo mismo.",
  ui_story_5038_50380701_11_dialog_content = "(Él vio a través de mí...)",
  ui_story_5038_50380701_12_dialog_content = "Nos dirigimos a la última ubicación conocida de The Compass con la ayuda de las cartas náuticas.",
  ui_story_5038_50380701_13_dialog_content = "Pero el barco todavía se encuentra en condiciones precarias, y las reparaciones temporales son más un emplasto que una cura.",
  ui_story_5038_50380701_14_dialog_content = "Navegar es una habilidad muy precisa con poco margen de error.",
  ui_story_5038_50380701_15_dialog_content = "Las oraciones por sí solas no garantizarán que las cosas salgan bien.",
  ui_story_5038_50380701_16_dialog_content = "... Sin embargo, es solo una pequeña preocupación mía.",
  ui_story_5038_50380701_17_dialog_content = "No te lo tomes a pecho.",
  ui_story_5038_50380701_18_dialog_content = "Por supuesto. Intentaré recomponerme. ¡Y Zhong Xu, recuerda que tampoco debes preocuparte demasiado!",
  ui_story_5038_50380701_19_dialog_content = "Shadowind experimentó todo tipo de obstáculos, pero logró llegar a salvo a Astra; no hay forma de que nos dejara perecer en el mar.",
  ui_story_5038_50380701_20_dialog_content = "¡Silencio!",
  ui_story_5038_50380701_21_dialog_content = "¡¿Q-Qué?!",
  ui_story_5038_50380701_22_dialog_content = "... Lo siento, exageré.",
  ui_story_5038_50380701_23_dialog_content = "En mi ciudad natal, decir esas cosas se considera un tabú cuando la llegada de un nuevo año está en el horizonte.",
  ui_story_5038_50380701_24_dialog_content = "Sé que es solo una pequeña costumbre inofensiva, pero espero que lo entiendas.",
  ui_story_5038_50380701_25_dialog_content = "Ahora disculpe, me despediré.",
  ui_story_5038_50380701_26_dialog_content = "(¿Quiso decir... hablar de la muerte es un tabú?)",
  ui_story_5038_50380701_27_dialog_content = "No sueles ver a Zhong Xu tan alterado.",
  ui_story_5038_50380701_28_dialog_content = "Supongo que está preocupado por cometer los mismos errores que cometió hace seis meses.",
  ui_story_5038_50380701_29_dialog_content = "PlayerName, ¿podrías darme una mano por favor?",
  ui_story_5038_50380701_30_dialog_content = "Estoy moviendo silenciosamente este pequeño bote salvavidas de madera hacia los rieles.",
  ui_story_5038_50380701_31_dialog_content = "¿Eh? ¡Aférrate! ¿No es esto básicamente solo <color=#FFB400>robando</color>?",
  ui_story_5038_50380701_32_dialog_content = "Vamos, no seas dramático, miau.",
  ui_story_5038_50380701_33_dialog_content = "Mire, el Capitán y Zhong Xu están allí discutiendo la prevención de filtraciones y fugas.",
  ui_story_5038_50380701_34_dialog_content = "No podría interrumpirlos por esto.",
  ui_story_5038_50380701_35_dialog_content = "Pero, ¿qué piensas hacer con el bote salvavidas?",
  ui_story_5038_50380701_36_dialog_content = "¡Salva la \"cabeza de mono\", por supuesto!",
  ui_story_5038_50380701_37_dialog_content = "¡De ninguna manera! ¡Es demasiado peligroso!",
  ui_story_5038_50380701_38_dialog_content = "Escúchame, PlayerName. Si Shadowind fuera una persona, estaría enferma ahora mismo.",
  ui_story_5038_50380701_39_dialog_content = "Las enfermedades necesitan ser tratadas con la cura adecuada. Algunas hierbas son bastante simples de obtener.",
  ui_story_5038_50380701_40_dialog_content = "Mientras que algunos crecen hasta la mitad de un acantilado vertical, lejos del alcance de cualquiera.",
  ui_story_5038_50380701_41_dialog_content = "La cabeza del mono está dañada y no hay un reemplazo adecuado a bordo.",
  ui_story_5038_50380701_42_dialog_content = "Para curar la enfermedad, necesito salir al mar.",
  ui_story_5038_50380701_43_dialog_content = "¿¿El mar?? ¿Crees que vas a encontrar algo ahí afuera cuando ni siquiera puedes encontrarlo a bordo?",
  ui_story_5038_50380701_44_dialog_content = "No sé si te has dado cuenta, pero hay todo tipo de cosas flotando por aquí.",
  ui_story_5038_50380701_45_dialog_content = "Estos restos son todo lo que queda de barcos desconocidos del pasado, perdidos en el mar quién sabe cuándo.",
  ui_story_5038_50380701_46_dialog_content = "Si puedo encontrar otra \"cabeza de mono\" de una de estas naves, seguramente eso resolvería el problema de Shadowind.",
  ui_story_5038_50380701_47_dialog_content = "¡Nos moveremos mucho más rápido una vez que podamos izar las velas! ¡Entonces podemos preocuparnos por las \"orejas de conejo\"!",
  ui_story_5038_50380701_48_dialog_content = "Tienes razón, pero ¿es esto realmente factible?",
  ui_story_5038_50380701_49_dialog_content = "Es como buscar una aguja en un pajar que es el océano.",
  ui_story_5038_50380701_50_dialog_content = "Es factible si digo que lo es, PlayerName. Yo soy el diabólico aquí, después de todo.",
  ui_story_5038_50380701_51_dialog_content = "Mi <color=#FFB400>amigos marinos</color> me dará señales y señales.",
  ui_story_5038_50380701_52_dialog_content = "¿De verdad?",
  ui_story_5038_50380701_53_dialog_content = "Por supuesto. A menudo hablo con ellos cuando estoy en el mar.",
  ui_story_5038_50380701_54_dialog_content = "Si pido ayuda, me la proporcionan.",
  ui_story_5038_50380701_55_dialog_content = "¿Incluyendo ayudarte a encontrar la \"cabeza de mono\" de otro barco?",
  ui_story_5038_50380701_56_dialog_content = "Pero... ¿cómo iban a saber cómo es una cosa así?",
  ui_story_5038_50380701_57_dialog_content = "No te preocupes por eso. Puedo describírselo a ellos.",
  ui_story_5038_50380701_58_dialog_content = "De todos modos, gracias por ayudar, PlayerName! ¡Puedo tomarlo desde aquí!",
  ui_story_5038_50380701_59_dialog_content = "Todavía estoy un poco preocupado. Te estaré vigilando por telepatía.",
  ui_story_5038_50380701_60_dialog_content = "Si tienes algún problema, será mejor que me lo hagas saber a través de nuestro enlace, ¿entendido?",
  ui_story_5038_50380701_61_dialog_content = "Bien bien. ¡Solo espera y espera mis buenas noticias!",
  ui_story_5038_50380701_62_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5038_50380701_63_dialog_content = "Yaaaaah!!!",
  ui_story_5038_50380701_64_dialog_content = "¿Qué? ¡¿Qué es?! Liqing!",
  ui_story_5038_50380701_65_option_content = "¡Potencia de fuerza!",
  ui_story_5038_50380701_66_dialog_content = "(¡Tanta agua! ¡Demasiada agua! ¡Agua, agua, por todas partes...!)",
  ui_story_5038_50380701_67_dialog_content = "Wah... PlayerName! ¡Hay, como, agua POR TODAS PARTES!",
  ui_story_5038_50380701_68_dialog_content = "Estás en el mar, ¿qué esperabas?",
  ui_story_5038_50380701_69_dialog_content = "Espera, no estarás diciendo que le tienes miedo al agua, ¿verdad?",
  ui_story_5038_50380701_70_dialog_content = "Bueno, ¡duh! ¡A los gatos que no les gusta el agua no es ninguna novedad!",
  ui_story_5038_50380701_71_dialog_content = "(Oh, el pobre Liqing está temblando violentamente. El accidente de hace seis meses debe haberlo marcado profundamente).",
  ui_story_5038_50380701_72_dialog_content = "¡V-Vuelve, rápido! Trata de no moverte demasiado, y te izaré a ti y al bote de regreso...",
  ui_story_5038_50380701_73_dialog_content = "Huff... Huff",
  ui_story_5038_50380701_74_dialog_content = "Miau...",
  ui_story_5038_50380701_75_dialog_content = "¿Qué diablos estabas pensando? ¿Por qué insististe en bajar cuando estás tan aterrorizado por el agua?",
  ui_story_5038_50380701_76_dialog_content = "Pensé que podría hacerlo yo mismo...",
  ui_story_5038_50380701_77_dialog_content = "Umm... De todos modos, PlayerName, ahora que estamos aquí, me temo que tengo que pedirte un favor.",
  ui_story_5038_50380701_78_dialog_content = "Déjame adivinar: ¿estarás bien si voy contigo?",
  ui_story_5038_50380701_79_dialog_content = "Bueno, todos los demás están ocupados reparando el barco. Seamos rápidos al respecto.",
  ui_story_5038_50380701_80_dialog_content = "¡Está bien!",
  ui_story_5038_50380701_81_dialog_content = "(Antes de salir, probablemente debería refrescar mi memoria del protocolo de seguridad...)",
  ui_story_5038_50380701_82_dialog_content = "Graah!!",
  ui_story_5038_50380701_83_dialog_content = "Tienes que estar bromeando...",
  ui_story_5038_50380701_84_dialog_content = "¿Eligen ahora, de todos los tiempos, trepar por esa cuerda?",
  ui_story_5038_50380702_1_dialog_content = "¡Escúchenme, amigos! Estoy buscando un objeto que se parece a la silueta de la cabeza de un mono.",
  ui_story_5038_50380702_2_dialog_content = "Algo grande, redondo y resistente.",
  ui_story_5038_50380702_3_dialog_content = "Podría estar enredado con algunas cuerdas.",
  ui_story_5038_50380702_X3_dialog_content = "Entonces, tus amigos son... ¿estos peces?",
  ui_story_5038_50380702_4_dialog_content = "Ugh... *Tos*...",
  ui_story_5038_50380702_5_dialog_content = "¿Estás bien? ¿Sientes náuseas?",
  ui_story_5038_50380702_6_dialog_content = "Buzi dice que los médicos no deberían tratarse a sí mismos. Creo que esto es de lo que estaba hablando.",
  ui_story_5038_50380702_7_dialog_content = "¿Puedo hacer cualquier cosa por ti?",
  ui_story_5038_50380702_8_dialog_content = "Ya que preguntaste... Un buen rasguño en la barbilla sería genial—",
  ui_story_5038_50380702_9_dialog_content = "¡PERO! *Tose*... ¡Rasguños en la barbilla y todo eso es más estilo Tinytail!",
  ui_story_5038_50380702_10_dialog_content = "Ya no soy solo un gato, ¡así que obviamente no me gustarían esas cosas!",
  ui_story_5038_50380702_11_dialog_content = "(Que lindo...)",
  ui_story_5038_50380702_12_dialog_content = "Hablando de eso, ¿hay algún diablillo de donde vienes? PlayerName?",
  ui_story_5038_50380702_13_dialog_content = "Bueno, tengo algunos amigos aurorianos que son semihumanos.",
  ui_story_5038_50380702_14_dialog_content = "La mayoría de ellos son descendientes de semihumanos y aurorianos, y son bastante raros.",
  ui_story_5038_50380702_15_dialog_content = "Ya veo. Suena un poco diferente a fiendlings.",
  ui_story_5038_50380702_16_dialog_content = "¿Sabes que Tinytail es mi hermano mayor?",
  ui_story_5038_50380702_17_dialog_content = "¡¿T-Tu qué...?!",
  ui_story_5038_50380702_18_dialog_content = "¿Es por eso que Tianxian siempre te llama gatito? ¿Porque en realidad eres uno?",
  ui_story_5038_50380702_19_dialog_content = "E-Es muy grosero de su parte llamarme así.",
  ui_story_5038_50380702_20_dialog_content = "Pero usted está en lo correcto. En mi tierra natal, los diabólicos son animales que se han convertido en aurorianos.",
  ui_story_5038_50380702_21_dialog_content = "Las familias influyentes de Longzhou que abogan por la paz a menudo invitan a los niños a sus hogares como invitados.",
  ui_story_5038_50380702_22_dialog_content = "Funcionan como retenedores.",
  ui_story_5038_50380702_23_dialog_content = "Así es como llegué a conocer al Lin Guildmaster.",
  ui_story_5038_50380702_24_dialog_content = "Parece ser una persona que realmente valora la amistad.",
  ui_story_5038_50380702_25_dialog_content = "Ehh... Para ser honesto, apenas puedo entender una palabra de las cosas de negocios de las que todos esos viejos parlotean.",
  ui_story_5038_50380702_26_dialog_content = "Los Lin me invitaron a su mansión porque querían que los ayudara. <color=#FFB400>cuidar sus peces</color>.",
  ui_story_5038_50380702_27_dialog_content = "Sé que todos piensan que los gatos comen pescado, pero los peces de mar son mis amigos.",
  ui_story_5038_50380702_28_dialog_content = "¿Quieres decir que puedes comunicarte con el pez serpiente?",
  ui_story_5038_50380702_29_dialog_content = "Más o menos. Es cierto, pero mira la otra noche. No pude hacer nada para ayudar, en medio de una crisis...",
  ui_story_5038_50380702_30_dialog_content = "¡Vaya! Nuestros amigos acuáticos han respondido.",
  ui_story_5038_50380702_31_dialog_content = "La \"cabeza de mono\" está justo debajo de nosotros, PlayerName!",
  ui_story_5038_50380702_32_dialog_content = "¿En serio?",
  ui_story_5038_50380702_33_dialog_content = "Sí. Probablemente esté enredado en algas.",
  ui_story_5038_50380702_34_dialog_content = "Espera, déjame hurgar con mi red...",
  ui_story_5038_50380702_35_dialog_content = "Oye... Ho—",
  ui_story_5038_50380702_36_dialog_content = "Echale un vistazo, PlayerName.",
  ui_story_5038_50380702_37_dialog_content = "¡E-Eso es increíble!",
  ui_story_5038_50380702_38_dialog_content = "¡Casi como magia!",
  ui_story_5038_50380702_39_dialog_content = "Te dije que mis amigos del océano vendrían.",
  ui_story_5038_50380702_40_dialog_content = "Ahora que tenemos una nueva \"cabeza de mono\", ¡podemos contribuir a las reparaciones del barco!",
  ui_story_5038_50380702_41_dialog_content = "¡Sí, aunque tenemos que volver primero!",
  ui_story_5038_50380702_42_dialog_content = "Esto seguramente levantará el ánimo de todos a bordo.",
  ui_story_5038_50380702_43_dialog_content = "Muy bien.",
  ui_story_5038_50380702_44_dialog_content = "(Me pregunto cómo está...)",
  ui_story_5038_50380702_45_dialog_content = "<color=#e8d9bb>en las cubiertas</color>",
  ui_story_5038_50380702_46_dialog_content = "¡Oye! Liqing y PlayerName ¡están de vuelta!",
  ui_story_5038_50380702_47_dialog_content = "Te dije que esos dos estarían bien.",
  ui_story_5038_50380702_48_dialog_content = "Jeje, seguro que lo hiciste. Pero tampoco parecías tener mucho apetito antes.",
  ui_story_5038_50380702_49_dialog_content = "PlayerName, Liqing! ¡Lo que hiciste fue increíblemente arriesgado!",
  ui_story_5038_50380702_50_dialog_content = "¿Incluso pensaste en las consecuencias antes de irte?",
  ui_story_5038_50380702_51_dialog_content = "Mire, capitán.",
  ui_story_5038_50380702_52_dialog_content = "¡...!",
  ui_story_5038_50380702_53_dialog_content = "¿Una polea?",
  ui_story_5038_50380702_54_dialog_content = "Obviamente se ha sumergido en agua de mar, pero debería poder repararse después de una buena limpieza.",
  ui_story_5038_50380702_55_dialog_content = "¿Dónde lo encontraste?",
  ui_story_5038_50380702_56_dialog_content = "¡En el mar!",
  ui_story_5038_50380702_57_dialog_content = "¿Ustedes dos se escabulleron del barco?",
  ui_story_5038_50380702_58_dialog_content = "Eso fue algo increíblemente peligroso de hacer. Con todos absortos en su trabajo, ¿qué hubiera pasado si te metieras en problemas? Nadie habría sido capaz de ayudar.",
  ui_story_5038_50380702_59_dialog_content = "Pero estamos bien, ¿no? ¡No pasó nada malo en absoluto!",
  ui_story_5038_50380702_60_dialog_content = "Puede haber sido un poco arriesgado, pero terminó bien.",
  ui_story_5038_50380702_61_dialog_content = "Tú mismo lo dijiste, Yuebai. Este viaje estaba destinado a ser arriesgado.",
  ui_story_5038_50380702_62_dialog_content = "Gracias a Liqing, tenemos nuestra polea \"cabeza de mono\". ¡Él debe ser elogiado!",
  ui_story_5038_50380702_63_dialog_content = "Ustedes...",
  ui_story_5038_50380702_64_dialog_content = "Bien. No puedo negar que tener esto será de gran ayuda para el progreso de la reparación de la nave. Así que por eso, te agradezco.",
  ui_story_5038_50380702_65_dialog_content = "Pero será mejor que no vuelva a atraparte escapándote del barco sin permiso.",
  ui_story_5038_50380702_66_dialog_content = "Despedido. Ve a cenar.",
  ui_story_5038_50380702_67_dialog_content = "Venid aquí, chicos.",
  ui_story_5038_50380702_68_dialog_content = "Mientras todos estaban ocupados, Jiu volvió a cocinar algunos platos tradicionales de su hogar.",
  ui_story_5038_50380702_69_dialog_content = "¡mmm! ¡No me di cuenta de lo hambrienta que estaba!",
  ui_story_5038_50380702_70_dialog_content = "¡Huele bien, princesa Dantan! ¡¿No me digas que vamos a comer estofado de cerdo?!",
  ui_story_5038_50380702_71_dialog_content = "¡Qué agudo sentido del olfato! El almuerzo de hoy es de hecho <color=#FFB400>carne de cerdo braseado</color>!",
  ui_story_5038_50380702_72_dialog_content = "Obtienes un buen trozo de carne sólido y lo atas, lo colocas en una olla llena de varias especias y lo dejas hervir a fuego lento...",
  ui_story_5038_50380702_73_dialog_content = "Es posible que tengamos un poco de ingredientes limitados en el barco, pero creo que el sabor está lo suficientemente cerca.",
  ui_story_5038_50380702_74_dialog_content = "Ve y come. Todavía tengo algo de trabajo que hacer.",
  ui_story_5038_50380702_75_dialog_content = "Con la polea de reemplazo, debería poder terminar de reparar el mástil con bastante rapidez.",
  ui_story_5038_50380702_76_dialog_content = "Pronto podremos retomar la velocidad normal.",
  ui_story_5038_50380702_77_dialog_content = "¡Puedo ayudar!",
  ui_story_5038_50380702_78_dialog_content = "<color=#e8d9bb>Gruñido-</color>",
  ui_story_5038_50380702_79_dialog_content = "Jaja... Parece que deberías ir con ellos primero.",
  ui_story_5038_50380702_80_dialog_content = "Nunca se dirá que un invitado de los Lin fue puesto a trabajar con el estómago vacío.",
  ui_story_5038_50380801_1_dialog_content = "(La velocidad del barco puede volver a la normalidad, pero el estado del casco sigue siendo un poco preocupante).",
  ui_story_5038_50380801_2_dialog_content = "(Todos han estado trabajando sin parar, como si el Shadowind se hundiera si se detuvieran incluso por un segundo).",
  ui_story_5038_50380801_3_dialog_content = "(Parece que pensamos que agotarse es un antídoto para la preocupación).",
  ui_story_5038_50380801_4_dialog_content = "Navega un poco más a babor, tripulación. El viento ha cambiado.",
  ui_story_5038_50380801_5_dialog_content = "¡Sí!",
  ui_story_5038_50380801_6_dialog_content = "¿Cómo está la bodega de carga?",
  ui_story_5038_50380801_7_dialog_content = "Todavía hay fugas, así que tenemos que seguir enviando a alguien para que saque el agua.",
  ui_story_5038_50380801_8_dialog_content = "Por suerte no está empeorando y todavía podemos manejarlo.",
  ui_story_5038_50380801_9_dialog_content = "Entendí. Elabora un horario y túrnense para descansar.",
  ui_story_5038_50380801_10_dialog_content = "No tenemos idea de cuánto durarán estas circunstancias, por lo que debemos controlar nuestro ritmo.",
  ui_story_5038_50380801_11_dialog_content = "¡Sí!",
  ui_story_5038_50380801_12_dialog_content = "Espero que nuestro rumbo se mantenga. Me voy al puente para comprobar las cosas.",
  ui_story_5038_50380801_13_dialog_content = "(Yuebai está constantemente en movimiento. Ni siquiera se detiene cuando habla).",
  ui_story_5038_50380801_14_dialog_content = "(Ella tiene más en qué pensar que el resto de nosotros, y eso obviamente la presiona aún más).",
  ui_story_5038_50380801_15_dialog_content = "(Tal vez sus pasos puedan tapar algunos de los agujeros en The Shadowind).",
  ui_story_5038_50380801_16_dialog_content = "Otro avistamiento...",
  ui_story_5038_50380801_17_dialog_content = "¿Cuántos son ahora, Jiu?",
  ui_story_5038_50380801_18_dialog_content = "42, Su Alteza.",
  ui_story_5038_50380801_19_dialog_content = "Tantos ya.",
  ui_story_5038_50380801_20_dialog_content = "Siguen viniendo de la dirección a la que nos dirigimos... Es bastante preocupante.",
  ui_story_5038_50380801_21_dialog_content = "(Se ha visto mucha madera flotante desde la mañana).",
  ui_story_5038_50380801_22_dialog_content = "(La cabeza de mono de ayer era solo la punta del iceberg. Ahora estamos viendo los restos de innumerables naufragios, todos perdidos en el mar aquí).",
  ui_story_5038_50380801_23_dialog_content = "(Dantang descansa constantemente al costado del barco, mirando hacia el mar, contando cada pieza de madera flotante).",
  ui_story_5038_50380801_24_dialog_content = "(Solo nosotros damos testimonio de estos restos de aquellos que sucumbieron a las olas).",
  ui_story_5038_50380801_25_dialog_content = "¿Qué es preocupante? Creo que es una buena señal.",
  ui_story_5038_50380801_26_dialog_content = "Si hay escombros en nuestro camino, eso significa que estamos en el camino correcto.",
  ui_story_5038_50380801_27_dialog_content = "¿No crees que un océano totalmente desierto y vacío da mucho más miedo?",
  ui_story_5038_50380801_28_dialog_content = "(Liqing pasa, con pescado seco colgando de su boca).",
  ui_story_5038_50380801_29_dialog_content = "(Ha estado ayudando, pero siempre parece tener una actitud tan indiferente).",
  ui_story_5038_50380801_30_dialog_content = "(Tal vez está tratando de hacer un juego con todo el trabajo).",
  ui_story_5038_50380801_31_dialog_content = "Ahhh... Estoy agotado.",
  ui_story_5038_50380801_32_dialog_content = "El agua en la bodega de carga sigue llegando, sin importar cuánto aguantes.",
  ui_story_5038_50380801_33_dialog_content = "Decidió unirse a nosotros, PlayerName?",
  ui_story_5038_50380801_34_dialog_content = "Sí. Me dijeron que descansara un poco.",
  ui_story_5038_50380801_35_dialog_content = "(Tianxian es el mismo de siempre. Solo un parlanchín sin parar).",
  ui_story_5038_50380801_36_dialog_content = "Y con mucha razón. No es bueno cansarse.",
  ui_story_5038_50380801_37_dialog_content = "Cuando termine el rescate de hoy, habrá más mañana.",
  ui_story_5038_50380801_38_dialog_content = "Debemos ser más pacientes que el mismo océano en este viaje.",
  ui_story_5038_50380801_39_dialog_content = "Parece que tienes un dicho para todas las ocasiones.",
  ui_story_5038_50380801_40_dialog_content = "Por supuesto. Tengo que convencerme de afrontar estos interminables días con ecuanimidad.",
  ui_story_5038_50380801_41_dialog_content = "Sr. silla de ruedas siendo nuestro último recurso, si aún no está levantado y trabajando, entonces la situación no puede ser tan mala.",
  ui_story_5038_50380801_42_dialog_content = "No confunda la discapacidad con la ociosidad.",
  ui_story_5038_50380801_43_dialog_content = "¡Oye, mira quién es! ¡Señor Zhong!",
  ui_story_5038_50380801_44_dialog_content = "¡Pocas veces te vemos tomando un poco de aire en cubierta!",
  ui_story_5038_50380801_45_dialog_content = "No hay necesidad de que me trates como una especie de noble. No tengo ese tipo de poder en tierra, y menos en un barco.",
  ui_story_5038_50380801_46_dialog_content = "Es usted demasiado modesto, señor. Un tigre sin dientes sigue siendo una criatura formidable, digna de respeto. Mucho menos un ex Gran General.",
  ui_story_5038_50380801_47_dialog_content = "Realmente eres un experto en halagos.",
  ui_story_5038_50380801_48_dialog_content = "De hecho, tengo una idea que podría ayudar a aliviar algunas de nuestras dificultades actuales.",
  ui_story_5038_50380801_49_dialog_content = "Pero necesito tu ayuda para que funcione.",
  ui_story_5038_50380801_50_dialog_content = "¿En serio? ¿Qué es?",
  ui_story_5038_50380801_51_dialog_content = "¡Estaré feliz de ayudar!",
  ui_story_5038_50380801_52_dialog_content = "¡Sería un honor ayudar a un caballero tan sabio y talentoso!",
  ui_story_5038_50380801_53_dialog_content = "No es particularmente arduo. Me gustaría pedirte que me ayudes a recoger un poco de madera flotante.",
  ui_story_5038_50380801_54_dialog_content = "¿Recoger madera flotante?",
  ui_story_5038_50380801_55_dialog_content = "¿No podríamos recoger algunos con una red?",
  ui_story_5038_50380801_56_dialog_content = "¿Derecho? Si hay algo que no nos falta aquí, es madera flotante.",
  ui_story_5038_50380801_57_dialog_content = "No toda la madera flotante es utilizable. Por favor, recoge sólo los que te señalo.",
  ui_story_5038_50380801_58_dialog_content = "¿Eh? ¿En qué se diferencian?",
  ui_story_5038_50380801_59_dialog_content = "Olvida eso. Solo haz lo que dice por ahora, estoy seguro de que sabe de lo que está hablando.",
  ui_story_5038_50380801_60_dialog_content = "A ver si podemos quitarle una red a uno de los marineros.",
  ui_story_5038_50380801_61_dialog_content = "¡Transportar!",
  ui_story_5038_50380801_62_dialog_content = "¡Casi llegamos! ¡Un tirón más!",
  ui_story_5038_50380801_63_dialog_content = "¡Argh!",
  ui_story_5038_50380801_64_dialog_content = "<color=#e8d9bb>¡Golpe, golpe!</color>",
  ui_story_5038_50380801_65_dialog_content = "¡Uf! ¡Éxito!",
  ui_story_5038_50380801_66_dialog_content = "Éxito, mi cola.",
  ui_story_5038_50380801_67_dialog_content = "No veo ni medio pez ahí. ¿Llamas éxito a atrapar una plancha?",
  ui_story_5038_50380801_68_dialog_content = "liqing? No, esto no es para...",
  ui_story_5038_50380801_69_dialog_content = "Les pedí que me ayudaran a recogerlo.",
  ui_story_5038_50380801_70_dialog_content = "¿Eh? Eso es un poco extraño. ¿Qué tiene de especial un trozo de madera?",
  ui_story_5038_50380801_71_dialog_content = "Mire más de cerca la pieza que recogieron. No es una tabla normal.",
  ui_story_5038_50380801_72_dialog_content = "En los barcos, estas piezas se conocen comúnmente como \"orejas de conejo\".",
  ui_story_5038_50380801_73_dialog_content = "¡Ay! Ahora que lo mencionas, realmente se parece a las orejas de conejo.",
  ui_story_5038_50380801_74_dialog_content = "¡Eso tiene sentido! ¡Lord Zhong, realmente diste en el clavo!",
  ui_story_5038_50380801_75_dialog_content = "\"Orejas de conejo\" fue la última de las tres cosas que calculé con los hexagramas.",
  ui_story_5038_50380801_76_dialog_content = "¿Para qué se usa?",
  ui_story_5038_50380801_77_dialog_content = "Es una tabla especial adherida al exterior. Por lo general, solo hay dos por barco.",
  ui_story_5038_50380801_78_dialog_content = "Está elaborado con más meticulosidad que otros tablones y es resistente al agua.",
  ui_story_5038_50380801_79_dialog_content = "Por eso pedí que se recogiera.",
  ui_story_5038_50380801_80_dialog_content = "¿Estás... interesado en él porque es resistente al agua?",
  ui_story_5038_50380801_81_dialog_content = "Así es.",
  ui_story_5038_50380801_82_dialog_content = "Usted se estará preguntando por qué. Algo que es resistente al agua asegura que el agua no vaya a donde no debe ir.",
  ui_story_5038_50380801_83_dialog_content = "repeliendo el agua...",
  ui_story_5038_50380801_84_dialog_content = "¡Ay! ¡Ya veo! Es para la bodega de carga, ¿verdad?",
  ui_story_5038_50380801_85_dialog_content = "¡Planea usar estos tablones para detener las fugas!",
  ui_story_5038_50380801_86_dialog_content = "Muy inteligente, joven amigo.",
  ui_story_5038_50380801_87_dialog_content = "Simplemente clave la \"oreja de conejo\" contra la fuga.",
  ui_story_5038_50380801_88_dialog_content = "Es solo temporal, pero debería ayudar a aliviar un poco la presión, para que no todos nos abrumemos.",
  ui_story_5038_50380801_89_dialog_content = "¡Maravilloso! Como modelar flores falsas en un árbol real.",
  ui_story_5038_50380801_90_dialog_content = "¡Así que ESO es lo que significaba el palo de la fortuna!",
  ui_story_5038_50380801_91_dialog_content = "¡Suena como un gran plan!",
  ui_story_5038_50380801_92_dialog_content = "Si realmente funciona para detener la fuga, liberará a todos los demás para ayudar con otras cosas.",
  ui_story_5038_50380801_93_dialog_content = "¡Rápido, veamos si podemos detectar a otros!",
  ui_story_5038_50380801_94_dialog_content = "ya mirando, PlayerName.",
  ui_story_5038_50380801_95_dialog_content = "¡Mira allá! Otro de esos tablones de orejas de conejo.",
  ui_story_5038_50380801_96_dialog_content = "¡La red! ¡Apuro!",
  ui_story_5038_50380801_97_dialog_content = "¿El agua sigue llegando?",
  ui_story_5038_50380801_98_dialog_content = "Sí. No podemos aflojar, ni siquiera por un segundo.",
  ui_story_5038_50380801_99_dialog_content = "¡No te quedes ahí parado! Ayuda bajo fianza.",
  ui_story_5038_50380801_100_dialog_content = "Oh, lo siento...",
  ui_story_5038_50380801_101_dialog_content = "Oye, ¿alguien puede echarme una mano?",
  ui_story_5038_50380801_102_dialog_content = "¿Eh? ¿No es eso Liqing?",
  ui_story_5038_50380801_103_dialog_content = "¡Date prisa, es demasiado pesado!",
  ui_story_5038_50380801_104_dialog_content = "¡Viniendo! Qué es lo que tú...",
  ui_story_5038_50380801_105_dialog_content = "<color=#e8d9bb>¡Golpe, golpe!</color>",
  ui_story_5038_50380801_106_dialog_content = "¿Eh?",
  ui_story_5038_50380801_107_dialog_content = "¡Ay! Era demasiado pesado.",
  ui_story_5038_50380801_108_dialog_content = "Pero conseguirlo aquí cuenta como misión cumplida.",
  ui_story_5038_50380801_109_dialog_content = "¿Qué haces aquí con una tabla, Liqing?",
  ui_story_5038_50380801_110_dialog_content = "Todo es culpa de Zhong Xu por ponerme a trabajar.",
  ui_story_5038_50380801_111_dialog_content = "Dijo que estos tablones podrían sellar fugas.",
  ui_story_5038_50380801_112_dialog_content = "¿Lo sacaste del mar?",
  ui_story_5038_50380801_113_dialog_content = "Probablemente esté demasiado erosionado para ser útil.",
  ui_story_5038_50380801_114_dialog_content = "No lo creo, se siente bastante fuerte para mí.",
  ui_story_5038_50380801_115_dialog_content = "Adelante, siéntelo.",
  ui_story_5038_50380801_116_dialog_content = "Creo que es tu falta de fuerza el problema.",
  ui_story_5038_50380801_117_dialog_content = "Déjame ver...",
  ui_story_5038_50380801_118_dialog_content = "¡Espera un minuto, esto es una oreja de conejo!",
  ui_story_5038_50380801_119_dialog_content = "Ah-ha, ¿impresionado ahora?",
  ui_story_5038_50380801_120_dialog_content = "Oreja de conejo... Sabes qué, esto podría funcionar.",
  ui_story_5038_50380801_121_dialog_content = "¡Dame un martillo!",
  ui_story_5038_50380801_122_dialog_content = "¡Tres dos uno!",
  ui_story_5038_50380801_123_dialog_content = "<color=#e8d9bb>¡Golpe, golpe!</color>",
  ui_story_5038_50380801_124_dialog_content = "¡Vaya, otra más!",
  ui_story_5038_50380801_125_dialog_content = "Pan comido.",
  ui_story_5038_50380801_126_dialog_content = "¿N-No dices? Necesito recuperar el aliento...",
  ui_story_5038_50380801_127_dialog_content = "¿Qué estás haciendo?",
  ui_story_5038_50380801_128_dialog_content = "Estamos recogiendo madera flotante del mar, Capitán.",
  ui_story_5038_50380801_129_dialog_content = "Lord Zhong dice que los aparadores de estos barcos hundidos podrían ayudar a reparar la fuga.",
  ui_story_5038_50380801_130_dialog_content = "Las orejas de conejo...",
  ui_story_5038_50380801_131_dialog_content = "¡Lo hicimos! ¡Las orejas de conejo sellaron la fuga!",
  ui_story_5038_50380801_132_dialog_content = "¡Liqing ha vuelto! Entonces, ¿realmente funcionó?",
  ui_story_5038_50380801_133_dialog_content = "Sí. Usamos la oreja de conejo que acabamos de encontrar para sellar una fuga.",
  ui_story_5038_50380801_134_dialog_content = "Pero hay muchas más fugas en el casco y la tripulación necesita más orejas de conejo.",
  ui_story_5038_50380801_135_dialog_content = "No se queden ahí, gente. ¡Ve a buscar más!",
  ui_story_5038_50380801_136_dialog_content = "Vale, vale, me voy ahora mismo...",
  ui_story_5038_50380801_137_dialog_content = "Por favor, no te molestes con esto.",
  ui_story_5038_50380801_138_dialog_content = "Ya que funcionó, enviaré marineros para recuperar las orejas de conejo.",
  ui_story_5038_50380801_139_dialog_content = "Ningún huésped del Shadowind debería trabajar duro.",
  ui_story_5038_50380801_140_dialog_content = "¡Vale, tira!",
  ui_story_5038_50380801_141_dialog_content = "¡Oye!",
  ui_story_5038_50380801_142_dialog_content = "<color=#e8d9bb>¡Golpe, golpe!</color>",
  ui_story_5038_50380801_143_dialog_content = "¡Tengo uno aquí!",
  ui_story_5038_50380801_144_dialog_content = "<color=#e8d9bb>¡Golpe, golpe!</color>",
  ui_story_5038_50380801_145_dialog_content = "¡Pon estos ahí abajo!",
  ui_story_5038_50380801_146_dialog_content = "Se nos acabaron los clavos, vine a buscar más.",
  ui_story_5038_50380801_147_dialog_content = "Fácil allí, una cosa a la vez!",
  ui_story_5038_50380801_148_dialog_content = "El trabajo ha ido mucho más eficientemente después de que todos comenzaron a ayudar.",
  ui_story_5038_50380801_149_dialog_content = "He perdido la cuenta de cuántos tablones ya han recogido.",
  ui_story_5038_50380801_150_dialog_content = "Parece que podemos arreglar el casco inferior hoy.",
  ui_story_5038_50380801_151_dialog_content = "Oye, esta oreja de conejo aquí...",
  ui_story_5038_50380801_152_dialog_content = "Ven a ver esto, Liu.",
  ui_story_5038_50380801_153_dialog_content = "¿Qué, hay algún problema con eso?",
  ui_story_5038_50380801_154_dialog_content = "No. Parece familiar.",
  ui_story_5038_50380801_155_dialog_content = "Ya sabes, ahora que lo mencionas...",
  ui_story_5038_50380801_156_dialog_content = "¿No es esto del barco de pesca de Liu Ge?",
  ui_story_5038_50380801_157_dialog_content = "Sí. Se fue un día de primavera para pescar en el mar y nunca más se supo de él.",
  ui_story_5038_50380801_158_dialog_content = "No esperaba ver esto aquí...",
  ui_story_5038_50380801_159_dialog_content = "Ellos... ¿Reconocen los restos?",
  ui_story_5038_50380801_160_dialog_content = "En seguida.",
  ui_story_5038_50380801_161_dialog_content = "¿Solo de un tablero?",
  ui_story_5038_50380801_162_dialog_content = "La oreja de conejo es un accesorio muy especial de un barco.",
  ui_story_5038_50380801_163_dialog_content = "Solo hay dos en cada barco y en posiciones bastante prominentes.",
  ui_story_5038_50380801_164_dialog_content = "A los armadores les gusta grabar patrones en ellos para distinguir una embarcación de otra.",
  ui_story_5038_50380801_165_dialog_content = "¡Así fue como pudieron reconocerlo!",
  ui_story_5038_50380801_166_dialog_content = "Es una práctica común para la gente de mar de Longzhou.",
  ui_story_5038_50380801_167_dialog_content = "Lo noté, Capitán Yuebai, también examinando las \"orejas de conejo\" que recogimos.",
  ui_story_5038_50380801_168_dialog_content = "Debes haber identificado muchas más de estas naves que tu tripulación.",
  ui_story_5038_50380801_169_dialog_content = "Si...",
  ui_story_5038_50380801_170_dialog_content = "Algunos eran barcos de pasajeros que chocaron con los huracanes en las temporadas de verano y nunca regresaron.",
  ui_story_5038_50380801_171_dialog_content = "Sus llamativas \"orejas de conejo\" los hacían fácilmente reconocibles.",
  ui_story_5038_50380801_172_dialog_content = "Hay muy pocos barcos de pesca, porque los pescadores conocen los peligros que encierra el océano.",
  ui_story_5038_50380801_173_dialog_content = "Pero dada la recesión económica del año, algunos aún optaron por correr el riesgo.",
  ui_story_5038_50380801_174_dialog_content = "La mayoría de estas partes, sin embargo, son de barcos mercantes.",
  ui_story_5038_50380801_175_dialog_content = "Codiciaron las riquezas del continente del otro lado y trataron de seguir al Shadowind original.",
  ui_story_5038_50380801_176_dialog_content = "Pero hasta la fecha, el Shadowind sigue siendo el único barco que atraviesa las dos tierras de forma segura.",
  ui_story_5038_50380801_177_dialog_content = "Aah...",
  ui_story_5038_50380801_178_dialog_content = "Acabo de darme cuenta de la gravedad de la situación.",
  ui_story_5038_50380801_179_dialog_content = "Solo hay dos \"orejas de conejo\" en un barco.",
  ui_story_5038_50380801_180_dialog_content = "En otras palabras, por cada dos orejas de conejo que encontramos, hay un barco hundido más.",
  ui_story_5038_50380801_181_dialog_content = "Aquellos que son reconocibles desencadenan una avalancha de recuerdos.",
  ui_story_5038_50380801_182_dialog_content = "Los que no lo son son solo forraje para los números.",
  ui_story_5038_50380801_183_dialog_content = "Y ya sacamos tantas orejas de conejo...",
  ui_story_5038_50380801_184_dialog_content = "Esto es lo que heredamos al surcar los mares.",
  ui_story_5038_50380801_185_dialog_content = "El mar no perdona a nadie. Nos basamos en la experiencia de aquellos que navegaron antes.",
  ui_story_5038_50380801_186_dialog_content = "Las reparaciones están casi listas.",
  ui_story_5038_50380801_187_dialog_content = "Barco mercante, barco de pesca, este también es un barco mercante...",
  ui_story_5038_50380801_188_dialog_content = "Un barco mercante, otro barco mercante...",
  ui_story_5038_50380801_189_dialog_content = "¿Qué estás escribiendo, Dantang?",
  ui_story_5038_50380801_190_dialog_content = "Oh, estoy resolviendo los orígenes de estas orejas de conejo.",
  ui_story_5038_50380801_191_dialog_content = "El capitán dijo que deberíamos reportarlos cuando volvamos a Longzhou.",
  ui_story_5038_50380801_192_dialog_content = "Entiendo...",
  ui_story_5038_50380801_193_dialog_content = "Terminé de contar todos los que había en la bodega. ¿Hay algunos nuevos?",
  ui_story_5038_50380801_194_dialog_content = "No. Acabamos de salir de esa zona llenos de madera flotante.",
  ui_story_5038_50380801_195_dialog_content = "Además, lo que tenemos debería ser suficiente.",
  ui_story_5038_50380801_196_dialog_content = "La bodega está casi arreglada. Todos están terminando las cosas ahora.",
  ui_story_5038_50380801_197_dialog_content = "Eso es genial. Supongo que puedo hacer lo mismo.",
  ui_story_5038_50380801_198_dialog_content = "Lástima que no encontré ninguna pista...",
  ui_story_5038_50380801_199_dialog_content = "¿Dirige?",
  ui_story_5038_50380801_200_dialog_content = "Sí, iba a buscar pistas sobre The Compass.",
  ui_story_5038_50380801_201_dialog_content = "Muchos de estos barcos hundidos navegaban en la misma flota que el Shadowind original.",
  ui_story_5038_50380801_202_dialog_content = "Dado que todos se hundieron, supuse que las \"orejas de conejo\" del viejo Shadowind podrían recuperarse en algún momento.",
  ui_story_5038_50380801_203_dialog_content = "Excepto que no es tan simple como pensé que sería.",
  ui_story_5038_50380801_204_dialog_content = "Eso tiene sentido. Las pistas sobre el paradero del viejo Shadowind podrían estar entre los restos.",
  ui_story_5038_50380801_205_dialog_content = "Deberíamos hacer una búsqueda exhaustiva ya que The Compass es muy importante.",
  ui_story_5038_50380801_206_dialog_content = "¿Deberíamos hablar con el capitán?",
  ui_story_5038_50380801_207_dialog_content = "Pero pensándolo bien, Zhong Xu no parecía demasiado preocupado por las orejas de conejo.",
  ui_story_5038_50380801_208_dialog_content = "Tal vez estaba seguro de que ninguno de ellos sería de Shadowind.",
  ui_story_5038_50380801_209_dialog_content = "¿Cómo podía estar tan seguro?",
  ui_story_5038_50380801_210_dialog_content = "¿Quizás tenían una forma única, fácilmente reconocible desde la distancia?",
  ui_story_5038_50380801_211_dialog_content = "Eso suena un poco hiperbólico.",
  ui_story_5038_50380801_212_dialog_content = "Nadie puede distinguir algo tan pequeño desde la distancia en el mar.",
  ui_story_5038_50380801_213_dialog_content = "Un momento, ¿y si el viejo Shadowind no tuviera orejas de conejo?",
  ui_story_5038_50380801_214_dialog_content = "No, incluso si no fuera así, sus otras partes aún deberían estar entre los restos.",
  ui_story_5038_50380801_215_dialog_content = "Pero Zhong Xu no mostró ningún interés en ninguno de los restos en absoluto...",
  ui_story_5038_50380801_216_dialog_content = "Podría ser...",
  ui_story_5038_50380801_217_dialog_content = "¡Es natural no encontrar restos del antiguo Shadowind!",
  ui_story_5038_50380801_218_dialog_content = "Nunca se convirtió en escombros en primer lugar.",
  ui_story_5038_50380801_219_dialog_content = "Qué... ¡¿De dónde vienes, Liqing?!",
  ui_story_5038_50380801_220_dialog_content = "No se arruinó...",
  ui_story_5038_50380801_221_dialog_content = "Los barcos perdidos y los naufragios son dos cosas diferentes.",
  ui_story_5038_50380801_222_dialog_content = "Tiene The Compass a bordo para mantenerlo a salvo, entonces, ¿cómo podría hundirse?",
  ui_story_5038_50380801_223_dialog_content = "¿La brújula es tan poderosa?",
  ui_story_5038_50380801_224_dialog_content = "Por supuesto. De lo contrario, no tendrías tanta gente persiguiéndolo.",
  ui_story_5038_50380801_225_dialog_content = "De todos modos, ahora no es el momento de discutir esto.",
  ui_story_5038_50380801_226_dialog_content = "La cena está por comenzar. Todo el mundo te está esperando.",
  ui_story_5038_50380801_227_dialog_content = "Sígueme.",
  ui_story_5038_50380801_228_dialog_content = "¿Todo el mundo? ¿Te refieres a todos en todo el barco?",
  ui_story_5038_50380801_229_dialog_content = "Sí. El barco está arreglado, por lo que todos tenemos un raro momento libre por una vez.",
  ui_story_5038_50380801_230_dialog_content = "No nos detengas. Incluso vino el anciano Zhong Xu.",
  ui_story_5038_50380801_231_dialog_content = "¡Date prisa!",
  ui_story_5038_50380801_232_dialog_content = "¡Ahí estás, por fin!",
  ui_story_5038_50380801_233_dialog_content = "¿Te atrajo finalmente el olor a comida?",
  ui_story_5038_50380801_234_dialog_content = "¡Toma asiento aquí!",
  ui_story_5038_50380801_235_dialog_content = "Wow, es animado aquí!",
  ui_story_5038_50380801_236_dialog_content = "¡Vaya, huele genial!",
  ui_story_5038_50380801_237_dialog_content = "Por supuesto. Hicieron todo lo posible en la galera.",
  ui_story_5038_50380801_238_dialog_content = "¡Ahora esto es lo que llamas una fiesta de celebración!",
  ui_story_5038_50380801_239_dialog_content = "Fiesta de celebración?",
  ui_story_5038_50380801_240_dialog_content = "Sí, celebrando que arreglamos el Shadowind y reanudamos el viaje.",
  ui_story_5038_50380801_241_dialog_content = "Pero espera, no debería estar robándole palabras al capitán ahora. ¡Capitán, adelante!",
  ui_story_5038_50380801_242_dialog_content = "¿M-Yo?",
  ui_story_5038_50380801_243_dialog_content = "Lo siento, pero no soy de palabras.",
  ui_story_5038_50380801_244_dialog_content = "Todo el mundo... disfruten del festín, supongo.",
  ui_story_5038_50380801_245_dialog_content = "Siéntase libre de pedir cualquier plato que desee. Mientras lo tengamos, lo obtendrás.",
  ui_story_5038_50380801_246_dialog_content = "¿En serio? ¡El jamón curado en la despensa para mí, entonces!",
  ui_story_5038_50380801_247_dialog_content = "¡Estoy tan harto de comer pescado todos los días!",
  ui_story_5038_50380801_248_dialog_content = "Oye, ¿qué tiene de malo el pescado?",
  ui_story_5038_50380801_249_dialog_content = "¡Me lo llevaré todo si no lo quieres!",
  ui_story_5038_50380801_250_dialog_content = "Está bastante lejos de los demás, Lord Zhong.",
  ui_story_5038_50380801_251_dialog_content = "¿Debería traerte algo de comida?",
  ui_story_5038_50380801_252_dialog_content = "Todo está bien. Este lugar tranquilo me queda muy bien.",
  ui_story_5038_50380801_253_dialog_content = "¿No te gustan las reuniones ruidosas?",
  ui_story_5038_50380801_254_dialog_content = "Todo lo contrario, yo sí.",
  ui_story_5038_50380801_255_dialog_content = "Cuando era funcionario, asistía a mi parte de funciones sociales.",
  ui_story_5038_50380801_256_dialog_content = "No fue hasta que me jubilé que me di cuenta de que es mucho mejor observar desde lejos.",
  ui_story_5038_50380801_257_dialog_content = "Disfruto absorbiendo todas las emociones mucho más que aquellos que realmente se deleitan con ellas.",
  ui_story_5038_50380801_258_dialog_content = "Ya veo... Eso es muy profundo...",
  ui_story_5038_50380801_259_dialog_content = "¡Aquí estás, Jiu!",
  ui_story_5038_50380801_260_dialog_content = "Me asustó, señorita...",
  ui_story_5038_50380801_261_dialog_content = "La tripulación de allí quiere bailar. ¿Vienes?",
  ui_story_5038_50380801_262_dialog_content = "¡Eres el mejor bailarín que conozco!",
  ui_story_5038_50380801_263_dialog_content = "Me siento halagado, pero no soy tan bueno...",
  ui_story_5038_50380801_264_dialog_content = "¡Entonces vamos a tomar algo para comer! ¡Están sirviendo platos nuevos ahora mismo!",
  ui_story_5038_50380801_265_dialog_content = "¡La buena comida se va rápido!",
  ui_story_5038_50380801_266_dialog_content = "¡Pareces muy emocionado!",
  ui_story_5038_50380801_267_dialog_content = "¡Porque estoy súper feliz!",
  ui_story_5038_50380801_268_dialog_content = "Nosotros mismos izamos las velas allí y fijamos el barco bajo nuestros pies con nuestras propias manos.",
  ui_story_5038_50380801_269_dialog_content = "¿No es tan asombroso?",
  ui_story_5038_50380801_270_dialog_content = "Partimos en este viaje, y todos terminaron en el mismo barco.",
  ui_story_5038_50380801_271_dialog_content = "Si, tienes razón. Shadowind está empezando a sentirse como en casa.",
  ui_story_5038_50380801_272_dialog_content = "Mira, eso es algo que solo los pasajeros como nosotros sentiríamos.",
  ui_story_5038_50380801_273_dialog_content = "Por supuesto, hay otro tipo de felicidad que todos a bordo pueden disfrutar.",
  ui_story_5038_50380801_274_dialog_content = "Échales un vistazo.",
  ui_story_5038_50380801_275_dialog_content = "¡Por fin, después de tanto trabajo!",
  ui_story_5038_50380801_276_dialog_content = "Finalmente dormiremos bien esta noche.",
  ui_story_5038_50380801_277_dialog_content = "Sí, ya no tenemos que arreglar el mástil ni achicar el agua.",
  ui_story_5038_50380801_278_dialog_content = "Regresaremos a Longzhou por fin.",
  ui_story_5038_50380901_1_dialog_content = "<color=#e8d9bb>5 días después...</color>",
  ui_story_5038_50380901_2_dialog_content = "Todo funciona y funciona bien, capitán.",
  ui_story_5038_50380901_3_dialog_content = "Todavía hay una pequeña fuga en la bodega, pero no empeoró de la noche a la mañana.",
  ui_story_5038_50380901_4_dialog_content = "Gracias por el informe.",
  ui_story_5038_50380901_5_dialog_content = "¿Se han eliminado las provisiones húmedas?",
  ui_story_5038_50380901_6_dialog_content = "Sí. Tiramos por la borda los que estaban completamente arruinados y estamos secando al sol los que están en condiciones aceptables en la cubierta.",
  ui_story_5038_50380901_7_dialog_content = "Sin embargo, ahora no nos queda mucha comida.",
  ui_story_5038_50380901_8_dialog_content = "Alimento...",
  ui_story_5038_50380901_9_dialog_content = "¿Cuánta agua dulce nos queda?",
  ui_story_5038_50380901_10_dialog_content = "Suficiente para aproximadamente medio mes.",
  ui_story_5038_50380901_11_dialog_content = "¿A qué distancia estamos de la costa, capitán?",
  ui_story_5038_50380901_12_dialog_content = "Lo siento, pero eso aún no está determinado en este momento.",
  ui_story_5038_50380901_13_dialog_content = "Los gráficos están incompletos para esta región y sufrimos un ataque.",
  ui_story_5038_50380901_14_dialog_content = "Estamos solos en un territorio desconocido.",
  ui_story_5038_50380901_15_dialog_content = "Dígales a todos que conserven nuestras provisiones por ahora y traten de pescar con más frecuencia.",
  ui_story_5038_50380901_16_dialog_content = "Lo mismo con el agua dulce. Úselo juiciosamente fuera del consumo normal.",
  ui_story_5038_50380901_17_dialog_content = "Estás despedido.",
  ui_story_5038_50380901_18_dialog_content = "Sí, capitán.",
  ui_story_5038_50380901_19_dialog_content = "<color=#e8d9bb>5 días más después</color>",
  ui_story_5038_50380901_20_dialog_content = "El almuerzo volvió a ser bastante escaso.",
  ui_story_5038_50380901_21_dialog_content = "Sí, pero no hay nada que podamos hacer.",
  ui_story_5038_50380901_22_dialog_content = "¿Estás lleno?",
  ui_story_5038_50380901_23_dialog_content = "Ni siquiera cerca. Apenas me dieron un bocado.",
  ui_story_5038_50380901_24_dialog_content = "Le di mi porción a Tinytail.",
  ui_story_5038_50380901_25_dialog_content = "¿Qué? ¡No puedes hacer eso, todavía estás creciendo!",
  ui_story_5038_50380901_26_dialog_content = "¡¿E-Eso es todo lo que te preocupa?!",
  ui_story_5038_50380901_27_dialog_content = "Iré a ver cómo van las cosas en la cubierta.",
  ui_story_5038_50380901_28_dialog_content = "Si tienes suerte, tendrás pescado para la cena.",
  ui_story_5038_50380901_29_dialog_content = "¿Pez? ¿De verdad, miau?",
  ui_story_5038_50380901_30_dialog_content = "Si tienes suerte.",
  ui_story_5038_50380901_31_dialog_content = "No soy... bueno pescando...",
  ui_story_5038_50380901_32_dialog_content = "De todos modos... espera aquí...",
  ui_story_5038_50380901_33_dialog_content = "Te tambaleas... ¿Qué pasa?",
  ui_story_5038_50380901_34_dialog_content = "¿Qué? No soy yo...",
  ui_story_5038_50380901_35_dialog_content = "Déjame tomarte el pulso.",
  ui_story_5038_50380901_36_dialog_content = "Yo...",
  ui_story_5038_50380901_37_dialog_content = "Estás enfermo.",
  ui_story_5038_50380901_38_dialog_content = "<color=#e8d9bb>5 días más después</color>",
  ui_story_5038_50380901_39_dialog_content = "¡Deja de correr, Tinytail!",
  ui_story_5038_50380901_40_dialog_content = "¡No quiero verte caer al océano!",
  ui_story_5038_50380901_41_dialog_content = "Maullar.",
  ui_story_5038_50380901_42_dialog_content = "Es mi negocio cuidar de ti. ¿No te das cuenta del viento que hace?",
  ui_story_5038_50380901_43_dialog_content = "Una sola ráfaga podría llevarte a quién sabe dónde.",
  ui_story_5038_50380901_44_dialog_content = "Vuelve a la cabaña conmigo.",
  ui_story_5038_50380901_45_dialog_content = "¡Miaauu!",
  ui_story_5038_50380901_46_dialog_content = "*Jadeando* Caray, realmente puede correr.",
  ui_story_5038_50380901_47_dialog_content = "No te preocupes. Los animales tienen instintos mucho más agudos que nosotros.",
  ui_story_5038_50380901_48_dialog_content = "Somos nosotros los que tenemos que confiar en ellos cuando surge un verdadero peligro.",
  ui_story_5038_50380901_49_dialog_content = "¡Me alegro de verte aquí, Yuebai!",
  ui_story_5038_50380901_50_dialog_content = "¿Has visto Liqing? No lo he visto nada hoy.",
  ui_story_5038_50380901_51_dialog_content = "No tendría que preocuparme por Tinytail si estuviera cerca.",
  ui_story_5038_50380901_52_dialog_content = "Está ocupado con los pacientes.",
  ui_story_5038_50380901_53_dialog_content = "Dos tripulantes más bajaron con fiebre hoy.",
  ui_story_5038_50380901_54_dialog_content = "Debe estar ocupado.",
  ui_story_5038_50380901_55_dialog_content = "Más enfermedad...",
  ui_story_5038_50380901_56_dialog_content = "¿Cuánto falta para llegar a Longzhou, Yuebai?",
  ui_story_5038_50380901_57_dialog_content = "...",
  ui_story_5038_50380901_58_dialog_content = "No lo sé...",
  ui_story_5038_50380901_59_dialog_content = "(Suena un poco abatida...)",
  ui_story_5038_50380901_60_dialog_content = "(Tal vez porque simplemente no sabe cómo responder).",
  ui_story_5038_50380901_61_dialog_content = "(Podemos recurrir a Yuebai, pero ¿a quién puede recurrir ella?)",
  ui_story_5038_50380901_62_dialog_content = "El mar es inmenso. Longzhou está mucho más allá del horizonte, fuera de mi vista.",
  ui_story_5038_50380901_63_dialog_content = "Solo puedo ocuparme de las cosas que están a mi alcance, que puedo ver.",
  ui_story_5038_50380901_64_dialog_content = "Deberías volver a tu cabaña. Se acerca una tormenta.",
  ui_story_5038_50380901_65_dialog_content = "<color=#e8d9bb>El día siguiente</color>",
  ui_story_5038_50380901_66_dialog_content = "Capitán, amarramos todo en la cubierta y toda la tripulación también está acomodada.",
  ui_story_5038_50380901_67_dialog_content = "¿Tenemos suficiente lastre?",
  ui_story_5038_50380901_68_dialog_content = "Sí. El peso debe soportar el oleaje.",
  ui_story_5038_50380901_69_dialog_content = "Bien, deberíamos terminar con las medidas preventivas entonces.",
  ui_story_5038_50380901_70_dialog_content = "Espera mis órdenes en la popa.",
  ui_story_5038_50380901_71_dialog_content = "Um, ¿no deberíamos plegar las velas, Capitán?",
  ui_story_5038_50380901_72_dialog_content = "No. Vamos a toda vela.",
  ui_story_5038_50380901_73_dialog_content = "¿En la tormenta?",
  ui_story_5038_50380901_74_dialog_content = "¡Eso es demasiado peligroso! ¡No podremos controlar la nave!",
  ui_story_5038_50380901_75_dialog_content = "¡Sin mencionar que más Eclipsites podrían abordar la nave como antes!",
  ui_story_5038_50380901_76_dialog_content = "Lo sé, pero no podemos darnos el lujo de esperar más.",
  ui_story_5038_50380901_77_dialog_content = "El tiempo también es un adversario ahora.",
  ui_story_5038_50380901_78_dialog_content = "Perderemos nuestra oportunidad de llegar a la costa si nos detenemos ahora.",
  ui_story_5038_50380901_79_dialog_content = "Pero...",
  ui_story_5038_50380901_80_dialog_content = "Tenemos que aprovechar todo el viento que tenemos, incluso dentro de una tormenta.",
  ui_story_5038_50380901_81_dialog_content = "En cuanto a los Eclipsites, son los intrusos los que deberían temer poner un pie a bordo de esta nave, no nosotros.",
  ui_story_5038_50380901_82_dialog_content = "No tenemos escasez de invitados a bordo en busca de acción.",
  ui_story_5038_50380901_83_dialog_content = "Ya que lo pones así...",
  ui_story_5038_50380901_84_dialog_content = "¡Ay, lo que sea! Solo soy un marinero. Son las órdenes del capitán.",
  ui_story_5038_50380901_85_dialog_content = "Bien. Ponte en posición en la popa.",
  ui_story_5038_50380901_86_dialog_content = "La oleada llegará muy pronto. Estén atentos a mis pedidos.",
  ui_story_5038_50380901_87_dialog_content = "¡Sí!",
  ui_story_5038_50381001_1_dialog_content = "(La tormenta ha sacudido a Shadowind durante todo un día.)",
  ui_story_5038_50381001_2_dialog_content = "(Nos hemos topado con tantos problemas, desde mareos, hasta bancos de peces atacando, hasta eclipses).",
  ui_story_5038_50381001_3_dialog_content = "(Pero justo ahora, el ruido aterrador del vendaval rasgando las velas finalmente comenzó a disminuir considerablemente).",
  ui_story_5038_50381001_4_dialog_content = "(Así es como sabemos que lo logramos).",
  ui_story_5038_50381001_5_dialog_content = "La cubierta parece estar a salvo ahora.",
  ui_story_5038_50381001_6_dialog_content = "Parecería de esa manera. ¿Hemos superado la tormenta?",
  ui_story_5038_50381001_7_dialog_content = "Sí, la parte más difícil del viaje ha terminado.",
  ui_story_5038_50381001_8_dialog_content = "Sólo turbulencias menores de ahora en adelante, nada que la precaución no pueda resolver.",
  ui_story_5038_50381001_9_dialog_content = "Gracias a Dios se acabó.",
  ui_story_5038_50381001_10_dialog_content = "Voy a vomitar todos mis órganos si el barco sigue balanceándose.",
  ui_story_5038_50381001_11_dialog_content = "¿Estás bien, Tianxian? Te ves bastante rudo.",
  ui_story_5038_50381001_12_dialog_content = "Estoy aguantando. Tener aire fresco en la cubierta ayuda mucho.",
  ui_story_5038_50381001_13_dialog_content = "¿No es hora de comer, capitán?",
  ui_story_5038_50381001_14_dialog_content = "Tenemos que sacar algo de nosotros después de un día entero en esa tormenta al revés.",
  ui_story_5038_50381001_15_dialog_content = "Sí tienes razón.",
  ui_story_5038_50381001_16_dialog_content = "Marinero, informe a los cocineros de la cocina para que preparen la cena.",
  ui_story_5038_50381001_17_dialog_content = "En seguida.",
  ui_story_5038_50381001_18_dialog_content = "Sin embargo, capitán, nos estamos quedando sin suministros, así que debemos racionarlos.",
  ui_story_5038_50381001_19_dialog_content = "Necesito saber cuántos días más vamos a estar navegando.",
  ui_story_5038_50381001_20_dialog_content = "... Eso es actualmente indeterminado.",
  ui_story_5038_50381001_21_dialog_content = "Llenemos los estómagos de todos primero.",
  ui_story_5038_50381001_22_dialog_content = "No, tal vez solo medio lleno.",
  ui_story_5038_50381001_23_dialog_content = "Oye, ¿cuántas raciones nos quedan?",
  ui_story_5038_50381001_24_dialog_content = "...",
  ui_story_5038_50381001_25_dialog_content = "Sé que lo sabes, así que dime.",
  ui_story_5038_50381001_26_dialog_content = "Entiendo que la situación es bastante grave, pero me gustaría saber qué tan grave.",
  ui_story_5038_50381001_27_dialog_content = "No podemos seguir así.",
  ui_story_5038_50381001_28_dialog_content = "¿Qué?",
  ui_story_5038_50381001_29_dialog_content = "Venir. Llama a todos para que empiecen a pescar.",
  ui_story_5038_50381001_30_dialog_content = "¿Ahora mismo? Pero hay trabajos que hacer—",
  ui_story_5038_50381001_31_dialog_content = "Los que no son importantes pueden esperar.",
  ui_story_5038_50381001_32_dialog_content = "Dígales a todos que hagan tiempo para pescar.",
  ui_story_5038_50381001_33_dialog_content = "De lo contrario, no vamos a tener nada para comer en unos días.",
  ui_story_5038_50381001_34_dialog_content = "¿Es tan grave...?",
  ui_story_5038_50381001_35_dialog_content = "Muy bien, reuniré a la tripulación.",
  ui_story_5038_50381001_36_dialog_content = "¡Esta red está llena!",
  ui_story_5038_50381001_37_dialog_content = "¡Rápido, ayúdame a levantarlo!",
  ui_story_5038_50381001_38_dialog_content = "¡Hola!",
  ui_story_5038_50381001_39_dialog_content = "¿Por qué toda la tripulación está pescando en la cubierta?",
  ui_story_5038_50381001_40_dialog_content = "¿Hay... algún problema con nuestros suministros de alimentos?",
  ui_story_5038_50381001_41_dialog_content = "Por supuesto. La comida es la necesidad más básica y primaria.",
  ui_story_5038_50381001_42_dialog_content = "El barco está bien ahora, pero ¿qué hay de nosotros? ¿Podemos soportar?",
  ui_story_5038_50381001_43_dialog_content = "Suspiro...",
  ui_story_5038_50381001_44_dialog_content = "Al menos estamos en el océano donde abundan los peces.",
  ui_story_5038_50381001_45_dialog_content = "No es tan simple.",
  ui_story_5038_50381001_46_dialog_content = "Incluso si a todos no les importa comer pescado todo el tiempo, seguimos consumiendo agua fresca todos los días.",
  ui_story_5038_50381001_47_dialog_content = "Cuando eso se haya ido, significará el final de nuestro viaje.",
  ui_story_5038_50381001_48_dialog_content = "Somos criaturas terrestres, después de todo.",
  ui_story_5038_50381001_49_dialog_content = "Una vez que estamos en el mar, comienza la cuenta regresiva.",
  ui_story_5038_50381001_50_dialog_content = "Cuenta regresiva, eh...",
  ui_story_5038_50381001_51_dialog_content = "Me pregunto cuánto tiempo nos queda.",
  ui_story_5038_50381001_52_dialog_content = "¡Atrapé otro! ¡También es grande!",
  ui_story_5038_50381001_53_dialog_content = "Muy bien, ¡necesitamos a todos para esto!",
  ui_story_5038_50381001_54_dialog_content = "¡Tres dos uno!",
  ui_story_5038_50381001_55_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5038_50381001_56_dialog_content = "¡Vaya, es enorme!",
  ui_story_5038_50381001_57_dialog_content = "¡Sí, premio gordo!",
  ui_story_5038_50381001_58_dialog_content = "¡Debería ser suficiente para cinco o seis personas!",
  ui_story_5038_50381001_59_dialog_content = "¡Sí, es enorme!",
  ui_story_5038_50381001_60_dialog_content = "¡Nunca antes había visto un pez tan grande!",
  ui_story_5038_50381001_61_dialog_content = "Vamos, llevémoslo a la cocina.",
  ui_story_5038_50381001_62_dialog_content = "¡Esto debería compensar lo poco que tuvimos esta noche!",
  ui_story_5038_50381001_63_dialog_content = "<size=50>¡Sí!</size>",
  ui_story_5038_50381001_64_dialog_content = "Liberarlo.",
  ui_story_5038_50381001_65_dialog_content = "¿Qué? ¿Quien dijo que?",
  ui_story_5038_50381001_66_dialog_content = "Fui yo, y dije, suéltalo.",
  ui_story_5038_50381001_67_dialog_content = "¿Señor Zhong? ¿Pero por qué?",
  ui_story_5038_50381001_68_dialog_content = "El tiene razón. Suéltelo de una vez.",
  ui_story_5038_50381001_69_dialog_content = "¡Mira de cerca, eso es un pez serpiente!",
  ui_story_5038_50381001_70_dialog_content = "¿¡Pez serpiente!?",
  ui_story_5038_50381001_X70_dialog_content = "Maldita sea, no estaba prestando atención en este momento. ¿No es lo que nos atacó antes...",
  ui_story_5038_50381001_71_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5038_50381001_72_dialog_content = "Ay...",
  ui_story_5038_50381001_73_dialog_content = "¡Whoa!",
  ui_story_5038_50381001_74_dialog_content = "¿Que esta pasando? ¿Chocamos con algo?",
  ui_story_5038_50381001_75_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5038_50381001_76_dialog_content = "¡E-Ahí está de nuevo!",
  ui_story_5038_50381001_77_dialog_content = "¡Mira abajo!",
  ui_story_5038_50381001_78_dialog_content = "¡Un banco de peces! ¡Nos están embistiendo!",
  ui_story_5038_50381001_79_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5038_50381001_80_dialog_content = "¡Estar atento! ¡Están saltando a cubierta!",
  ui_story_5038_50381002_1_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5038_50381002_2_dialog_content = "¡Ahhhh!",
  ui_story_5038_50381002_3_dialog_content = "¿Ahora que? Todavía nos están embistiendo...",
  ui_story_5038_50381002_4_dialog_content = "Acabamos de reparar el casco inferior. Si lo violan...",
  ui_story_5038_50381002_5_dialog_content = "¡Dame ese pez grande!",
  ui_story_5038_50381002_6_dialog_content = "¿Ah?",
  ui_story_5038_50381002_7_dialog_content = "¡Por favor, vuelve por donde viniste, viejo venerable!",
  ui_story_5038_50381002_8_dialog_content = "¡Aqui tienes!",
  ui_story_5038_50381002_9_dialog_content = "<color=#e8d9bb>¡Chapoteo!</color>",
  ui_story_5038_50381002_10_dialog_content = "Bien, todo debería estar bien ahora.",
  ui_story_5038_50381002_11_dialog_content = "¿Convocó a los otros peces?",
  ui_story_5038_50381002_12_dialog_content = "Sí. Los peces serpiente siempre están en cardúmenes y su sentido de unidad es fuerte.",
  ui_story_5038_50381002_13_dialog_content = "Toda la escuela acudirá en ayuda de cualquier miembro que tenga problemas.",
  ui_story_5038_50381002_14_dialog_content = "No es prudente enojar al pez serpiente en el mar.",
  ui_story_5038_50381002_15_dialog_content = "Mentalidad de manada... Qué rasgo único.",
  ui_story_5038_50381002_16_dialog_content = "Gracias por la advertencia, Liqing, Lord Zhong.",
  ui_story_5038_50381002_17_dialog_content = "Nos disculpamos por nuestra imprudencia.",
  ui_story_5038_50381002_18_dialog_content = "Está bien. Estamos todos en el mismo barco. Literalmente.",
  ui_story_5038_50381002_19_dialog_content = "No resultó nada malo, así que olvidemos lo que sucedió.",
  ui_story_5038_50381002_20_dialog_content = "No puedo creer que haya peces serpiente en estas aguas. No me digas que nos van a atacar de nuevo...",
  ui_story_5038_50381002_21_dialog_content = "No resistiremos otra ola...",
  ui_story_5038_50381002_22_dialog_content = "<color=#e8d9bb>El día siguiente</color>",
  ui_story_5038_50381002_23_dialog_content = "¡Otro pez serpiente! ¡Suéltalo ahora!",
  ui_story_5038_50381002_24_dialog_content = "Sé que sé. No es como si fuera la primera vez.",
  ui_story_5038_50381002_25_dialog_content = "Suspiro... ¿No pueden dejar de arruinar nuestras posibilidades de pescar algún pez?",
  ui_story_5038_50381002_26_dialog_content = "El séptimo...",
  ui_story_5038_50381002_27_dialog_content = "¡Ahí estás, Yuebai!",
  ui_story_5038_50381002_28_dialog_content = "Me mandaron a decirte que el almuerzo está listo.",
  ui_story_5038_50381002_29_dialog_content = "¿Adivina qué? ¡Vamos a tener una buena comida hoy! Aunque todo se cocina con pescado.",
  ui_story_5038_50381002_30_dialog_content = "Ustedes sigan adelante. Esperaré por ahora.",
  ui_story_5038_50381002_31_dialog_content = "¿Qué? ¿Cómo?",
  ui_story_5038_50381002_32_dialog_content = "¿Algo te esta molestando?",
  ui_story_5038_50381002_33_dialog_content = "Hay, y me gustaría averiguarlo, para aliviar mis preocupaciones.",
  ui_story_5038_50381002_34_dialog_content = "¿Qué es?",
  ui_story_5038_50381002_35_dialog_content = "Estos peces serpiente se están comportando de una manera muy inusual.",
  ui_story_5038_50381002_36_dialog_content = "Son una especie migratoria que viaja en grupos entre las costas de Astra y Longzhou.",
  ui_story_5038_50381002_37_dialog_content = "Nunca permanecen mucho tiempo en ninguna parte del océano, excepto brevemente cuando están cerca de la costa.",
  ui_story_5038_50381002_38_dialog_content = "Pero ahora, grupos de ellos parecen estar vagando por la zona.",
  ui_story_5038_50381002_39_dialog_content = "Cierto, la tripulación siguió atrapándolos hoy.",
  ui_story_5038_50381002_40_dialog_content = "No nos volverán a atacar, ¿verdad?",
  ui_story_5038_50381002_41_dialog_content = "Ese no parece ser el caso en este momento.",
  ui_story_5038_50381002_42_dialog_content = "Estoy haciendo todo lo posible para navegar alrededor de ellos para evitar que se repita lo que sucedió antes.",
  ui_story_5038_50381002_43_dialog_content = "Pero su comportamiento peculiar es indicativo de condiciones inusuales por delante.",
  ui_story_5038_50381002_44_dialog_content = "Algo aquí es más atractivo para el pez serpiente que incluso Longzhou.",
  ui_story_5038_50381002_45_dialog_content = "Mmm...",
  ui_story_5038_50381002_46_dialog_content = "Ve y almuerza. Tengo que mirar los gráficos.",
  ui_story_5038_50381002_47_dialog_content = "¿A qué lugar del mundo hemos navegado...?",
  ui_story_5038_50381002_48_dialog_content = "La dirección y la velocidad del viento ayer...",
  ui_story_5038_50381002_49_dialog_content = "No, un poco más al norte.",
  ui_story_5038_50381002_50_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_5038_50381002_51_dialog_content = "¿Quién es?",
  ui_story_5038_50381002_52_dialog_content = "Soy yo, Zhong Xu.",
  ui_story_5038_50381002_53_dialog_content = "¿Qué te trae por aquí, señor Zhong?",
  ui_story_5038_50381002_54_dialog_content = "He estado en este barco oscilante durante demasiado tiempo para saber hacia dónde vamos.",
  ui_story_5038_50381002_55_dialog_content = "¿Puedo preguntar dónde estamos ahora?",
  ui_story_5038_50381002_56_dialog_content = "Dónde...",
  ui_story_5038_50381002_57_dialog_content = "Francamente, con estos mapas incompletos, no puedo decirte nuestra ubicación precisa.",
  ui_story_5038_50381002_58_dialog_content = "Permítanme más tiempo para desenredar el problema.",
  ui_story_5038_50381002_59_dialog_content = "Por supuesto. No sé nada de navegación. Simplemente tenía curiosidad.",
  ui_story_5038_50381002_60_dialog_content = "Eres el capitán, así que estoy seguro de que tienes un plan.",
  ui_story_5038_50381002_61_dialog_content = "...",
  ui_story_5038_50381002_62_dialog_content = "A menos que, por supuesto, como yo, no lo hagas.",
  ui_story_5038_50381002_63_dialog_content = "Suspiro...",
  ui_story_5038_50381002_64_dialog_content = "Me temo que no tengo la arrogancia de afirmar salvajemente que sé dónde estamos, mi señor.",
  ui_story_5038_50381002_65_dialog_content = "Lo único que puedo prometer es que haré lo mejor que pueda.",
  ui_story_5038_50381002_66_dialog_content = "Nadie puede predecir el futuro.",
  ui_story_5038_50381002_67_dialog_content = "Admiro su determinación, capitán.",
  ui_story_5038_50381002_68_dialog_content = "Pero el futuro no es completamente impredecible en el mar.",
  ui_story_5038_50381002_69_dialog_content = "...",
  ui_story_5038_50381002_70_dialog_content = "¿Se refiere a La Brújula, señor?",
  ui_story_5038_50381002_71_dialog_content = "Sí. Entiendo que su prioridad es completar el viaje.",
  ui_story_5038_50381002_72_dialog_content = "Pero el barco se está quedando sin provisiones y prácticamente perdido. Solo The Compass puede ponernos en el camino correcto.",
  ui_story_5038_50381002_73_dialog_content = "La brújula...",
  ui_story_5038_50381002_74_dialog_content = "Incluso si es tan poderoso como dice, mi señor...",
  ui_story_5038_50381002_75_dialog_content = "No tenemos los recursos para buscarlo.",
  ui_story_5038_50381002_76_dialog_content = "¿Qué pasa si no tenemos que buscar mucho y lejos para encontrarlo?",
  ui_story_5038_50381002_77_dialog_content = "Ese tesoro de Lin está en esta misma vecindad.",
  ui_story_5038_50381002_78_dialog_content = "¡¿Qué?!",
  ui_story_5038_50381002_79_dialog_content = "Suspiro...",
  ui_story_5038_50381002_80_dialog_content = "Otra caja de comida estropeada...",
  ui_story_5038_50381002_81_dialog_content = "Sin embargo, probablemente no debería tirarlo.",
  ui_story_5038_50381002_82_dialog_content = "La comida estropeada es mejor que nada.",
  ui_story_5038_50381002_83_dialog_content = "¿Qué pasa con el agua dulce...",
  ui_story_5038_50381002_84_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5038_50381002_85_dialog_content = "Este barril está vacío.",
  ui_story_5038_50381002_86_dialog_content = "Nos vendría bien un poco de lluvia ahora mismo.",
  ui_story_5038_50381002_87_dialog_content = "¿Cuantos quedan? Veo uno, dos, tres...",
  ui_story_5038_50381002_88_dialog_content = "¡Ahí tienes!",
  ui_story_5038_50381002_89_dialog_content = "¿Qué estás haciendo acá?",
  ui_story_5038_50381002_90_dialog_content = "¡Sígueme, el capitán quiere verte ahora mismo!",
  ui_story_5038_50381101_1_dialog_content = "¡No te concentres solo en los peces, mantén tus ojos en el horizonte también!",
  ui_story_5038_50381101_2_dialog_content = "¡Tenemos que registrar el área inmediata, órdenes del capitán!",
  ui_story_5038_50381101_3_dialog_content = "¡Infórmame en el instante en que veas algo!",
  ui_story_5038_50381101_4_dialog_content = "¡Sí!",
  ui_story_5038_50381101_5_dialog_content = "Estamos buscando La Brújula, ¿verdad, Liqing?",
  ui_story_5038_50381101_6_dialog_content = "Por supuesto. ¿Por qué si no se ordenaría a todo el barco que mirara al mar?",
  ui_story_5038_50381101_7_dialog_content = "La brújula debería estar en la otra nave Lin...",
  ui_story_5038_50381101_8_dialog_content = "Así es, recuerdo que me dijiste que el barco no se hundió.",
  ui_story_5038_50381101_9_dialog_content = "Al menos no cuando Zhong Xu y yo nos fuimos.",
  ui_story_5038_50381101_10_dialog_content = "Entonces, ¿podría haber estado a la deriva solo todo este tiempo?",
  ui_story_5038_50381101_11_dialog_content = "Eso suena raro...",
  ui_story_5038_50381101_12_dialog_content = "¿No es eso algo bueno? Hace que sea más fácil de encontrar.",
  ui_story_5038_50381101_13_dialog_content = "Pero es probable que se haya topado con oleaje y vendavales después de todo este tiempo.",
  ui_story_5038_50381101_14_dialog_content = "Sin nadie que lo maneje, es probable que ya esté hundido.",
  ui_story_5038_50381101_15_dialog_content = "Para nada.",
  ui_story_5038_50381101_16_dialog_content = "¡No cuando lleva la preciosa brújula que estamos buscando!",
  ui_story_5038_50381101_17_dialog_content = "ya esta oscuro...",
  ui_story_5038_50381101_18_dialog_content = "¿Deberíamos dejar de fumar por el día?",
  ui_story_5038_50381101_19_dialog_content = "No podemos ver nada en la oscuridad.",
  ui_story_5038_50381101_20_dialog_content = "Pero hoy no avanzamos...",
  ui_story_5038_50381101_21_dialog_content = "Y nos estamos quedando sin tiempo.",
  ui_story_5038_50381101_22_dialog_content = "Por ahí!",
  ui_story_5038_50381101_23_dialog_content = "¿Qué es? ¡¿Donde?!",
  ui_story_5038_50381101_24_dialog_content = "¡Mira dónde estoy señalando!",
  ui_story_5038_50381101_25_dialog_content = "¡Sí, algo está flotando de esta manera!",
  ui_story_5038_50381101_26_dialog_content = "¿Es eso... una placa?",
  ui_story_5038_50381101_27_dialog_content = "Más cerca... Más cerca...",
  ui_story_5038_50381101_28_dialog_content = "¡Creo que puedo verlo!",
  ui_story_5038_50381101_29_dialog_content = "¡Es una placa! Se lee...",
  ui_story_5038_50381101_30_dialog_content = "Lin!",
  ui_story_5038_50381101_31_dialog_content = "¡Es del Lin Guild!",
  ui_story_5038_50381101_32_dialog_content = "¿El gremio Lin? ¿Podría ser el viejo Shadowind?",
  ui_story_5038_50381101_33_dialog_content = "¡Parece que se cayó al agua no hace mucho tiempo!",
  ui_story_5038_50381101_34_dialog_content = "¡Es una señal segura de que el barco está cerca!",
  ui_story_5038_50381101_35_dialog_content = "¿Dónde está el bote? ¡Lo estoy tomando!",
  ui_story_5038_50381101_36_dialog_content = "¿Ahora mismo?",
  ui_story_5038_50381101_37_dialog_content = "¿No deberías hablarlo primero con Yuebai?",
  ui_story_5038_50381101_38_dialog_content = "Eso no es necesario.",
  ui_story_5038_50381101_39_dialog_content = "Yuebai...?",
  ui_story_5038_50381101_40_dialog_content = "<color=#e8d9bb>¡Chapoteo!</color>",
  ui_story_5038_50381101_41_dialog_content = "¡E-Ella, simplemente se zambulló en el agua!",
  ui_story_5038_50381101_42_dialog_content = "¡Envidio a la gente que no le teme al agua!",
  ui_story_5038_50381101_43_dialog_content = "¡De ninguna manera, no puedo quedarme atrás!",
  ui_story_5038_50381101_44_dialog_content = "¡Rápido, baja el bote!",
  ui_story_5038_50381101_45_dialog_content = "(El agua tiene un fuerte olor a madera.)",
  ui_story_5038_50381101_46_dialog_content = "(Viene de más abajo.)",
  ui_story_5038_50381101_47_dialog_content = "(¿Se hundió el Lin Ship aquí?)",
  ui_story_5038_50381101_48_dialog_content = "(Esperemos que The Compass no se haya erosionado...)",
  ui_story_5038_50381101_49_dialog_content = "(Suspiro, solo puedo depender de otra cosa al final, después de todo).",
  ui_story_5038_50381101_50_dialog_content = "(Debería seguir bajando.)",
  ui_story_5038_50381101_51_dialog_content = "(Debo sumergirme más profundo.)",
  ui_story_5038_50381101_52_dialog_content = "(Al fondo del océano...)",
  ui_story_5038_50381101_53_dialog_content = "(Espera, es eso...)",
  ui_story_5038_50381101_54_dialog_content = "(!!!)",
  ui_story_5038_50381101_55_dialog_content = "(Barcos hundidos... múltiples.)",
  ui_story_5038_50381101_56_dialog_content = "(Así que así es como se ven los barcos que estoy tan acostumbrado a ver en el fondo del mar).",
  ui_story_5038_50381101_57_dialog_content = "(Se ven tan serenos, inusualmente tan.)",
  ui_story_5038_50381101_58_dialog_content = "(No importa lo que hayan encontrado antes, en el fondo del océano, solo hay serenidad).",
  ui_story_5038_50381101_59_dialog_content = "(La quietud roza lo aterrador.)",
  ui_story_5038_50381101_60_dialog_content = "(El mar devoró no sólo a los barcos, sino también a las tripulaciones y sus gritos de angustia.)",
  ui_story_5038_50381101_61_dialog_content = "(Absorbe todo en su alcance abisal; ni siquiera las olas se salvan).",
  ui_story_5038_50381101_62_dialog_content = "(Esto es como un cementerio de barcos hundidos, su último puerto).",
  ui_story_5038_50381101_63_dialog_content = "(Una vez anclados aquí, nunca más zarparán).",
  ui_story_5038_50381101_64_dialog_content = "(¿Debería echarles un vistazo?)",
  ui_story_5038_50381101_65_dialog_content = "(Pero no veo la nave Lin...)",
  ui_story_5038_50381101_66_dialog_content = "<color=#e8d9bb>¡Woosh!</color>",
  ui_story_5038_50381101_67_dialog_content = "Vale, el bote está listo para ti.",
  ui_story_5038_50381101_68_dialog_content = "¿Te vas ahora mismo?",
  ui_story_5038_50381101_69_dialog_content = "¡Sí, ahora!",
  ui_story_5038_50381101_70_dialog_content = "Déjame ir contigo, Liqing.",
  ui_story_5038_50381101_71_dialog_content = "Que vayas solo me hace un poco...",
  ui_story_5038_50381101_72_dialog_content = "A-¿No le tienes miedo al agua?",
  ui_story_5038_50381101_73_dialog_content = "mmm...",
  ui_story_5038_50381101_74_dialog_content = "Bien, puedes venir.",
  ui_story_5038_50381101_75_dialog_content = "El remo es demasiado largo para remar solo.",
  ui_story_5038_50381101_76_dialog_content = "¡Perfecto, vamos!",
  ui_story_5038_50381101_77_dialog_content = "Mueve el bote a—",
  ui_story_5038_50381101_78_dialog_content = "Graah...",
  ui_story_5038_50381101_79_dialog_content = "¡¿Qué fue eso?!",
  ui_story_5038_50381101_80_dialog_content = "¡Algo se ha apoderado del bote!",
  ui_story_5038_50381101_81_dialog_content = "¡¿Qué?!",
  ui_story_5038_50381101_82_dialog_content = "¿Quién sería lo suficientemente estúpido...",
  ui_story_5038_50381101_83_dialog_content = "¡Gaah!",
  ui_story_5038_50381101_84_dialog_content = "¡Whoa Whoa!",
  ui_story_5038_50381101_85_dialog_content = "¡¿De dónde salió tanta escoria?!",
  ui_story_5038_50381101_86_dialog_content = "¡Ahí abajo! ¡La cuerda atada al bote!",
  ui_story_5038_50381101_87_dialog_content = "¡Los eclipses están trepando por él!",
  ui_story_5038_50381102_1_dialog_content = "Grah...",
  ui_story_5038_50381102_2_dialog_content = "Esto apesta... Mi mano está sucia ahora.",
  ui_story_5038_50381102_3_dialog_content = "¿Algún otro eclipse?",
  ui_story_5038_50381102_4_dialog_content = "No, están todos muertos.",
  ui_story_5038_50381102_5_dialog_content = "Es bueno escuchar ¡Vamos, tenemos que irnos!",
  ui_story_5038_50381102_6_dialog_content = "¿Estás seguro de que quieres bajar allí?",
  ui_story_5038_50381102_7_dialog_content = "Podría ser más peligroso en el mar.",
  ui_story_5038_50381102_8_dialog_content = "Bueno, su capitán se lanzó directamente hacia abajo.",
  ui_story_5038_50381102_9_dialog_content = "Deberías preocuparte más por ella.",
  ui_story_5038_50381102_10_dialog_content = "Vamos, PlayerName.",
  ui_story_5038_50381102_11_dialog_content = "¡Seguro!",
  ui_story_5038_50381102_12_dialog_content = "No nos sigas, Tinytail.",
  ui_story_5038_50381102_13_dialog_content = "¿Miau?",
  ui_story_5038_50381102_14_dialog_content = "No te das cuenta de lo vasto que es el océano hasta que estás en un bote.",
  ui_story_5038_50381102_15_dialog_content = "¿Crees que encontraremos la vieja nave Lin?",
  ui_story_5038_50381102_16_dialog_content = "Bueno, la pista que tenemos implica que no está muy lejos.",
  ui_story_5038_50381102_17_dialog_content = "Pero...",
  ui_story_5038_50381102_18_dialog_content = "¿Te preocupa que se haya hundido?",
  ui_story_5038_50381102_19_dialog_content = "Sí.",
  ui_story_5038_50381102_20_dialog_content = "La placa flotaba sola como todos los restos que vimos antes.",
  ui_story_5038_50381102_21_dialog_content = "Tal vez el viento se lo llevó.",
  ui_story_5038_50381102_22_dialog_content = "O fue arrancado por Eclipsites que abordaron la nave.",
  ui_story_5038_50381102_23_dialog_content = "De cualquier manera, lo importante es el hecho de que sabemos que está en algún lugar cercano.",
  ui_story_5038_50381102_24_dialog_content = "Debemos encontrarlo.",
  ui_story_5038_50381102_25_dialog_content = "Me gusta la confianza que tienes en esa nave.",
  ui_story_5038_50381102_26_dialog_content = "Por supuesto. Lleva La Brújula.",
  ui_story_5038_50381102_27_dialog_content = "(Tengo la sensación de que Liqing está especialmente interesado en encontrar The Compass).",
  ui_story_5038_50381102_28_dialog_content = "(Pero su motivo es diferente al de Yuebai).",
  ui_story_5038_50381102_29_dialog_content = "(Puedo entender por qué tiene prisa, pero no cuán serio es Liqing al respecto).",
  ui_story_5038_50381102_30_dialog_content = "(Tal vez estoy más acostumbrado a lo relajado que suele ser).",
  ui_story_5038_50381102_31_dialog_content = "¿Qué está pasando?",
  ui_story_5038_50381102_32_dialog_content = "¿Niebla?",
  ui_story_5038_50381102_33_dialog_content = "Sí, estamos perdiendo visibilidad rápidamente.",
  ui_story_5038_50381102_34_dialog_content = "Esto es molesto. ¿Dónde está el viento cuando lo necesitas?",
  ui_story_5038_50381102_35_dialog_content = "¿Cómo se supone que encontraremos algo en esto?",
  ui_story_5038_50381102_36_dialog_content = "Uh, de repente pensé en algo aún más preocupante...",
  ui_story_5038_50381102_37_dialog_content = "¿Cómo vamos a volver a Shadowind si no podemos ver?",
  ui_story_5038_50381102_38_dialog_content = "¿Recuerdas en qué dirección está el barco?",
  ui_story_5038_50381102_39_dialog_content = "Uh, ¿de vuelta por ese camino?",
  ui_story_5038_50381102_40_dialog_content = "¿O tal vez a la izquierda?",
  ui_story_5038_50381102_41_dialog_content = "Así que no lo sabes.",
  ui_story_5038_50381102_42_dialog_content = "Si perdemos el barco...",
  ui_story_5038_50381102_43_dialog_content = "Vamos. No está tan mal.",
  ui_story_5038_50381102_44_dialog_content = "Aquí tenemos una caña de pescar. Podemos vivir de pescado durante unos días.",
  ui_story_5038_50381102_45_dialog_content = "Me gustaría vivir más que \"unos días\", muchas gracias...",
  ui_story_5038_50381102_46_dialog_content = "Además, si llegamos primero al barco viejo y a La Brújula...",
  ui_story_5038_50381102_47_dialog_content = "Incluso podríamos ganarles a Longzhou.",
  ui_story_5038_50381102_48_dialog_content = "¿Cómo empezamos a encontrar algo en tanta niebla?",
  ui_story_5038_50381102_49_dialog_content = "¿No deberíamos quedarnos quietos y esperar a que pase la niebla?",
  ui_story_5038_50381102_50_dialog_content = "Tienes un punto.",
  ui_story_5038_50381102_51_dialog_content = "<color=#e8d9bb>¡Chapoteo!</color>",
  ui_story_5038_50381102_52_dialog_content = "Aaaaaaaargh!!",
  ui_story_5038_50381102_53_dialog_content = "¿Qué es?",
  ui_story_5038_50381102_54_dialog_content = "Estoy todo empapado!!!!!!!",
  ui_story_5038_50381102_55_dialog_content = "Ponte detrás de mí, Liqing—",
  ui_story_5038_50381102_56_dialog_content = "Deja de gritar, soy solo yo.",
  ui_story_5038_50381102_57_dialog_content = "¿Yuebai?",
  ui_story_5038_50381102_58_dialog_content = "¿Saliste del océano?",
  ui_story_5038_50381102_59_dialog_content = "¿Ves algo más aquí?",
  ui_story_5038_50381102_60_dialog_content = "¿T-Tenías que seguir así?",
  ui_story_5038_50381102_61_dialog_content = "Uf, estoy tan asquerosamente mojada...",
  ui_story_5038_50381102_62_dialog_content = "Lo siento, no estoy acostumbrado a satisfacer las necesidades de un hidrófobo en el agua.",
  ui_story_5038_50381102_63_dialog_content = "Acaso...",
  ui_story_5038_50381102_64_dialog_content = "Seamos serios por un momento.",
  ui_story_5038_50381102_65_dialog_content = "Acabo de descubrir un cementerio de barcos ahí abajo.",
  ui_story_5038_50381102_66_dialog_content = "Así que realmente hay barcos hundidos...",
  ui_story_5038_50381102_67_dialog_content = "Espera, ¿buceaste hasta el fondo del océano?",
  ui_story_5038_50381102_68_dialog_content = "No lo habría hecho si no fuera un gran nadador.",
  ui_story_5038_50381102_69_dialog_content = "Hablando del cementerio, está lleno de barcos mercantes.",
  ui_story_5038_50381102_70_dialog_content = "Miré a mi alrededor pero no encontré la nave Lin.",
  ui_story_5038_50381102_71_dialog_content = "entonces no esta ahi...",
  ui_story_5038_50381102_72_dialog_content = "¿Notaste algo en la superficie?",
  ui_story_5038_50381102_73_dialog_content = "No.",
  ui_story_5038_50381102_74_dialog_content = "Es difícil ver de noche, y ahora la niebla lo oscurece todo.",
  ui_story_5038_50381102_75_dialog_content = "Olvídese de la nave Lin, ni siquiera sabemos dónde está nuestro Shadowind en este momento.",
  ui_story_5038_50381102_76_dialog_content = "Esperaba tanto.",
  ui_story_5038_50381102_77_dialog_content = "Probablemente no vamos a encontrar nada en esta niebla.",
  ui_story_5038_50381102_78_dialog_content = "Regresemos. Pásame el remo.",
  ui_story_5038_50381102_79_dialog_content = "¡Por supuesto! ¿Sabes dónde está el Shadowind?",
  ui_story_5038_50381102_80_dialog_content = "Por supuesto. ¿Cómo podría un capitán perder su barco?",
  ui_story_5038_50381102_81_dialog_content = "¡Maravilloso! ¡Eso me hace sentir mucho mejor!",
  ui_story_5038_50381102_82_dialog_content = "R-Rema más rápido, tengo que secarme en un horno lo antes posible.",
  ui_story_5038_50381102_83_dialog_content = "Sí, no me entretendré.",
  ui_story_5038_50381102_84_dialog_content = "(Yuebai rema mucho mejor que Liqing o que yo).",
  ui_story_5038_50381102_85_dialog_content = "(Con toda esta densa niebla que nos rodea, no puedo decir si el bote se está moviendo, y mucho menos en qué dirección vamos).",
  ui_story_5038_50381102_86_dialog_content = "(¿Puede Yuebai realmente encontrar su camino en la niebla?)",
  ui_story_5038_50381102_87_dialog_content = "(Sin embargo, confío en ella. Encontró el bote, ¿no? Un barco grande como el Shadowind no debería ser un problema).",
  ui_story_5038_50381102_88_dialog_content = "¡Achuu!",
  ui_story_5038_50381102_89_dialog_content = "Cuando regrese, tengo que hacerme un—",
  ui_story_5038_50381102_90_dialog_content = "Oye, ¿eso es...?",
  ui_story_5038_50381102_91_dialog_content = "¡Sí, estamos en casa!",
  ui_story_5038_50381102_92_dialog_content = "Sí, lo somos. No podía decirlo hasta que estuvimos tan cerca.",
  ui_story_5038_50381102_93_dialog_content = "Y esta es la primera vez que veo a Shadowind desde este ángulo.",
  ui_story_5038_50381102_94_dialog_content = "Tan grandioso y magnífico...",
  ui_story_5038_50381102_95_dialog_content = "Pidamos a alguien que nos levante.",
  ui_story_5038_50381102_96_dialog_content = "¡Hola, tripulación!",
  ui_story_5038_50381102_97_dialog_content = "¡Aquí abajo!",
  ui_story_5038_50381102_98_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5038_50381102_99_dialog_content = "Sin respuesta... ¿Están todos en la cama?",
  ui_story_5038_50381102_100_dialog_content = "Sí, ¿por qué está tan tranquilo?",
  ui_story_5038_50381102_101_dialog_content = "Oye, ¿alguien puede oírme?",
  ui_story_5038_50381102_102_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5038_50381102_103_dialog_content = "Eso es raro, no podría ser más fuerte.",
  ui_story_5038_50381102_104_dialog_content = "Sé que es difícil ver en la niebla, pero no debería ser difícil escuchar, ¿verdad?",
  ui_story_5038_50381102_105_dialog_content = "Este barco...",
  ui_story_5038_50381102_106_dialog_content = "¿Qué crees que está pasando, Yuebai?",
  ui_story_5038_50381102_107_dialog_content = "Subamos a bordo y echemos un vistazo.",
  ui_story_5038_50381102_108_dialog_content = "Veo una cuerda por ahí. Podemos levantarnos.",
  ui_story_5038_50381201_1_dialog_content = "¿De dónde vino toda esta niebla?",
  ui_story_5038_50381201_2_dialog_content = "Dígame usted. El capitán, Liqing, y PlayerName todavía están por ahí. Si se pierden...",
  ui_story_5038_50381201_3_dialog_content = "¿Quién sabe si los volveremos a ver?",
  ui_story_5038_50381201_4_dialog_content = "¿Están ahí fuera? ¿Para qué?",
  ui_story_5038_50381201_5_dialog_content = "Encontraron una pista del Shadowind original y fueron a buscarlo en un bote.",
  ui_story_5038_50381201_6_dialog_content = "Nadie esperaba que esta repentina niebla descendiera sobre nosotros.",
  ui_story_5038_50381201_7_dialog_content = "Diles a todos que levanten antorchas y permanezcan en vigilia junto a la proa.",
  ui_story_5038_50381201_8_dialog_content = "Ya plegué las velas para minimizar el movimiento del barco.",
  ui_story_5038_50381201_9_dialog_content = "El capitán tiene un gran sentido de la orientación y debería poder encontrar el camino de regreso.",
  ui_story_5038_50381201_10_dialog_content = "Pero los otros dos, sin embargo...",
  ui_story_5038_50381201_11_dialog_content = "Entonces, Sr. Swindler, ¿por qué nos convocó a Jiu y a mí aquí?",
  ui_story_5038_50381201_12_dialog_content = "Tenemos tres personas desaparecidas y me gustaría ayudar a encontrarlas.",
  ui_story_5038_50381201_13_dialog_content = "No podrá hacer ninguna diferencia dada la densidad de la niebla.",
  ui_story_5038_50381201_14_dialog_content = "Es mejor que te unas a mí en la cabina para apoyo emocional.",
  ui_story_5038_50381201_15_dialog_content = "¿Soporte emocional? ¿Qué estás haciendo?",
  ui_story_5038_50381201_16_dialog_content = "Voy a ver al Señor Zhong.",
  ui_story_5038_50381201_17_dialog_content = "¿Eh? ¿Te asusta o algo?",
  ui_story_5038_50381201_18_dialog_content = "<color=#e8d9bb>Chunda chunda...</color>",
  ui_story_5038_50381201_19_dialog_content = "Perdóneme, señor Zhong.",
  ui_story_5038_50381201_20_dialog_content = "Veo que hay niebla afuera. ¿Hay algún problema?",
  ui_story_5038_50381201_21_dialog_content = "La tripulación dijo que el capitán, Liqing, y PlayerName salió a buscar el viejo barco, y ahora están desaparecidos...",
  ui_story_5038_50381201_22_dialog_content = "Esta niebla es muy intempestiva...",
  ui_story_5038_50381201_23_dialog_content = "Si pueden encontrar el viejo barco, estarán bien.",
  ui_story_5038_50381201_24_dialog_content = "De lo contrario, el mar está lleno de peligros.",
  ui_story_5038_50381201_25_dialog_content = "Eso es cierto, especialmente con el pez serpiente que podría atacar en cualquier momento.",
  ui_story_5038_50381201_26_dialog_content = "Dados nuestros problemas de visibilidad, incluso Shadowind está en peligro.",
  ui_story_5038_50381201_27_dialog_content = "Lo somos, ¿no?",
  ui_story_5038_50381201_28_dialog_content = "Y la nave no puede sobrevivir a otro ataque.",
  ui_story_5038_50381201_29_dialog_content = "Tal vez debería adivinar el futuro de Shadowind.",
  ui_story_5038_50381201_30_dialog_content = "Si puedo augurar lo que nos va a atacar, al menos podemos tratar de prepararnos para ello.",
  ui_story_5038_50381201_31_dialog_content = "¿Puedes calcular ese tipo de cosas?",
  ui_story_5038_50381201_32_dialog_content = "El tiempo lo es todo, y ahora es el momento más oportuno.",
  ui_story_5038_50381201_33_dialog_content = "Sin embargo, soy simplemente un aficionado, por lo que mis habilidades son limitadas.",
  ui_story_5038_50381201_34_dialog_content = "Esperemos que esto funcione.",
  ui_story_5038_50381201_35_dialog_content = "<color=#e8d9bb>susurro, susurro...</color>",
  ui_story_5038_50381201_36_dialog_content = "¿Asi que? ¿Qué tienes?",
  ui_story_5038_50381201_37_dialog_content = "Doy gracias a los cielos por su benevolencia al proporcionarme respuestas.",
  ui_story_5038_50381201_38_dialog_content = "La verdad se revelará aquí, de donde comenzó este hilo del destino.",
  ui_story_5038_50381201_39_dialog_content = "Aquí es donde Shadowind encontró su peligro.",
  ui_story_5038_50381201_40_dialog_content = "¡Señor Zhong, este palo lo indica a usted como la causa!",
  ui_story_5038_50381201_41_dialog_content = "¡Hola...!",
  ui_story_5038_50381201_42_dialog_content = "Usted debe estar avergonzado de sí mismo, PlayerName, necesitando que te tire de la cuerda.",
  ui_story_5038_50381201_43_dialog_content = "Lo siento, no todo el mundo está acostumbrado a escalar por todos lados.",
  ui_story_5038_50381201_44_dialog_content = "Está bien, estamos a bordo, pero...",
  ui_story_5038_50381201_45_dialog_content = "No veo a nadie alrededor.",
  ui_story_5038_50381201_46_dialog_content = "¿Que esta pasando? ¿Salieron todos a buscarnos?",
  ui_story_5038_50381201_47_dialog_content = "Revisemos las cabañas, tal vez estén resguardándose de la niebla.",
  ui_story_5038_50381201_48_dialog_content = "Espera, ¿no entramos en la cabina desde aquí?",
  ui_story_5038_50381201_49_dialog_content = "Uh, creo que me dieron la vuelta en el camino hacia arriba. Tal vez sea de esta manera...",
  ui_story_5038_50381201_50_dialog_content = "No.",
  ui_story_5038_50381201_51_dialog_content = "¿Ah?",
  ui_story_5038_50381201_52_dialog_content = "Todo está apagado.",
  ui_story_5038_50381201_53_dialog_content = "El mástil, las barandillas, la cubierta...",
  ui_story_5038_50381201_54_dialog_content = "No estamos en Shadowind.",
  ui_story_5038_50381201_55_dialog_content = "¡Cuidado atrás de ti!",
  ui_story_5038_50381201_56_dialog_content = "Hay eclipses en la nave...",
  ui_story_5038_50381201_57_dialog_content = "Un montón de ellos.",
  ui_story_5038_50381201_58_dialog_content = "Oh no, estamos rodeados...",
  ui_story_5038_50381201_59_dialog_content = "¡Trata primero con los de la izquierda, Yuebai!",
  ui_story_5038_50381201_60_dialog_content = "Estoy en ello.",
  ui_story_5038_50381201_61_dialog_content = "Parece que tienes un don para manejar situaciones como esta.",
  ui_story_5038_50381201_62_dialog_content = "No es sorprendente, considerando que incluso sueño con eclipses que aparecen de la nada.",
  ui_story_5038_50381201_63_dialog_content = "Ahora tenemos que tener cuidado con—",
  ui_story_5038_50381201_64_dialog_content = "¡Me lo imaginé!",
  ui_story_5038_50381201_65_dialog_content = "¿Qué descubriste?",
  ui_story_5038_50381201_66_dialog_content = "¡Reconozco esto! ¡He estado aqui antes!",
  ui_story_5038_50381201_67_dialog_content = "¡Este es Shadowind! ¡¡El Shadowind original!!",
  ui_story_5038_50381201_68_dialog_content = "¡¿Qué?!",
  ui_story_5038_50381201_69_dialog_content = "Si...",
  ui_story_5038_50381201_70_dialog_content = "¿Lo encontramos por pura suerte?",
  ui_story_5038_50381201_71_dialog_content = "¡Estoy seguro de ello! ¡Este es el riel que doblé antes!",
  ui_story_5038_50381201_72_dialog_content = "Genial, por fin lo encontramos!",
  ui_story_5038_50381201_73_dialog_content = "Lo hicimos, pero no diría exactamente que nuestra situación actual es \"increíble\"...",
  ui_story_5038_50381201_74_dialog_content = "La brújula está en las cabinas. ¡Sé exactamente dónde está!",
  ui_story_5038_50381201_75_dialog_content = "Sígueme. ¡Te llevaré a él!",
  ui_story_5038_50381201_76_dialog_content = "¡Oye, más despacio, no sabes si hay Eclipsitos dentro!",
  ui_story_5038_50381201_77_dialog_content = "Espéranos, al menos...",
  ui_story_5038_50381201_78_dialog_content = "Y se va.",
  ui_story_5038_50381201_79_dialog_content = "¡Chicos, pónganse al día!",
  ui_story_5038_50381201_80_dialog_content = "No creo que te vaya a escuchar.",
  ui_story_5038_50381201_81_dialog_content = "Ven, vamos a seguir.",
  ui_story_5038_50381201_82_dialog_content = "Los eclipses no me van a detener.",
  ui_story_5038_50381202_1_dialog_content = "¿Estás diciendo que Lord Zhong provocó que Shadowind fuera atacado? ¿Cómo es eso posible?",
  ui_story_5038_50381202_2_dialog_content = "¿Es confiable su adivinación?",
  ui_story_5038_50381202_3_dialog_content = "Li Tianxian, estuviste detrás de mí todo este tiempo.",
  ui_story_5038_50381202_4_dialog_content = "Hiciste esta lectura antes de tiempo, ¿no es así?",
  ui_story_5038_50381202_5_dialog_content = "Muy perceptivo, Lord Zhong.",
  ui_story_5038_50381202_6_dialog_content = "Revisé mis palos cuando el pez serpiente apareció por segunda vez.",
  ui_story_5038_50381202_X6_dialog_content = "Cuando lo hice, el símbolo que se me reveló fue el Tigre Yin.",
  ui_story_5038_50381202_X7_dialog_content = "No pude entender lo que significaba.",
  ui_story_5038_50381202_X8_dialog_content = "Hasta que de repente recordé el viejo dicho: \"El que tiene el tigre, dirige el batallón\".",
  ui_story_5038_50381202_X9_dialog_content = "Una vez comandaste a miles de soldados empuñando un tigre en una bandera de guerra. Eres la persona implicada en esta adivinación.",
  ui_story_5038_50381202_X10_dialog_content = "Interesante. Continuar.",
  ui_story_5038_50381202_X11_dialog_content = "La palabra \"Xu\" en tu nombre puede significar mariposa.",
  ui_story_5038_50381202_7_dialog_content = "Tal vez agitaste tus alas en ese entonces, lo que resultó en esta tormenta que se gesta hoy.",
  ui_story_5038_50381202_8_dialog_content = "Una vez nos contaste la historia de la desventura del viejo barco.",
  ui_story_5038_50381202_9_dialog_content = "El barco Lin cargado de tesoros fue saqueado por piratas.",
  ui_story_5038_50381202_10_dialog_content = "Sin embargo, de alguna manera al final, los únicos supervivientes fuisteis tú y Liqing, que no erais más que invitados de honor.",
  ui_story_5038_50381202_11_dialog_content = "¿Qué papeles jugaron ustedes dos en el encuentro?",
  ui_story_5038_50381202_12_dialog_content = "Espero que puedas responder a esta y otras preguntas.",
  ui_story_5038_50381202_13_dialog_content = "Estás aquí para interrogarme; por lo tanto, puede prescindir de los trámites.",
  ui_story_5038_50381202_14_dialog_content = "Trajiste a Dantang y Jiu por miedo a enfurecerme, ¿no es así?",
  ui_story_5038_50381202_15_dialog_content = "E-Es por eso que pediste apoyo emocional...",
  ui_story_5038_50381202_16_dialog_content = "A pesar de que está confinado a una silla de ruedas, sigue siendo bastante intimidante, mi señor.",
  ui_story_5038_50381202_17_dialog_content = "Probablemente me habría reducido a tartamudear si hubiera estado solo en tu presencia.",
  ui_story_5038_50381202_18_dialog_content = "Muy bien, ya que preguntaste, lo explicaré con más detalle.",
  ui_story_5038_50381202_19_dialog_content = "De hecho, también he estado sospechando que el pez serpiente vino por mi culpa.",
  ui_story_5038_50381202_20_dialog_content = "O más bien, que soy responsable de su comportamiento errático.",
  ui_story_5038_50381202_21_dialog_content = "¿Qué quieres decir?",
  ui_story_5038_50381202_22_dialog_content = "Comencemos con el viejo Shadowind.",
  ui_story_5038_50381202_23_dialog_content = "Es cierto que los Lin tienen un tesoro en el barco y atraen piratas codiciosos.",
  ui_story_5038_50381202_24_dialog_content = "Sin embargo, yo no estaba en Shadowind en ese entonces. Yo estaba siguiendo en un barco detrás de los piratas.",
  ui_story_5038_50381202_25_dialog_content = "¿Los estabas siguiendo?",
  ui_story_5038_50381202_26_dialog_content = "Le prometí al Lin Guildmaster que protegería su propiedad.",
  ui_story_5038_50381202_27_dialog_content = "Por lo tanto, seguí a los piratas durante todo el viaje y abordé el Shadowind un tiempo después que ellos.",
  ui_story_5038_50381202_28_dialog_content = "Mi idea era recuperar la Brújula y volver a aterrizar en un barco.",
  ui_story_5038_50381202_29_dialog_content = "Lo que sucedió esa noche en el barco resultó mucho peor de lo que imaginaba.",
  ui_story_5038_50381202_30_dialog_content = "Los piratas se apoderaron del barco, pero no pudieron encontrar The Compass.",
  ui_story_5038_50381202_31_dialog_content = "Comenzaron a torturar a la tripulación por su paradero.",
  ui_story_5038_50381202_32_dialog_content = "No hay leyes ni justicia en alta mar, algo que los sinvergüenzas toman como patos en el agua.",
  ui_story_5038_50381202_33_dialog_content = "Cuando llegué allí, nadie de la familia Lin seguía con vida.",
  ui_story_5038_50381202_34_dialog_content = "Fue entonces cuando me di cuenta de que recuperar The Compass era inútil.",
  ui_story_5038_50381202_35_dialog_content = "Los Lin ya están en una situación terrible. Poseer la brújula solo traerá más problemas.",
  ui_story_5038_50381202_36_dialog_content = "La mejor manera de proteger el tesoro es dejar que \"desaparezca\".",
  ui_story_5038_50381202_37_dialog_content = "¿Entonces lo desechaste?",
  ui_story_5038_50381202_38_dialog_content = "Por supuesto no. Es una reliquia familiar de Lin, y su única esperanza de volver a destacarse.",
  ui_story_5038_50381202_39_dialog_content = "La Brújula debe mantenerse en secreto, así que tenía que asegurarme de que nadie volviera a hablar de ella.",
  ui_story_5038_50381202_40_dialog_content = "Nadie debe hablar de eso...",
  ui_story_5038_50381202_41_dialog_content = "Espera, ¿me estás diciendo que tú...",
  ui_story_5038_50381202_42_dialog_content = "Sí, tuve que matar a todos los piratas presentes.",
  ui_story_5038_50381202_43_dialog_content = "He luchado en muchas batallas a lo largo de los años, pero nunca experimenté algo tan terrible como eso.",
  ui_story_5038_50381202_44_dialog_content = "Esos piratas no son guerreros. Son oportunistas por naturaleza, y cuando han sido derrotados, suplican misericordia de rodillas.",
  ui_story_5038_50381202_45_dialog_content = "Maldicen, gimen y se avergüenzan cuando la situación se vuelve sombría.",
  ui_story_5038_50381202_46_dialog_content = "No estaban tratando de vencerme, sino de sobrevivir.",
  ui_story_5038_50381202_47_dialog_content = "Algunos de ellos eran verdaderamente irredimibles, algunos simplemente estaban tratando de ganarse la vida a duras penas. Las personas terminan como forajidos por todo tipo de razones.",
  ui_story_5038_50381202_48_dialog_content = "Pero no tuve tiempo de considerar esas razones. Sólo podía matarlos a todos.",
  ui_story_5038_50381202_49_dialog_content = "¿Para preservar La Brújula?",
  ui_story_5038_50381202_50_dialog_content = "Eso es lo que dije para convencerme.",
  ui_story_5038_50381202_51_dialog_content = "Hubo momentos fugaces en los que sentí que estaba yendo demasiado lejos.",
  ui_story_5038_50381202_52_dialog_content = "Pero en el momento en que mi espada se manchó de sangre, ya era demasiado tarde para dar marcha atrás.",
  ui_story_5038_50381202_53_dialog_content = "Entiendo...",
  ui_story_5038_50381202_54_dialog_content = "Mentí acerca de que el barco fue golpeado por una tormenta.",
  ui_story_5038_50381202_55_dialog_content = "Los peces serpiente fueron los verdaderos culpables de que Liqing y yo fuéramos a la deriva en el mar.",
  ui_story_5038_50381202_56_dialog_content = "Pez serpiente otra vez?",
  ui_story_5038_50381202_57_dialog_content = "Por eso me pregunté si me perseguían.",
  ui_story_5038_50381202_58_dialog_content = "Su ataque fue una reminiscencia del asalto al viejo Shadowind.",
  ui_story_5038_50381202_59_dialog_content = "Ninguna de estas cosas es relevante para la búsqueda de The Compass, por lo que no vi la necesidad de mencionarlas.",
  ui_story_5038_50381202_60_dialog_content = "Pero como insististe, ahora me he sincerado.",
  ui_story_5038_50381202_61_dialog_content = "Nadie querría aliviar una experiencia así. ¡Me disculpo por ser entrometido!",
  ui_story_5038_50381202_62_dialog_content = "Está bien. Debemos confiar unos en otros inequívocamente para superar nuestra situación actual.",
  ui_story_5038_50381202_63_dialog_content = "Sí, debemos estar unidos.",
  ui_story_5038_50381202_64_dialog_content = "Debería dedicar más tiempo a averiguar cómo vamos a resolver los problemas actuales.",
  ui_story_5038_50381202_65_dialog_content = "Es casi imposible hacer nada en esta niebla.",
  ui_story_5038_50381202_66_dialog_content = "Pero Liqing está muy dedicado a encontrar la brújula y tiene un instinto especial para manipular.",
  ui_story_5038_50381202_67_dialog_content = "Dado que él mismo estaba dispuesto a salir al mar, significa que el barco está cerca.",
  ui_story_5038_50381202_68_dialog_content = "Tal vez cuando se disipe la niebla, regrese con The Compass.",
  ui_story_5038_50381202_69_dialog_content = "Ese sería el mejor de los casos...",
  ui_story_5038_50381202_70_dialog_content = "<color=#e8d9bb>¡Choque!</color>",
  ui_story_5038_50381202_71_dialog_content = "Qué...",
  ui_story_5038_50381202_72_dialog_content = "<size=45><color=#e8d9bb>¡Ruido sordo!</color></size>",
  ui_story_5038_50381202_73_dialog_content = "¡Ahhhhhh!",
  ui_story_5038_50381202_74_dialog_content = "¿Qué sucedió? ¿Por qué lanzamos tan mal?",
  ui_story_5038_50381202_75_dialog_content = "Mi señor, ¿está usted...?",
  ui_story_5038_50381202_76_dialog_content = "Estoy bien. ¡Sube a la cubierta para ver qué está pasando!",
  ui_story_5038_50381202_77_dialog_content = "¡Absolutamente! Por favor espere aqui...",
  ui_story_5038_50381202_78_dialog_content = "<size=45>Aaaaaahhhhhhhh!!!</size>",
  ui_story_5038_50381202_79_dialog_content = "¡¿Por qué grita el marinero?!",
  ui_story_5038_50381202_80_dialog_content = "nave AA...",
  ui_story_5038_50381202_81_dialog_content = "<size=50>¡Un barco acaba de estrellarse contra nosotros!</size>",
  ui_story_5038_50381301_1_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5038_50381301_2_dialog_content = "¡¿Hola Qué pasa?!",
  ui_story_5038_50381301_3_dialog_content = "El arco debe haber chocado con algo. ¿Estás bien?",
  ui_story_5038_50381301_4_dialog_content = "Estoy bien. Ya estoy acostumbrado al entorno inestable de un barco.",
  ui_story_5038_50381301_5_dialog_content = "¿Qué chocamos, un arrecife?",
  ui_story_5038_50381301_6_dialog_content = "Ven rápido, está justo más adelante.",
  ui_story_5038_50381301_7_dialog_content = "Uh, por cierto, ¿alguno de ustedes puede forzar una cerradura?",
  ui_story_5038_50381301_8_dialog_content = "La puerta parece estar...",
  ui_story_5038_50381301_9_dialog_content = "Mi hoja puede.",
  ui_story_5038_50381301_10_dialog_content = "<color=#e8d9bb>¡Mierda!</color>",
  ui_story_5038_50381301_11_dialog_content = "¡Cuidado, casi me cortas la cabeza!",
  ui_story_5038_50381301_12_dialog_content = "¿No vas a entrar?",
  ui_story_5038_50381301_13_dialog_content = "Mmm...",
  ui_story_5038_50381301_14_dialog_content = "Ven y contempla los tesoros que todos hemos estado esperando.",
  ui_story_5038_50381301_15_dialog_content = "<color=#e8d9bb>*Crujir*</color>",
  ui_story_5038_50381301_16_dialog_content = "Whoa...",
  ui_story_5038_50381301_17_dialog_content = "¡Es tan elegante aquí!",
  ui_story_5038_50381301_18_dialog_content = "Así que así son los clanes ricos de Longzhou, ¿eh?",
  ui_story_5038_50381301_19_dialog_content = "Estos diseños...",
  ui_story_5038_50381301_20_dialog_content = "Son muy similares a los que se encuentran en Lin Manor que recuerdo.",
  ui_story_5038_50381301_21_dialog_content = "Deben haber escondido estas antigüedades y pinturas aquí después de la caída de la familia.",
  ui_story_5038_50381301_22_dialog_content = "¿La mansión Lin? ¿Era esa tu casa?",
  ui_story_5038_50381301_23_dialog_content = "Viví allí brevemente cuando era joven.",
  ui_story_5038_50381301_24_dialog_content = "Hasta que Lin Guild cayó en declive, perdió toda su fortuna y se vio obligado a entregar la propiedad.",
  ui_story_5038_50381301_25_dialog_content = "Nunca pensé que sería capaz de volver a disfrutar de las imágenes del pasado.",
  ui_story_5038_50381301_26_dialog_content = "Los hogares de la infancia definitivamente evocan una avalancha de emociones...",
  ui_story_5038_50381301_27_dialog_content = "Dejemos de recordar.",
  ui_story_5038_50381301_28_dialog_content = "¿Cuál de estos es The Compass, Liqing?",
  ui_story_5038_50381301_29_dialog_content = "De ninguna manera, esto no puede ser...",
  ui_story_5038_50381301_30_dialog_content = "¿Qué pasa, Liqing?",
  ui_story_5038_50381301_31_dialog_content = "No está aquí... ¿Cómo es que no está aquí?",
  ui_story_5038_50381301_32_dialog_content = "¿Qué quieres decir?",
  ui_story_5038_50381301_33_dialog_content = "Tal vez estaba escondido en otro lugar.",
  ui_story_5038_50381301_34_dialog_content = "Liqing, descríbenos The Compass y te ayudaremos a encontrarlo.",
  ui_story_5038_50381301_35_dialog_content = "Pero... ¿dónde más podría estar?",
  ui_story_5038_50381301_36_dialog_content = "Sin embargo, solo puede estar en un tanque en alguna parte...",
  ui_story_5038_50381301_37_dialog_content = "¿En un tanque?",
  ui_story_5038_50381301_38_dialog_content = "Esperar. ¿La brújula no es una brújula?",
  ui_story_5038_50381301_39_dialog_content = "La brújula es un pez.",
  ui_story_5038_50381301_40_dialog_content = "¡¿Qué?!",
  ui_story_5038_50381301_41_dialog_content = "Je...",
  ui_story_5038_50381301_42_dialog_content = "<color=#e8d9bb>*Chapoteo*</color>",
  ui_story_5038_50381301_43_dialog_content = "<color=#e8d9bb>*Chapoteo*</color>",
  ui_story_5038_50381301_44_dialog_content = "¡¿Q-Qué está pasando?! ¡Parece que algo está a punto de romperse!",
  ui_story_5038_50381301_45_dialog_content = "Es de porcelana, pero no puedo ver dónde está...",
  ui_story_5038_50381301_46_dialog_content = "¡Oh no, acabo de ver a alguien salir corriendo!",
  ui_story_5038_50381301_47_dialog_content = "¡¿Había alguien más aquí?!",
  ui_story_5038_50381301_48_dialog_content = "<color=#828282>¡Golpe!</color>",
  ui_story_5038_50381301_49_dialog_content = "¡Oye, la puerta está cerrada!",
  ui_story_5038_50381301_50_dialog_content = "¡Es él del otro lado!",
  ui_story_5038_50381301_51_dialog_content = "¿Quién? ¿Quién está del otro lado?",
  ui_story_5038_50381301_52_dialog_content = "Agradecer...",
  ui_story_5038_50381301_53_dialog_content = "?!!",
  ui_story_5038_50381301_54_dialog_content = "Gracias... Gracias... a ti.",
  ui_story_5038_50381301_55_dialog_content = "<color=#e8d9bb>Golpe, golpe, golpe...</color>",
  ui_story_5038_50381301_56_dialog_content = "Eso es...",
  ui_story_5038_50381301_57_dialog_content = "¡El se escapo! ¡Tenemos que ponernos al día!",
  ui_story_5038_50381301_58_dialog_content = "Esta puerta... Capitán, ¿puede abrirla?",
  ui_story_5038_50381301_59_dialog_content = "Lo intenté. Está atrincherado con algo pesado.",
  ui_story_5038_50381301_60_dialog_content = "Esto no es bueno... Tenemos que alcanzarlo.",
  ui_story_5038_50381301_61_dialog_content = "Qué podemos hacer...",
  ui_story_5038_50381301_62_dialog_content = "¡Vamos a tirarnos a la puerta y derribarla!",
  ui_story_5038_50381301_63_dialog_content = "Eso no funcionará, solo nosotros tres no es suficiente.",
  ui_story_5038_50381301_64_dialog_content = "Cálmate primero.",
  ui_story_5038_50381301_65_dialog_content = "¡¿Cómo puedo hacerlo cuando está a punto de irse?!",
  ui_story_5038_50381301_66_dialog_content = "¿Cómo vamos a encontrarlo ahí fuera en el mar masivo?",
  ui_story_5038_50381301_67_dialog_content = "Er, podría tener una manera de abrir la puerta.",
  ui_story_5038_50381301_68_dialog_content = "¿En serio?",
  ui_story_5038_50381301_69_dialog_content = "Sí, pero necesito algo de tiempo.",
  ui_story_5038_50381301_70_dialog_content = "Dame un momento...",
  ui_story_5038_50381301_71_dialog_content = "(Esto es probablemente absurdo, pero...)",
  ui_story_5038_50381301_72_dialog_content = "(¡No puede doler intentarlo!)",
  ui_story_5038_50381301_73_option_content = "¡Potencia de fuerza!",
  ui_story_5038_50381301_74_dialog_content = "De repente se ha quedado quieto. Debe estar usando su habilidad psíquica.",
  ui_story_5038_50381301_X74_dialog_content = "¿Por qué no te tomas este tiempo para decirme cuál es el problema con The Compass?",
  ui_story_5038_50381301_75_dialog_content = "¿Y quién fue el que se escapó?",
  ui_story_5038_50381301_76_dialog_content = "Uh, ¿por dónde debería empezar...?",
  ui_story_5038_50381301_77_dialog_content = "En realidad, nunca he visto a esa persona antes.",
  ui_story_5038_50381301_78_dialog_content = "Pero si estuvo aquí, entonces solo hay una posibilidad.",
  ui_story_5038_50381301_79_dialog_content = "Él es La Brújula.",
  ui_story_5038_50381301_80_dialog_content = "¡¿Él es el qué?!",
  ui_story_5038_50381301_81_dialog_content = "Un minuto dices que la brújula es un pez, al minuto siguiente me dices que es una persona. Que esta pasando?",
  ui_story_5038_50381301_82_dialog_content = "La brújula es de hecho un pez, y un pez serpiente muy especial.",
  ui_story_5038_50381301_83_dialog_content = "Pero el hecho de que sea un pez no significa que tenga que parecerse a uno.",
  ui_story_5038_50381301_84_dialog_content = "Recuerda, soy un gato.",
  ui_story_5038_50381301_85_dialog_content = "¿Estás diciendo que es un diablillo?",
  ui_story_5038_50381301_86_dialog_content = "Sí, esa es la única posibilidad.",
  ui_story_5038_50381301_87_dialog_content = "Probablemente se transformó en un fiendling mientras el barco estaba a la deriva.",
  ui_story_5038_50381301_88_dialog_content = "La evolución lo liberó del agua y de la restricción de un tanque.",
  ui_story_5038_50381301_89_dialog_content = "Pero todavía no podía salir de la cabina cerrada.",
  ui_story_5038_50381301_90_dialog_content = "Hasta que rompimos la cerradura...",
  ui_story_5038_50381301_91_dialog_content = "...Ya veo.",
  ui_story_5038_50381301_92_dialog_content = "La brújula es un pez... ¿Cómo navega un pez en un barco?",
  ui_story_5038_50381301_93_dialog_content = "Como Lin, debes conocer muy bien el tótem de tu familia, ¿verdad?",
  ui_story_5038_50381301_94_dialog_content = "Serpentfish actuará colectivamente para un individuo en la escuela.",
  ui_story_5038_50381301_95_dialog_content = "Y The Compass es el líder del pez serpiente.",
  ui_story_5038_50381301_96_dialog_content = "¡¿El líder?!",
  ui_story_5038_50381301_97_dialog_content = "No es de extrañar que todos los peces serpiente comenzaran a comportarse de manera extraña y a llenar esta área del mar.",
  ui_story_5038_50381301_98_dialog_content = "Así fue como tú y Zhong Xu descubristeis que La Brújula estaba aquí.",
  ui_story_5038_50381301_99_dialog_content = "Exactamente.",
  ui_story_5038_50381301_100_dialog_content = "Hmm, creo que ahora entiendo.",
  ui_story_5038_50381301_101_dialog_content = "Los peces serpiente son expertos en surcar las aguas entre los dos continentes, como es su naturaleza.",
  ui_story_5038_50381301_102_dialog_content = "El antiguo Shadowind explotó sus habilidades al apoderarse del pez serpiente líder.",
  ui_story_5038_50381301_103_dialog_content = "Al mantener cautivo a su líder, toda la escuela comenzó a ayudar al barco a cruzar el océano...",
  ui_story_5038_50381301_104_dialog_content = "Así es.",
  ui_story_5038_50381301_105_dialog_content = "Los Lin confinaron el pez serpiente líder a bordo.",
  ui_story_5038_50381301_106_dialog_content = "Pasaron generaciones, y los peces serpiente recién nacidos llegaron a ver a Shadowind como su líder.",
  ui_story_5038_50381301_107_dialog_content = "Se reunían detrás del barco y lo empujaban hacia adelante cada vez que el barco zarpaba.",
  ui_story_5038_50381301_108_dialog_content = "Por lo tanto, nunca hubo necesidad de preocuparse por perderse o quedar varado por las inclemencias del tiempo.",
  ui_story_5038_50381301_109_dialog_content = "El pez siempre los llevaría a su destino.",
  ui_story_5038_50381301_110_dialog_content = "¿Cómo es que nadie me habló de esto antes?",
  ui_story_5038_50381301_111_dialog_content = "Los Lin no lo hicieron, ni tú ni Zhong Xu.",
  ui_story_5038_50381301_112_dialog_content = "Sobre eso... Zhong Xu me explicó un poco, pero realmente no entendí.",
  ui_story_5038_50381301_113_dialog_content = "Sonaba complicado. Algo sobre secretos comerciales, protección del honor familiar, etc.",
  ui_story_5038_50381301_114_dialog_content = "Con todo, guardar silencio era la mejor opción.",
  ui_story_5038_50381301_115_dialog_content = "...",
  ui_story_5038_50381301_116_dialog_content = "En cuanto a mí, bueno... Supongo que me siento culpable por todo el asunto.",
  ui_story_5038_50381301_117_dialog_content = "Desde el día que puse un pie en el viejo Shadowind, me convertí en cómplice de la esclavitud.",
  ui_story_5038_50381301_118_dialog_content = "Cada vez que el mar se volvía caprichoso, me veía obligado a tratarlo como un instrumento.",
  ui_story_5038_50381301_119_dialog_content = "Lo llamé La Brújula para hacerme sentir mejor.",
  ui_story_5038_50381301_120_dialog_content = "Culpa...",
  ui_story_5038_50381301_121_dialog_content = "Al menos tienes la retrospectiva para sentirte así.",
  ui_story_5038_50381301_122_dialog_content = "Eso es probablemente porque siempre pensé en él como un amigo.",
  ui_story_5038_50381301_123_dialog_content = "Ah, sí, tiene un nombre. Es Yoh.",
  ui_story_5038_50381301_124_dialog_content = "Yoh... Lo recordaré.",
  ui_story_5038_50381301_125_dialog_content = "Uh, siento interrumpir...",
  ui_story_5038_50381301_126_dialog_content = "creo que lo hice",
  ui_story_5038_50381301_127_dialog_content = "¿Lo hiciste? ¿Abriste la puerta?",
  ui_story_5038_50381301_128_dialog_content = "Sí, estará abierto en un rato.",
  ui_story_5038_50381301_129_dialog_content = "¡Wow impresionante!",
  ui_story_5038_50381301_130_dialog_content = "Sin embargo, ustedes dos deberían prepararse.",
  ui_story_5038_50381301_131_dialog_content = "¿Prepararnos? ¿Para qué?",
  ui_story_5038_50381301_132_dialog_content = "¡Aquí vienen!",
  ui_story_5038_50381301_133_dialog_content = "<color=#e8d9bb>¡Choque!</color>",
  ui_story_5038_50381301_134_dialog_content = "¡Grrr!",
  ui_story_5038_50381301_135_dialog_content = "¡¡¡Ay!!! ¡Eso me sobresaltó!",
  ui_story_5038_50381301_136_dialog_content = "¿Cómo entraron los eclipses?",
  ui_story_5038_50381301_137_dialog_content = "Espera un momento, ¿así fue como abriste la puerta?",
  ui_story_5038_50381301_138_dialog_content = "¿Dibujar los eclipses y hacer que los atraviesen?",
  ui_story_5038_50381301_139_dialog_content = "¿No lo llamarías violento pero efectivo?",
  ui_story_5038_50381301_140_dialog_content = "Bien hecho. Es mucho más fácil lidiar con Eclipsites que con la puerta.",
  ui_story_5038_50381301_141_dialog_content = "¡Vamos a acabar con ellos!",
  ui_story_5038_50381302_1_dialog_content = "¿Que esta pasando? ¿Qué ocurre?",
  ui_story_5038_50381302_2_dialog_content = "Eclipsitos... ¡Están en cubierta!",
  ui_story_5038_50381302_3_dialog_content = "¡Vinieron del barco detrás de nosotros!",
  ui_story_5038_50381302_4_dialog_content = "¡Graaah!",
  ui_story_5038_50381302_5_dialog_content = "¡Lárgate, inmundicia!",
  ui_story_5038_50381302_6_dialog_content = "Graah...",
  ui_story_5038_50381302_7_dialog_content = "Hay demasiados de ellos...",
  ui_story_5038_50381302_8_dialog_content = "Por favor, retroceda, Su Alteza.",
  ui_story_5038_50381302_9_dialog_content = "Déjame manejar trabajos rudimentarios como este.",
  ui_story_5038_50381302_10_dialog_content = "¡Todos, reúnanse en la popa!",
  ui_story_5038_50381302_11_dialog_content = "Mantenga la línea contra los eclipses. ¡No dejes que hagan lo que les plazca!",
  ui_story_5038_50381302_12_dialog_content = "¡Sí!",
  ui_story_5038_50381302_13_dialog_content = "¿Qué está pasando, Señor Zhong?",
  ui_story_5038_50381302_14_dialog_content = "¿Por qué una nave llena de eclipses se concentraría en nosotros?",
  ui_story_5038_50381302_15_dialog_content = "Es un barco muy grande...",
  ui_story_5038_50381302_16_dialog_content = "Tal vez las olas se lo llevaron por pura casualidad y la poca visibilidad agravó el problema.",
  ui_story_5038_50381302_17_dialog_content = "¡Oh no, están destrozando el mástil!",
  ui_story_5038_50381302_18_dialog_content = "¡Cuidado, gran parte de la cubierta ha sido destrozada!",
  ui_story_5038_50381302_19_dialog_content = "¡Esto es malo, tenemos que hacer algo!",
  ui_story_5038_50381302_20_dialog_content = "¡Eclipsitos podridos!",
  ui_story_5038_50381302_21_dialog_content = "¡Vamos a ayudar, Jiu!",
  ui_story_5038_50381302_22_dialog_content = "Por favor espera.",
  ui_story_5038_50381302_23_dialog_content = "¿Por qué?",
  ui_story_5038_50381302_24_dialog_content = "Luchar en Shadowind solo dañará aún más la nave.",
  ui_story_5038_50381302_25_dialog_content = "Debemos mover el campo de batalla.",
  ui_story_5038_50381302_26_dialog_content = "¿Moverse? Te refieres a...",
  ui_story_5038_50381302_27_dialog_content = "Reúna tablones y construya un puente hacia ese otro barco.",
  ui_story_5038_50381302_28_dialog_content = "Si tiene que haber un incendio, asegurémonos de que no sea nuestro barco el que se queme.",
  ui_story_5038_50381401_1_dialog_content = "No está en condiciones de luchar, mi señor. Por favor, quédate aquí.",
  ui_story_5038_50381401_2_dialog_content = "Tenemos suficiente mano de obra para deshacernos de los eclipses.",
  ui_story_5038_50381401_3_dialog_content = "Ella está en lo correcto. No tiene sentido que te lastimes.",
  ui_story_5038_50381401_4_dialog_content = "No se preocupen por eso.",
  ui_story_5038_50381401_5_dialog_content = "No lo habría seguido si creyera que iba a ser una carga.",
  ui_story_5038_50381401_6_dialog_content = "(No hay duda, este es el Shadowind original).",
  ui_story_5038_50381401_7_dialog_content = "(La brújula está muy cerca. La recuperaré esta vez).",
  ui_story_5038_50381401_8_dialog_content = "(No renego de mis promesas, Sr. Lin.)",
  ui_story_5038_50381401_9_dialog_content = "Aquí vienen más Eclipsites, Su Alteza.",
  ui_story_5038_50381401_10_dialog_content = "Hay más aquí que en nuestro barco.",
  ui_story_5038_50381401_11_dialog_content = "No hay problema, nosotros—",
  ui_story_5038_50381401_12_dialog_content = "Un segundo, por favor retroceda un par de pasos.",
  ui_story_5038_50381401_13_dialog_content = "No te dejes atrapar por mi línea de fuego.",
  ui_story_5038_50381401_14_dialog_content = "¿Eh? Mi señor, ¿qué estás...",
  ui_story_5038_50381401_15_dialog_content = "<size=50>¡Las llamas reducirán todo a cenizas!</size>",
  ui_story_5038_50381401_16_dialog_content = "¡Tenga cuidado, Su Alteza!",
  ui_story_5038_50381401_17_dialog_content = "¡Gaahhhh!",
  ui_story_5038_50381401_18_dialog_content = "¡Qué llama más intensa!",
  ui_story_5038_50381401_19_dialog_content = "Todos los eclipses están chamuscados...",
  ui_story_5038_50381401_20_dialog_content = "¡Incluso la niebla se ha disipado!",
  ui_story_5038_50381401_21_dialog_content = "No es de extrañar que Lord Zhong insistiera en venir.",
  ui_story_5038_50381401_22_dialog_content = "No hay forma de que pudiera desatar algo así a bordo del Shadowind.",
  ui_story_5038_50381401_23_dialog_content = "Este viejo barco ha estado a la deriva durante mucho tiempo, asaltado por las olas, erosionado por los vientos salados del océano.",
  ui_story_5038_50381401_24_dialog_content = "Es un caparazón de lo que era por ahora. Lo único que sigue intacto es su marco.",
  ui_story_5038_50381401_25_dialog_content = "Un fuego ardería intensamente aquí.",
  ui_story_5038_50381401_26_dialog_content = "¡Gran! ¡Démonos prisa y lidiemos con los Eclipsites con el fuego de Lord Zhong!",
  ui_story_5038_50381401_27_dialog_content = "Shadowind todavía está esperando que regresemos y ayudemos.",
  ui_story_5038_50381401_28_dialog_content = "Tenga cuidado, Su Alteza, la cubierta debilitada por el fuego podría colapsar.",
  ui_story_5038_50381401_29_dialog_content = "Hmm, tienes razón en eso...",
  ui_story_5038_50381401_30_dialog_content = "Aferrémonos el uno al otro, Jiu.",
  ui_story_5038_50381401_31_dialog_content = "De esa manera, si uno de nosotros se resbala, el otro puede ayudar.",
  ui_story_5038_50381401_32_dialog_content = "H-espera...",
  ui_story_5038_50381401_33_dialog_content = "Como usted dice, Su Alteza.",
  ui_story_5038_50381401_34_dialog_content = "Muy bien, ustedes dos, déjenme despejarles el camino.",
  ui_story_5038_50381401_35_dialog_content = "Sí, sigamos adelante.",
  ui_story_5038_50381401_36_dialog_content = "Hay algo más que quería hacer además de deshacerme de los eclipses.",
  ui_story_5038_50381401_37_dialog_content = "¿Debes hacerlo en este barco?",
  ui_story_5038_50381401_38_dialog_content = "Si no me equivoco, este es el Shadowind original.",
  ui_story_5038_50381401_39_dialog_content = "Tengo ciertos lazos con la nave.",
  ui_story_5038_50381401_40_dialog_content = "Oh, entonces este es el legendario barco perdido...",
  ui_story_5038_50381401_41_dialog_content = "Hay una antigüedad a bordo.",
  ui_story_5038_50381401_42_dialog_content = "Debo recuperarlo antes de que la nave se queme.",
  ui_story_5038_50381401_43_dialog_content = "Suena como algo muy importante.",
  ui_story_5038_50381401_44_dialog_content = "Sí, puede ayudarnos a regresar a Longzhou.",
  ui_story_5038_50381401_45_dialog_content = "(La brújula se ha descuidado durante tanto tiempo, espero que esté bien).",
  ui_story_5038_50381401_46_dialog_content = "(Es bastante ridículo cuando se piensa en ello...)",
  ui_story_5038_50381401_47_dialog_content = "(Que la longevidad de una ruta entre dos continentes cabalga a lomos de un pez.)",
  ui_story_5038_50381401_48_dialog_content = "<color=#e8d9bb>*Pasando pasos*...</color>",
  ui_story_5038_50381401_49_dialog_content = "¿Hmm?",
  ui_story_5038_50381401_50_dialog_content = "Espera, creo que escuché un ruido.",
  ui_story_5038_50381401_51_dialog_content = "¿Un eclipse escondido quizás?",
  ui_story_5038_50381401_52_dialog_content = "No, Su Alteza, eso suena como...",
  ui_story_5038_50381401_53_dialog_content = "<color=#e8d9bb>Baraja, baraja...</color>",
  ui_story_5038_50381401_54_dialog_content = "Pasos.",
  ui_story_5038_50381401_55_dialog_content = "¿Pasos? ¿Se supone que hay gente aquí además de nosotros?",
  ui_story_5038_50381401_56_dialog_content = "Eres tú.",
  ui_story_5038_50381401_57_dialog_content = "!!!",
  ui_story_5038_50381401_58_dialog_content = "¿Quién es? ¿Quien esta hablando?",
  ui_story_5038_50381401_59_dialog_content = "Sal y—",
  ui_story_5038_50381401_60_dialog_content = "Control.",
  ui_story_5038_50381401_61_dialog_content = "¡Uh!",
  ui_story_5038_50381401_62_dialog_content = "¡Te tengo, Su Alteza!",
  ui_story_5038_50381401_63_dialog_content = "L-Mira!",
  ui_story_5038_50381401_64_dialog_content = "Señor Zhong—",
  ui_story_5038_50381401_65_dialog_content = "Tos...",
  ui_story_5038_50381401_66_dialog_content = "¿Quién eres?",
  ui_story_5038_50381401_67_dialog_content = "Te conozco.",
  ui_story_5038_50381401_68_dialog_content = "Pero no sé...",
  ui_story_5038_50381401_69_dialog_content = "Espera, ¿tienes cola?",
  ui_story_5038_50381401_70_dialog_content = "Tú... estabas... en... el... barco.",
  ui_story_5038_50381401_71_dialog_content = "Esa es una cola de pez serpiente.",
  ui_story_5038_50381401_72_dialog_content = "Ese es un rasgo de Lin. ¿Eres Lin?",
  ui_story_5038_50381401_73_dialog_content = "Tú... ayudaste... a Lins.",
  ui_story_5038_50381401_74_dialog_content = "No, no puedes ser un Lin.",
  ui_story_5038_50381401_75_dialog_content = "Nadie sobrevivió a esa masacre.",
  ui_story_5038_50381401_76_dialog_content = "Las únicas cosas que aparecerían aquí son las posesiones de Lin.",
  ui_story_5038_50381401_77_dialog_content = "Tu nombre.",
  ui_story_5038_50381401_78_dialog_content = "Zhong... Xu.",
  ui_story_5038_50381401_79_dialog_content = "Tú eres eso.",
  ui_story_5038_50381401_80_dialog_content = "El tesoro más apreciado por los Lins.",
  ui_story_5038_50381401_81_dialog_content = "Eres Yoh.",
  ui_story_5038_50381401_82_dialog_content = "¿Quién es ese niño? ¿Y por qué lastimó a Lord Zhong?",
  ui_story_5038_50381401_83_dialog_content = "Ten cuidado, es muy poderoso.",
  ui_story_5038_50381401_84_dialog_content = "¿Cómo puede un niño tan pequeño ser tan...",
  ui_story_5038_50381401_85_dialog_content = "¿Podría ser un fiundling?",
  ui_story_5038_50381401_86_dialog_content = "No puedo creer que así luzcas ahora...",
  ui_story_5038_50381401_87_dialog_content = "¿Por qué me atacaste?",
  ui_story_5038_50381401_88_dialog_content = "Lins... merece... morir.",
  ui_story_5038_50381401_89_dialog_content = "... Como sospechaba, los desprecias.",
  ui_story_5038_50381401_90_dialog_content = "Porque te hicieron prisionero.",
  ui_story_5038_50381401_91_dialog_content = "Todos... en... el... barco.",
  ui_story_5038_50381401_92_dialog_content = "Debe morir.",
  ui_story_5038_50381401_93_dialog_content = "Yo, junto con la familia Lin, he predicho durante mucho tiempo tu inevitable odio.",
  ui_story_5038_50381401_94_dialog_content = "Pero ninguno de nosotros esperaba ser confrontado por ese odio algún día.",
  ui_story_5038_50381401_95_dialog_content = "Nave... merece... la muerte... más.",
  ui_story_5038_50381401_96_dialog_content = "Tu odio está justificado, así que eres bienvenido.",
  ui_story_5038_50381401_97_dialog_content = "Heredamos los legados de nuestros antecesores, así como sus deudas.",
  ui_story_5038_50381401_98_dialog_content = "Algunos tienen más mala suerte que otros y se quedan atrapados entre los dos.",
  ui_story_5038_50381401_99_dialog_content = "Este parece ser otro buen lío del que tengo que sacarte de apuros, Lin, viejo amigo.",
  ui_story_5038_50381401_100_dialog_content = "Todos... de... ustedes... son...",
  ui_story_5038_50381401_101_dialog_content = "enemigos... del... mar.",
  ui_story_5038_50381401_102_dialog_content = "Tú... y... esta... nave.",
  ui_story_5038_50381401_103_dialog_content = "Hundirse... en... el océano.",
  ui_story_5038_50381401_104_dialog_content = "¡¿Qué esta pasando?!",
  ui_story_5038_50381401_105_dialog_content = "¡Espera, Yo!",
  ui_story_5038_50381401_106_dialog_content = "¡E-Esa es la voz de Liqing!",
  ui_story_5038_50381401_107_dialog_content = "Huff... ¡Finalmente te alcancé!",
  ui_story_5038_50381401_108_dialog_content = "Li...qing...",
  ui_story_5038_50381401_109_dialog_content = "Así es como se ve The Compass.",
  ui_story_5038_50381401_110_dialog_content = "¿Por qué están todos aquí? ¿Qué sucedió?",
  ui_story_5038_50381401_111_dialog_content = "¿Ustedes tres han estado aquí todo el tiempo?",
  ui_story_5038_50381401_112_dialog_content = "¿Que esta pasando? ¿Y quién es el niño?",
  ui_story_5038_50381401_113_dialog_content = "Esa es la brújula que hemos estado buscando.",
  ui_story_5038_50381401_114_dialog_content = "¡¿La brújula?!",
  ui_story_5038_50381401_115_dialog_content = "Ninguna de mis adivinaciones eligió revelarme eso...",
  ui_story_5038_50381401_116_dialog_content = "Espera un minuto, la lectura!",
  ui_story_5038_50381401_117_dialog_content = "Me presentaron un grupo muy extraño de tres animales: el ratón vacilante, el mono tonto y el conejo astuto.",
  ui_story_5038_50381401_118_dialog_content = "\"Lo que es ilusión se vuelve real, cuando lo real se vuelve ilusión\". Esencialmente, nos está diciendo que <color=#FFB400>reemplazar</color> lo que hemos perdido.",
  ui_story_5038_50381401_119_dialog_content = "¡Así que eso es lo que eso significaba!",
  ui_story_5038_50381401_120_dialog_content = "¿Sobre qué estás divagando?",
  ui_story_5038_50381401_121_dialog_content = "Los palos predijeron todo este viaje.",
  ui_story_5038_50381401_122_dialog_content = "El \"ratón vacilante\" era el capitán que dudaba entre encontrar La Brújula y llegar a Longzhou.",
  ui_story_5038_50381401_123_dialog_content = "El \"conejo astuto\"... ya conoces el dicho: \"Un conejo astuto tiene tres escondites\". Estaba hablando de La Brújula. No sabíamos qué era, qué hacía o dónde estaba.",
  ui_story_5038_50381401_124_dialog_content = "El segundo palo, el \"mono tonto\", reconcilia el primero y el último palo.",
  ui_story_5038_50381401_125_dialog_content = "Solo siendo un tonto, recorriendo el camino imposible y haciendo lo imposible, nuestro viaje puede concluir.",
  ui_story_5038_50381401_126_dialog_content = "Cuando sumas los tres trigramas, puedes ver que lo que debíamos reemplazar no eran partes de un barco.",
  ui_story_5038_50381401_127_dialog_content = "¡Estaba hablando de todo el barco en sí!",
  ui_story_5038_50381401_128_dialog_content = "¿Qué estás tratando de hacer, Yoh?",
  ui_story_5038_50381401_129_dialog_content = "¿Estás tratando de matarlo?",
  ui_story_5038_50381401_130_dialog_content = "...",
  ui_story_5038_50381401_131_dialog_content = "No solo yo. También quiere hundir al Shadowind.",
  ui_story_5038_50381401_132_dialog_content = "¿Por qué harías eso?",
  ui_story_5038_50381401_133_dialog_content = "Sé lo duro que fue para ti encerrado en el tanque pequeño.",
  ui_story_5038_50381401_134_dialog_content = "Y sé que guardas rencor. Te sientes enojado e incluso rencoroso.",
  ui_story_5038_50381401_135_dialog_content = "Pero no todas las personas son iguales, no todos están tratando de lastimarte.",
  ui_story_5038_50381401_136_dialog_content = "¡No deberías hacer que personas inocentes paguen por los pecados de otros!",
  ui_story_5038_50381401_137_dialog_content = "Tú... no deberías... haber... salido.",
  ui_story_5038_50381401_138_dialog_content = "¿Por qué no?",
  ui_story_5038_50381401_139_dialog_content = "Morirás.",
  ui_story_5038_50381401_140_dialog_content = "<color=#e8d9bb>¡Grieta!</color>",
  ui_story_5038_50381401_141_dialog_content = "¡Oh no, la cubierta se está rompiendo!",
  ui_story_5038_50381401_142_dialog_content = "¡Piénsalo, Yo! ¿Es esto realmente lo que quieres?",
  ui_story_5038_50381401_143_dialog_content = "¡Nadie aquí hizo nada malo, especialmente yo!",
  ui_story_5038_50381401_144_dialog_content = "¿Olvidaste cómo solía alimentarte todos los días?",
  ui_story_5038_50381401_145_dialog_content = "<color=#e8d9bb>¡Grieta!</color>",
  ui_story_5038_50381401_146_dialog_content = "¡Tú-Tú—!",
  ui_story_5038_50381401_X146_dialog_content = "Ha pasado el punto de escuchar a alguien más. Si no lo detenemos, todos a bordo del barco perecerán.",
  ui_story_5038_50381401_X147_dialog_content = "Tratemos de encontrar una manera de detenerlo primero.",
  ui_story_5038_50381401_147_dialog_content = "Es inútil, hijo. La poca buena voluntad que tiene hacia ti no es suficiente para sofocar su odio.",
  ui_story_5038_50381401_148_dialog_content = "¿Esperas usar la comida para peces que le diste antes para cambiarla por la vida de todos?",
  ui_story_5038_50381401_149_dialog_content = "Pero...",
  ui_story_5038_50381401_150_dialog_content = "Shadowind no sucumbirá tan fácilmente.",
  ui_story_5038_50381401_151_dialog_content = "¿Dijimos que podías enloquecer y hacer lo que quisieras?",
  ui_story_5038_50381401_152_dialog_content = "¡Sí, no dejaremos que nadie dañe la nave!",
  ui_story_5038_50381401_153_dialog_content = "¿Crees que... está realmente bien golpear a un niño?",
  ui_story_5038_50381401_154_dialog_content = "Es un diablillo y probablemente lo bastante mayor para ser tu abuelo.",
  ui_story_5038_50381401_155_dialog_content = "¡Está a punto de atacar!",
  ui_story_5038_50381401_156_dialog_content = "¡Prepárate para luchar!",
  ui_story_5038_50381402_1_dialog_content = "Fuera del camino.",
  ui_story_5038_50381402_2_dialog_content = "¡Ha perdido mucho poder!",
  ui_story_5038_50381402_3_dialog_content = "Atacándonos parece estar quitándole mucho.",
  ui_story_5038_50381402_4_dialog_content = "Sí. Es un novato y todavía no sabe cómo manejar sus poderes.",
  ui_story_5038_50381402_5_dialog_content = "Desperdició demasiada energía en ataques sin sentido.",
  ui_story_5038_50381402_6_dialog_content = "Debemos someterlo antes de que tenga la oportunidad de tomar represalias.",
  ui_story_5038_50381402_7_dialog_content = "¡Claro, déjame ayudarte!",
  ui_story_5038_50381402_8_dialog_content = "Hundirse... ahora.",
  ui_story_5038_50381402_9_dialog_content = "<color=#e8d9bb>¡Grieta!</color>",
  ui_story_5038_50381402_10_dialog_content = "¡E-está atacando el casco!",
  ui_story_5038_50381402_11_dialog_content = "Y si estoy viendo esto bien, ¡los peces serpiente están nadando hacia aquí!",
  ui_story_5038_50381402_12_dialog_content = "Haz tu jugada, Liqing.",
  ui_story_5038_50381402_13_dialog_content = "¡Entendido!",
  ui_story_5038_50381402_14_dialog_content = "Así que pasamos de ser amigos a ser amigos, ¿eh, Yoh?",
  ui_story_5038_50381402_15_dialog_content = "Li...qing...",
  ui_story_5038_50381402_16_dialog_content = "Has aprendido a hablar.",
  ui_story_5038_50381402_17_dialog_content = "No... me detengas.",
  ui_story_5038_50381402_18_dialog_content = "Es una lástima que nunca tuvimos la oportunidad de hablar.",
  ui_story_5038_50381402_19_dialog_content = "Fuera... de... camino.",
  ui_story_5038_50381402_20_dialog_content = "¿Cuál es tu problema? ¡Soy un manipulador más experimentado que tú!",
  ui_story_5038_50381402_21_dialog_content = "¡Todavía hay muchas cosas que necesitas aprender!",
  ui_story_5038_50381402_22_dialog_content = "Como tu superior, me gustaría enseñártelos, pero...",
  ui_story_5038_50381402_23_dialog_content = "¡Eso tiene que esperar hasta después de que te gane!",
  ui_story_5038_50381402_24_dialog_content = "(¡Ahora, Yuebai!)",
  ui_story_5038_50381402_25_dialog_content = "!!!",
  ui_story_5038_50381402_26_dialog_content = "No pongas una mano en mi barco.",
  ui_story_5038_50381402_27_dialog_content = "Oh...",
  ui_story_5038_50381402_28_dialog_content = "¡Está herido! ¡Consíguelo ahora!",
  ui_story_5038_50381402_29_dialog_content = "¡Bueno! ¡Tengo su brazo izquierdo!",
  ui_story_5038_50381402_30_dialog_content = "Tomaré el brazo derecho, Su Alteza.",
  ui_story_5038_50381402_31_dialog_content = "N-ustedes no tienen que ser tan rudos...",
  ui_story_5038_50381402_32_dialog_content = "Está completamente agotado.",
  ui_story_5038_50381402_33_dialog_content = "¿Él es?",
  ui_story_5038_50381402_34_dialog_content = "Silbido... silbido...",
  ui_story_5038_50381402_35_dialog_content = "Los peces no gritan. Todavía no ha aprendido a gritar de dolor.",
  ui_story_5038_50381402_36_dialog_content = "Uf, finalmente ganamos.",
  ui_story_5038_50381402_37_dialog_content = "¿Significa esto que tenemos The Compass ahora?",
  ui_story_5038_50381402_38_dialog_content = "Sí. Él es La Brújula, sin ninguna duda.",
  ui_story_5038_50381402_39_dialog_content = "Convertirse en un maníaco no cambia su papel como The Compass.",
  ui_story_5038_50381402_40_dialog_content = "¿Entonces, qué hacemos ahora?",
  ui_story_5038_50381402_41_dialog_content = "...",
  ui_story_5038_50381402_42_dialog_content = "...",
  ui_story_5038_50381402_43_dialog_content = "De acuerdo con los procedimientos, debemos confinarlo al Shadowind.",
  ui_story_5038_50381402_44_dialog_content = "Luego pídele que envíe la señal de regreso.",
  ui_story_5038_50381402_45_dialog_content = "Una vez que los peces serpiente reciban la señal, se reunirán alrededor del barco y nos escoltarán de regreso a Longzhou.",
  ui_story_5038_50381402_46_dialog_content = "Este viaje estará desprovisto de más peligros, al igual que los innumerables viajes anteriores.",
  ui_story_5038_50381402_47_dialog_content = "Suspiro...",
  ui_story_5038_50381402_48_dialog_content = "¿Debemos encerrar a un niño?",
  ui_story_5038_50381402_49_dialog_content = "Un viaje seguro suena bien, pero no me siento del todo cómodo con esta opción.",
  ui_story_5038_50381402_50_dialog_content = "Sí, especialmente cuando acabamos de presenciar su desprecio por nosotros.",
  ui_story_5038_50381402_51_dialog_content = "El antepasado Lin inspiró el odio, que se profundizó con cada pasajero que alguna vez subió a bordo.",
  ui_story_5038_50381402_52_dialog_content = "Todos optaron por creer que The Compass era solo un pez, incapaz de guardar rencor.",
  ui_story_5038_50381402_53_dialog_content = "Todos creían que si no había odio no había crimen, y sin crimen no había necesidad de culpa.",
  ui_story_5038_50381402_54_dialog_content = "Pero es demasiado tarde para arrepentirse cuando el odio se manifiesta ante tus ojos.",
  ui_story_5038_50381402_55_dialog_content = "¿Sientes arrepentimiento, Señor Zhong?",
  ui_story_5038_50381402_56_dialog_content = "Sientes que confinar a The Compass también está mal, ¿no es así?",
  ui_story_5038_50381402_57_dialog_content = "me arrepiento de muchas cosas",
  ui_story_5038_50381402_58_dialog_content = "Estuvo mal masacrar a toda esa gente, y está mal esclavizar a The Compass.",
  ui_story_5038_50381402_59_dialog_content = "Trasladar un tema que debería haberse resuelto en tierra al mar es como terminamos en esta posición.",
  ui_story_5038_50381402_60_dialog_content = "Entonces, ¿vamos a ir por el mismo camino equivocado...?",
  ui_story_5038_50381402_61_dialog_content = "Dada mi edad, no tengo ningún problema en expiar mis pecados con mi vida.",
  ui_story_5038_50381402_62_dialog_content = "Pero hay más personas presentes aquí que solo yo.",
  ui_story_5038_50381402_63_dialog_content = "¿Tenemos alguna esperanza de llegar a Longzhou sin explotar The Compass?",
  ui_story_5038_50381402_64_dialog_content = "Bueno...",
  ui_story_5038_50381402_65_dialog_content = "El barco está maltratado y todavía no sabemos el alcance de los daños...",
  ui_story_5038_50381402_66_dialog_content = "Sé lo que significa Zhong Xu, porque yo mismo lo he pensado mucho.",
  ui_story_5038_50381402_67_dialog_content = "La mayoría de las veces, tus manos están atadas cuando estás en el mar.",
  ui_story_5038_50381402_68_dialog_content = "Pienso en Yoh como mi amigo y quiero verlo libre, pero...",
  ui_story_5038_50381402_69_dialog_content = "No puedo pagar el precio de esa decisión.",
  ui_story_5038_50381402_70_dialog_content = "Precio...",
  ui_story_5038_50381402_71_dialog_content = "(Nadie dice una palabra ahora.)",
  ui_story_5038_50381402_72_dialog_content = "(Todos intercambiamos miradas para tratar de disimular la impotencia que sentimos.)",
  ui_story_5038_50381402_73_dialog_content = "(Como si estuviéramos mostrando remordimiento a través del silencio).",
  ui_story_5038_50381402_74_dialog_content = "(Sabemos que está mal, pero no tenemos otra opción).",
  ui_story_5038_50381402_75_dialog_content = "No seamos tan sombríos.",
  ui_story_5038_50381402_76_dialog_content = "Encontramos La Brújula. Debemos estar felices de haber cumplido nuestra misión.",
  ui_story_5038_50381402_77_dialog_content = "Vale la pena celebrar el hecho de que podamos terminar nuestro viaje, capitán.",
  ui_story_5038_50381402_78_dialog_content = "Pero la idea de encerrar al niño...",
  ui_story_5038_50381402_79_dialog_content = "¿Quién dice que lo vamos a encerrar? ¿Es eso necesario?",
  ui_story_5038_50381402_80_dialog_content = "¿Ah?",
  ui_story_5038_50381402_81_dialog_content = "¿Qué quiere decir, capitán?",
  ui_story_5038_50381402_82_dialog_content = "Teníamos que encontrar La Brújula para tener alguna esperanza de llegar a Longzhou.",
  ui_story_5038_50381402_83_dialog_content = "Ahora que lo hemos localizado, tenemos muchas opciones en cuanto a cómo podemos utilizarlo.",
  ui_story_5038_50381402_84_dialog_content = "Está claro que ninguno de nosotros está de acuerdo con cómo lo hicieron los Lin.",
  ui_story_5038_50381402_85_dialog_content = "Así que exploraré otras opciones.",
  ui_story_5038_50381402_86_dialog_content = "¿En serio? ¿Realmente no tenemos que mantener cautivo a Yoh?",
  ui_story_5038_50381402_87_dialog_content = "...",
  ui_story_5038_50381402_88_dialog_content = "Dime, ¿estás dispuesto a ser un invitado a bordo del Shadowind?",
  ui_story_5038_50381402_89_dialog_content = "... No.",
  ui_story_5038_50381402_90_dialog_content = "Por supuesto no.",
  ui_story_5038_50381402_91_dialog_content = "Entonces supongo que aquí es donde nos separamos.",
  ui_story_5038_50381402_92_dialog_content = "Este barco se hundirá pronto. Deberías volver al mar.",
  ui_story_5038_50381402_93_dialog_content = "Lo dejó ir. Regresamos a nuestra nave.",
  ui_story_5038_50381402_94_dialog_content = "A-¿Estás seguro?",
  ui_story_5038_50381402_95_dialog_content = "Será imposible volver a encontrarlo.",
  ui_story_5038_50381402_96_dialog_content = "Él es un pez. Es mucho más adecuado para el océano que para un barco.",
  ui_story_5038_50381402_97_dialog_content = "Vamos. La niebla se ha ido. Deberíamos reanudar el viaje.",
  ui_story_5038_50381402_98_dialog_content = "¿Has tomado una decisión?",
  ui_story_5038_50381402_99_dialog_content = "En seguida.",
  ui_story_5038_50381402_100_dialog_content = "¿Vas a detenerme, Señor Zhong?",
  ui_story_5038_50381402_101_dialog_content = "Le prometí al viejo Sr. Lin que protegería el tesoro familiar.",
  ui_story_5038_50381402_102_dialog_content = "Cumplí esa promesa entregando The Compass a un miembro de la familia Lin.",
  ui_story_5038_50381402_103_dialog_content = "Mientras seas consciente de las consecuencias de tu decisión, la respetaré.",
  ui_story_5038_50381402_104_dialog_content = "Vamos, escuchaste las órdenes del capitán.",
  ui_story_5038_50381402_105_dialog_content = "Ella sabe más que nosotros cuando se trata de navegar.",
  ui_story_5038_50381402_106_dialog_content = "Sí, cierto... No debemos preocuparnos.",
  ui_story_5038_50381402_107_dialog_content = "Vamos... Muévete, PlayerName, ¿por qué estás parado ahí?",
  ui_story_5038_50381402_108_dialog_content = "Oh, solo estoy viendo el pez serpiente.",
  ui_story_5038_50381402_109_dialog_content = "Es espectacular como siguen dando vueltas al barco.",
  ui_story_5038_50381402_110_dialog_content = "Como si estuvieran esperando a que se hunda.",
  ui_story_5038_50381402_111_dialog_content = "Oh, no empieces a encerar poéticas aquí o lo que sea. Puedes hacerlo desde Shadowind.",
  ui_story_5038_50381402_112_dialog_content = "Pongámonos en marcha.",
  ui_story_5038_50381402_113_dialog_content = "Está bien, ya voy.",
  ui_story_5038_50381402_114_dialog_content = "¡Felicitaciones, Yoh, ahora eres libre!",
  ui_story_5038_50381402_115_dialog_content = "Gratis...",
  ui_story_5038_50381402_116_dialog_content = "¿No lo entiendes? Dijeron que te dejarían ir.",
  ui_story_5038_50381402_117_dialog_content = "No es fácil convertirse en un fiendling. Recuerda seguir practicando hablar.",
  ui_story_5038_50381402_118_dialog_content = "Tratar de conversar contigo es agotador.",
  ui_story_5038_50381402_119_dialog_content = "¿Déjame ir?",
  ui_story_5038_50381402_120_dialog_content = "Sí, ¿no lo entiendes?",
  ui_story_5038_50381402_121_dialog_content = "Ve y dirígete a donde sea que estés destinado a estar.",
  ui_story_5038_50381402_122_dialog_content = "Yo...",
  ui_story_5038_50381402_123_dialog_content = "Me tengo que ir. No voy a caerme al agua.",
  ui_story_5038_50381402_124_dialog_content = "Pero nunca olvides que Liqing es tu amigo.",
  ui_story_5038_50381402_125_dialog_content = "¡Adiós!",
  ui_story_5038_50381402_126_dialog_content = "¡Ahí está, Capitán!",
  ui_story_5038_50381402_127_dialog_content = "El barco fue embestido, luego abordado por Eclipsites y sufrió muchos daños.",
  ui_story_5038_50381402_128_dialog_content = "Estamos trabajando duro tratando de volver a armarlo...",
  ui_story_5038_50381402_129_dialog_content = "Entendí. No se detenga con las reparaciones, pero asegúrese de desplegar las velas de inmediato.",
  ui_story_5038_50381402_130_dialog_content = "Estamos zarpando.",
  ui_story_5038_50381402_131_dialog_content = "¿Ahora? ¿No deberíamos reagruparnos primero?",
  ui_story_5038_50381402_132_dialog_content = "No tenemos tiempo.",
  ui_story_5038_50381402_133_dialog_content = "El pez serpiente pronto comenzará su viaje de regreso y debemos seguirlos de cerca.",
  ui_story_5038_50381402_134_dialog_content = "¿El pez serpiente?",
  ui_story_5038_50381402_135_dialog_content = "¡Es cierto, los peces serpiente están empezando a nadar!",
  ui_story_5038_50381402_136_dialog_content = "¡Todos van en la misma dirección!",
  ui_story_5038_50381402_137_dialog_content = "Ahí es donde se encuentra Longzhou.",
  ui_story_5038_50381402_138_dialog_content = "Nada en el océano quiere volver a casa más que ellos.",
  ui_story_5038_50381402_139_dialog_content = "¡Oh ya entiendo!",
  ui_story_5038_50381402_140_dialog_content = "Sabías que una vez que dejaras ir a Yoh, el pez serpiente reanudaría su viaje original.",
  ui_story_5038_50381402_141_dialog_content = "¡Pueden llevarnos por la ruta más rápida de regreso a Longzhou!",
  ui_story_5038_50381402_142_dialog_content = "Suena simple, pero mantenerse al día con el pez serpiente es más difícil de lo que piensas.",
  ui_story_5038_50381402_143_dialog_content = "Necesitaré la ayuda de todos en el tramo final de este viaje.",
  ui_story_5038_50381402_144_dialog_content = "¡Puedes contar con ello!",
  ui_story_5038_50381402_145_dialog_content = "Oh no, estamos goteando de nuevo...",
  ui_story_5038_50381402_146_dialog_content = "¡Necesitamos más manos a la obra!",
  ui_story_5038_50381402_147_dialog_content = "Todos los miembros de la tripulación están demasiado ocupados para ayudar en este momento.",
  ui_story_5038_50381402_148_dialog_content = "Será muy duro para el maltratado Shadowind navegar en el mar embravecido.",
  ui_story_5038_50381402_149_dialog_content = "¿Esto aguantará?",
  ui_story_5038_50381402_150_dialog_content = "La grieta que sellamos antes está goteando de nuevo.",
  ui_story_5038_50381402_151_dialog_content = "Estamos trabajando duro para rescatar el agua, pero el nivel sigue subiendo.",
  ui_story_5038_50381402_152_dialog_content = "Qué podemos hacer ahora...",
  ui_story_5038_50381402_153_dialog_content = "No importa, ya que todo el mundo está lo suficientemente ocupado como está.",
  ui_story_5038_50381402_154_dialog_content = "Tendremos que rescatar más rápido.",
  ui_story_5038_50381402_155_dialog_content = "Mira, ahora tengo un balde en cada mano.",
  ui_story_5038_50381402_156_dialog_content = "Espera hasta que me mete uno en la boca, ¡entonces puedo achicar el agua de tres personas!",
  ui_story_5038_50381402_157_dialog_content = "¿Eso va a funcionar?",
  ui_story_5038_50381402_158_dialog_content = "Tiene que. Todo el mundo va a por todas ya que estamos tan cerca.",
  ui_story_5038_50381402_159_dialog_content = "Todo estará bien mientras el barco aún pueda navegar a toda velocidad.",
  ui_story_5038_50381402_160_dialog_content = "¡Deberías irte y dejarme ir a trabajar!",
  ui_story_5038_50381402_161_dialog_content = "¿Quién tiene un balde vacío? ¡Dame una!",
  ui_story_5038_50381402_162_dialog_content = "Aqui, PlayerName!",
  ui_story_5038_50381402_163_dialog_content = "¡Por favor, échame una mano!",
  ui_story_5038_50381402_164_dialog_content = "¿Qué está pasando, Dantang? Qué estás haciendo...?",
  ui_story_5038_50381402_165_dialog_content = "El cabrestante que mantiene las velas en su lugar está roto, por lo que ahora las cuerdas deben manejarse a mano.",
  ui_story_5038_50381402_166_dialog_content = "Lo hice antes, pero ahora...",
  ui_story_5038_50381402_167_dialog_content = "El viento se levantó y me está exigiendo físicamente.",
  ui_story_5038_50381402_168_dialog_content = "¡Ah, claro! Puedo ayudar.",
  ui_story_5038_50381402_169_dialog_content = "¿Así que sigo jalándolo así?",
  ui_story_5038_50381402_170_dialog_content = "Sí, así como así.",
  ui_story_5038_50381402_171_dialog_content = "Tus manos están todas rojas... ¿Estás bien?",
  ui_story_5038_50381402_172_dialog_content = "Está bien. Es solo porque nunca hago un trabajo físico como este.",
  ui_story_5038_50381402_173_dialog_content = "Sería completamente inútil si ni siquiera pudiera manejar esta pequeña tarea.",
  ui_story_5038_50381402_174_dialog_content = "Pero no sabemos cuánto tiempo nos queda todavía. Tus manos...",
  ui_story_5038_50381402_175_dialog_content = "¿Y qué? Incluso Shadowind no se ha rendido.",
  ui_story_5038_50381402_176_dialog_content = "¡Tira esta caja por la borda!",
  ui_story_5038_50381402_177_dialog_content = "¡Sí!",
  ui_story_5038_50381402_178_dialog_content = "¡Guau, se siente liberador tirar cosas por la borda!",
  ui_story_5038_50381402_179_dialog_content = "¡Y esto también! ¡Echarlo!",
  ui_story_5038_50381402_180_dialog_content = "¿Vamos a tirar todas las mantas?",
  ui_story_5038_50381402_181_dialog_content = "Sí, no vamos a dormir por un tiempo.",
  ui_story_5038_50381402_182_dialog_content = "Muy bien, ¡esto también va al mar!",
  ui_story_5038_50381402_183_dialog_content = "Pierde todo lo que no es esencial. ¡Cada bit cuenta!",
  ui_story_5038_50381402_184_dialog_content = "¡Luchamos contra el mismo mar por más tiempo!",
  ui_story_5038_50381402_185_dialog_content = "Eso es cierto.",
  ui_story_5038_50381402_186_dialog_content = "¡Tíralo, deshazte de todo!",
  ui_story_5038_50381402_187_dialog_content = "¡Y todas las mesas, sillas y muebles!",
  ui_story_5038_50381402_188_dialog_content = "(Las personas a bordo nunca han estado más ocupadas).",
  ui_story_5038_50381402_189_dialog_content = "(Cada miembro de la tripulación y cada parte del barco se está trabajando al máximo).",
  ui_story_5038_50381402_190_dialog_content = "(Hay dos resultados posibles para nosotros: Sink o Longzhou).",
  ui_story_5038_50381402_191_dialog_content = "(Es una lucha entre lo realista y lo idealista).",
  ui_story_5038_50381402_192_dialog_content = "(Mucho más allá, en la dirección donde se encuentra la tierra, el sol se eleva sobre el horizonte, mientras nuestro barco continúa hundiéndose).",
  ui_story_5038_50381402_193_dialog_content = "(El universo está esperando ansiosamente para revelarnos nuestro destino final).",
  ui_story_5038_50381402_194_dialog_content = "¡Estamos acabados, toda la bodega está inundada!",
  ui_story_5038_50381402_195_dialog_content = "¿Alguna idea, marineros veteranos?",
  ui_story_5038_50381402_196_dialog_content = "esta todo inundado...",
  ui_story_5038_50381402_197_dialog_content = "No hay nada que podamos hacer. Si la bodega está inundada, lo siguiente...",
  ui_story_5038_50381402_198_dialog_content = "¡Vaya, hay agua en la cubierta!",
  ui_story_5038_50381402_199_dialog_content = "¿Qué se supone que debemos hacer ahora...?",
  ui_story_5038_50381402_200_dialog_content = "N-Nos estamos hundiendo...",
  ui_story_5038_50381402_201_dialog_content = "Que hacemos, que hacemos...",
  ui_story_5038_50381402_202_dialog_content = "¡Capitán! ¡Capitán!",
  ui_story_5038_50381402_203_dialog_content = "¿A dónde fuiste? ¿Ves lo que está pasando?",
  ui_story_5038_50381402_204_dialog_content = "No entrar en pánico. Solo espera en cubierta.",
  ui_story_5038_50381402_205_dialog_content = "El Shadowind no se hundirá.",
  ui_story_5038_50381402_206_dialog_content = "<color=#e8d9bb>¡Estallido! ¡Estallido! ¡Estallido!</color>",
  ui_story_5038_50381402_207_dialog_content = "¿Q-Qué es eso?",
  ui_story_5038_50381402_208_dialog_content = "Algo está golpeando el fondo de la nave...",
  ui_story_5038_50381402_209_dialog_content = "¡Espera un minuto! ¿Sienten eso? ¡Parece que estamos subiendo!",
  ui_story_5038_50381402_210_dialog_content = "¡Estás bien! Que sucede-",
  ui_story_5038_50381402_211_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_5038_50381402_212_dialog_content = "¿Estamos volando?",
  ui_story_5038_50381402_213_dialog_content = "¡M-Mira ahí abajo! ¡Es pescado, mucho pez serpiente!",
  ui_story_5038_50381402_214_dialog_content = "¡Llevan el barco sobre sus espaldas!",
  ui_story_5038_50381402_215_dialog_content = "¡Ay, qué espectacular!",
  ui_story_5038_50381402_216_dialog_content = "Te dije que los peces serpiente eran mucho más adecuados para el océano que para un barco.",
  ui_story_5038_50381402_217_dialog_content = "¡Sí, Yoh nos está ayudando!",
  ui_story_5038_50381402_218_dialog_content = "¿Estás ahí, Yo?",
  ui_story_5038_50381402_219_dialog_content = "¡¡¡Gracias!!!",
  ui_story_5038_50381402_220_dialog_content = "¿Pensaste que esto sucedería cuando dejaras ir a Yoh, Yuebai?",
  ui_story_5038_50381402_221_dialog_content = "No. Nadie puede predecir el curso del efímero mar.",
  ui_story_5038_50381402_222_dialog_content = "Todo lo que sé es que hicimos nuestro mejor esfuerzo y logramos todas nuestras metas.",
  ui_story_5038_50381402_223_dialog_content = "Seguro que llegaremos a Longzhou.",
  ui_story_5038_50381501_1_dialog_content = "¿Ya viene el Señor Zhong?",
  ui_story_5038_50381501_2_dialog_content = "Rápido, tráelo aquí.",
  ui_story_5038_50381501_3_dialog_content = "¡Viene, viene! Caray, todos ustedes simplemente ordenan a la gente.",
  ui_story_5038_50381501_4_dialog_content = "¿Qué estás haciendo, Liqing?",
  ui_story_5038_50381501_5_dialog_content = "No queremos que te pierdas la fabulosa vista.",
  ui_story_5038_50381501_6_dialog_content = "Mira allá. ¿Que ves?",
  ui_story_5038_50381501_7_dialog_content = "Eso es...",
  ui_story_5038_50381501_8_dialog_content = "¿Estamos en casa?",
  ui_story_5038_50381501_9_dialog_content = "¡Sí, estamos en casa! ¡Eso es Longzhou!",
  ui_story_5038_50381501_10_dialog_content = "¿Lo extrañas?",
  ui_story_5038_50381501_11_dialog_content = "Longzhou...",
  ui_story_5038_50381501_12_dialog_content = "En mi vida, el suelo bajo mis pies rara vez ha sido Longzhou.",
  ui_story_5038_50381501_13_dialog_content = "No esperaba sentir tanta nostalgia al escucharte mencionarlo.",
  ui_story_5038_50381501_14_dialog_content = "Nos hemos ido demasiado tiempo.",
  ui_story_5038_50381501_15_dialog_content = "Sí. Hemos pasado por mucho y viajado hasta ahora.",
  ui_story_5038_50381501_16_dialog_content = "Durante este viaje, hemos cambiado de barco. Ahora también estoy confinado a una silla de ruedas.",
  ui_story_5038_50381501_17_dialog_content = "No será tan fácil para mí saludar al Emperador la próxima vez que lo visite.",
  ui_story_5038_50381501_18_dialog_content = "No me digas que el palacio es todo lo que extrañas de Longzhou.",
  ui_story_5038_50381501_19_dialog_content = "Te pondrás nostálgico cuando llegues a mi edad también.",
  ui_story_5038_50381501_20_dialog_content = "Ya sea en la corte real o en cualquier otro lugar, añoro todos los lugares en los que he estado.",
  ui_story_5038_50381501_21_dialog_content = "Es un fastidio hablar contigo...",
  ui_story_5038_50381501_22_dialog_content = "Solo dime, ¿disfrutas de la vista desde la cubierta en este momento?",
  ui_story_5038_50381501_23_dialog_content = "Sí, lo disfruto mucho.",
  ui_story_5038_50381501_24_dialog_content = "¡Mira, los peces serpiente se alejan nadando!",
  ui_story_5038_50381501_25_dialog_content = "Por supuesto. No pueden bajar a tierra con nosotros.",
  ui_story_5038_50381501_26_dialog_content = "Se van a hacer lo suyo después de ayudarnos.",
  ui_story_5038_50381501_27_dialog_content = "Después de haber sido llevado por ellos durante tanto tiempo, es un poco triste decir adiós.",
  ui_story_5038_50381501_28_dialog_content = "Probablemente me hayan echado a perder.",
  ui_story_5038_50381501_29_dialog_content = "Mi amo dice que las despedidas siempre son agridulces.",
  ui_story_5038_50381501_30_dialog_content = "Pero como no están destinados a quedarse con nosotros, lo mejor es conformarse con una despedida adecuada.",
  ui_story_5038_50381501_31_dialog_content = "Sí, supongo. Todos los viajes llegan a su fin.",
  ui_story_5038_50381501_32_dialog_content = "¡Adiós! ¡Gracias a todos!",
  ui_story_5038_50381501_33_dialog_content = "*Sollozando* Por fin estamos en casa...",
  ui_story_5038_50381501_34_dialog_content = "Sí, pensé que todos íbamos a morir en el mar.",
  ui_story_5038_50381501_35_dialog_content = "Es genial ver tierra.",
  ui_story_5038_50381501_36_dialog_content = "Todo es gracias al capitán. Sin ella, el barco se habría hundido diez veces.",
  ui_story_5038_50381501_37_dialog_content = "¡Sí, tenemos un capitán increíble!",
  ui_story_5038_50381501_38_dialog_content = "¿Solo piensa en lo que ella nos llevó a lograr?",
  ui_story_5038_50381501_39_dialog_content = "¡Hemos restaurado la ruta Lin!",
  ui_story_5038_50381501_40_dialog_content = "¡Oye, aquí viene el capitán!",
  ui_story_5038_50381501_41_dialog_content = "¡Por aquí, capitán! ¡Solo te estábamos llenando de elogios!",
  ui_story_5038_50381501_42_dialog_content = "Ustedes...",
  ui_story_5038_50381501_43_dialog_content = "¿Qué haces pasando el rato aquí? ¡Vuelve a tus publicaciones!",
  ui_story_5038_50381501_44_dialog_content = "El barco se dirige hacia el puerto. Aún no ha terminado.",
  ui_story_5038_50381501_45_dialog_content = "Escuche eso, no se acaba hasta que se acaba, ¡órdenes del capitán!",
  ui_story_5038_50381501_46_dialog_content = "¡Ey ey!",
  ui_story_5038_50381501_47_dialog_content = "Estoy, eh, un poco nervioso.",
  ui_story_5038_50381501_48_dialog_content = "¿Qué se supone que debo hacer después de bajar del barco?",
  ui_story_5038_50381501_49_dialog_content = "¿Por qué estás nervioso? ¡Solo síguenos!",
  ui_story_5038_50381501_50_dialog_content = "Acabas de capear una tormenta infernal en el mar. ¿Cómo puede ser más aterrador estar en tierra?",
  ui_story_5038_50381501_51_dialog_content = "Pero estos alrededores son totalmente nuevos...",
  ui_story_5038_50381501_52_dialog_content = "Nada me es familiar, y estoy solo.",
  ui_story_5038_50381501_53_dialog_content = "¿Qué quieres decir con que estás solo? ¿No nos tienes?",
  ui_story_5038_50381501_54_dialog_content = "Así es.",
  ui_story_5038_50381501_55_dialog_content = "Solo quédate conmigo en Longzhou y me aseguraré de que pases el mejor momento de tu vida.",
  ui_story_5038_50381501_56_dialog_content = "Muy bien, comencemos a empacar.",
  ui_story_5038_50381501_57_dialog_content = "El capitán insta a todos a empezar a prepararse para desembarcar.",
  ui_story_5038_50381501_58_dialog_content = "Espinos confitados!",
  ui_story_5038_50381501_59_dialog_content = "¡Se venden espinos confitados!",
  ui_story_5038_50381501_60_dialog_content = "¿Cuánto cuestan, señor?",
  ui_story_5038_50381501_61_dialog_content = "Oye, allí hay un fabricante de dulces, ¡vamos a verlo!",
  ui_story_5038_50381501_62_dialog_content = "¿Son empanadillas dulces lo que huelo?",
  ui_story_5038_50381501_63_dialog_content = "¡Guau, las calles están bulliciosas!",
  ui_story_5038_50381501_64_dialog_content = "¡Tanta gente!",
  ui_story_5038_50381501_65_dialog_content = "¿Entonces, qué piensas?",
  ui_story_5038_50381501_66_dialog_content = "No estoy seguro... ¿Las calles de Longzhou siempre están tan llenas de gente?",
  ui_story_5038_50381501_67_dialog_content = "No siempre. Llegaste justo a tiempo para el final del Festival de Primavera.",
  ui_story_5038_50381501_68_dialog_content = "Es el momento más popular en Longzhou. Las calles se llenan de cosas divertidas y sabrosas.",
  ui_story_5038_50381501_69_dialog_content = "Mira, ese chico tiene lo que se llama Espino confitado. Son súper ácidos, dulces y deliciosos.",
  ui_story_5038_50381501_70_dialog_content = "Y en esa mesa hay pequeñas figuritas con forma de azúcar. Son solo para apariencia, no comestibles.",
  ui_story_5038_50381501_71_dialog_content = "Luego, hirviendo en esa olla enorme, están las albóndigas dulces, disponibles solo durante este tiempo.",
  ui_story_5038_50381501_72_dialog_content = "¡Vaya, todo se ve bien!",
  ui_story_5038_50381501_73_dialog_content = "¡Solo pregúntame si tienes curiosidad sobre algo!",
  ui_story_5038_50381501_74_dialog_content = "Déjame tomar todo esto.",
  ui_story_5038_50381501_75_dialog_content = "Ese puesto en el suelo con el vendedor sacudiendo un bote de palos...",
  ui_story_5038_50381501_76_dialog_content = "¡Oh, no caigas en eso! ¡Es una estafa total!",
  ui_story_5038_50381501_77_dialog_content = "¿Una estafa?",
  ui_story_5038_50381501_78_dialog_content = "Sí, se llama adivinación. No es algo que valga la pena escribir en casa.",
  ui_story_5038_50381501_79_dialog_content = "Esos charlatanes dirán cualquier cosa para atraparte anzuelo, sedal y pecador.",
  ui_story_5038_50381501_80_dialog_content = "Es poco más que inventar cosas para estafarlo.",
  ui_story_5038_50381501_81_dialog_content = "¿Por qué no son arrestados y encarcelados?",
  ui_story_5038_50381501_82_dialog_content = "Bueno, es bastante complicado...",
  ui_story_5038_50381501_83_dialog_content = "De todos modos, no los escuches, no confíes en ellos. Si quieres saber lo que depara el futuro, ¡soy el hombre!",
  ui_story_5038_50381501_84_dialog_content = "¿Tú?",
  ui_story_5038_50381501_85_dialog_content = "¿Pensé que adivinar era una estafa?",
  ui_story_5038_50381501_86_dialog_content = "Se trata de quién está haciendo la adivinación. Te lo dije, es complicado.",
  ui_story_5038_50381501_87_dialog_content = "Je, hay un dicho en Longzhou que dice: \"Dos de un oficio rara vez están de acuerdo\".",
  ui_story_5038_50381501_88_dialog_content = "Te dejaré reflexionar sobre eso, PlayerName.",
  ui_story_5038_50381501_89_dialog_content = "Despeja el camino, despeja el camino!",
  ui_story_5038_50381501_90_dialog_content = "¿No ves pasar una silla de ruedas?",
  ui_story_5038_50381501_91_dialog_content = "Reduzca la velocidad, Liqing, para no molestar a los demás.",
  ui_story_5038_50381501_92_dialog_content = "¡De ninguna manera! ¡Después de todos los problemas para llegar a casa, voy a caminar como quiera!",
  ui_story_5038_50381501_93_dialog_content = "Pero, ¿adónde vamos todos, capitán?",
  ui_story_5038_50381501_94_dialog_content = "Shadowind es el barco de los Lin, así que, naturalmente, debo regresar al Lin Guild.",
  ui_story_5038_50381501_95_dialog_content = "Si no le importa, está invitado a quedarse como mis invitados.",
  ui_story_5038_50381501_96_dialog_content = "Más, mejor para la temporada de festivales.",
  ui_story_5038_50381501_97_dialog_content = "¿Nos vamos, viejo?",
  ui_story_5038_50381501_98_dialog_content = "estoy muerto de hambre",
  ui_story_5038_50381501_99_dialog_content = "Por supuesto que somos. Habría ido incluso sin la invitación.",
  ui_story_5038_50381501_100_dialog_content = "El Lin Guildmaster me debe mucho.",
  ui_story_5038_50381501_101_dialog_content = "Nadie cobra deudas durante el Festival de Primavera, Lord Zhong.",
  ui_story_5038_50381501_102_dialog_content = "Y dado el lamentable estado en el que se encuentra actualmente el gremio, no podríamos pagar el precio de venta de un general adecuado como usted, mi señor.",
  ui_story_5038_50381501_103_dialog_content = "Bueno, esa es la idea.",
  ui_story_5038_50381501_104_dialog_content = "Quiero que se avergüence de ese hecho por el resto de su vida.",
  ui_story_5038_50381501_105_dialog_content = "¡Están de vuelta! ¡Los viajeros Shadowind están de vuelta!",
  ui_story_5038_50381501_106_dialog_content = "¡Por favor entra! ¡Debe haber sido un viaje duro!",
  ui_story_5038_50381501_107_dialog_content = "¡Debes de estar exhausto!",
  ui_story_5038_50381501_108_dialog_content = "¿Así que esta es la mansión Lin?",
  ui_story_5038_50381501_109_dialog_content = "No esperaba que el edificio fuera bastante común para un clan que construyó una nave tan grande como Shadowind.",
  ui_story_5038_50381501_110_dialog_content = "No lo están haciendo muy bien, después de todo.",
  ui_story_5038_50381501_111_dialog_content = "Escuché que su puerta de entrada solía ser mucho más grandiosa.",
  ui_story_5038_50381501_112_dialog_content = "No me gustan las puertas grandes, son tan impersonales.",
  ui_story_5038_50381501_113_dialog_content = "¡Tiene esa sensación de Festival de Primavera tal como es ahora!",
  ui_story_5038_50381501_114_dialog_content = "¿Por qué no entras ya que estás en casa?",
  ui_story_5038_50381501_115_dialog_content = "No te quedes ahí parado.",
  ui_story_5038_50381501_116_dialog_content = "¿Quién es este señor mayor?",
  ui_story_5038_50381501_117_dialog_content = "Guildmaster, no tenías que salir a saludarnos.",
  ui_story_5038_50381501_118_dialog_content = "¿Cómo no iba a poder oír la noticia del regreso de Shadowind?",
  ui_story_5038_50381501_119_dialog_content = "Todos ustedes son estimados invitados por lo que hicieron. Debería haberte estado esperando en el muelle en persona.",
  ui_story_5038_50381501_120_dialog_content = "Así es, debería haber hecho un festín en el muelle para darnos la bienvenida.",
  ui_story_5038_50381501_121_dialog_content = "En lugar de simplemente sentarnos en casa, disfrutando de los frutos de nuestro trabajo.",
  ui_story_5038_50381501_122_dialog_content = "¡Zhong Xu, has vuelto!",
  ui_story_5038_50381501_123_dialog_content = "Tus piernas...",
  ui_story_5038_50381501_124_dialog_content = "Están bien.",
  ui_story_5038_50381501_125_dialog_content = "Todo lo que sufrí luchando por el Ejército Imperial todos esos años fueron algunas cicatrices.",
  ui_story_5038_50381501_126_dialog_content = "Pero haciendo mandados para tu gremio, he logrado romperme ambas piernas.",
  ui_story_5038_50381501_127_dialog_content = "Viejo Lin, has superado al mismísimo Emperador.",
  ui_story_5038_50381501_128_dialog_content = "Por favor, no digas eso, no me atrevería...",
  ui_story_5038_50381501_129_dialog_content = "Te encontraré el mejor médico. Solo quédate y tómate tu tiempo para recuperarte.",
  ui_story_5038_50381501_130_dialog_content = "Eso no será necesario. Me gusta mucho relajarme en la silla de ruedas.",
  ui_story_5038_50381501_131_dialog_content = "Además, ¿cómo se vería en Liqing si alguien lograra curar mis piernas?",
  ui_story_5038_50381501_132_dialog_content = "¡Eso es imposible!",
  ui_story_5038_50381501_133_dialog_content = "¡Tus piernas no se pueden curar, no importa quién lo intente!",
  ui_story_5038_50381501_134_dialog_content = "E-Él es muy directo, ¿no?",
  ui_story_5038_50381501_135_dialog_content = "No le hagas caso. Liqing siempre ha sido un francotirador.",
  ui_story_5038_50381501_136_dialog_content = "El viaje que tuvimos fue bastante emocionante...",
  ui_story_5038_50381501_137_dialog_content = "Sin embargo, no pude recuperar La Brújula, Lin.",
  ui_story_5038_50381501_138_dialog_content = "Zhong Xu...",
  ui_story_5038_50381501_139_dialog_content = "Me estás avergonzando.",
  ui_story_5038_50381501_140_dialog_content = "No fue fácil para ti volver a ser como es.",
  ui_story_5038_50381501_141_dialog_content = "Es mi culpa por no poder proteger el negocio familiar y cargar a un amigo.",
  ui_story_5038_50381501_142_dialog_content = "Por la presente, me disculpo contigo, Zhong Xu, así como con todos los presentes.",
  ui_story_5038_50381501_143_dialog_content = "Oh, no importa eso.",
  ui_story_5038_50381501_144_dialog_content = "Perdí La Brújula, así que estamos a mano.",
  ui_story_5038_50381501_145_dialog_content = "Pero tienes un heredero brillante que ahora puede navegar la ruta sin The Compass.",
  ui_story_5038_50381501_146_dialog_content = "Deberías guardar tus sentimientos por ella.",
  ui_story_5038_50381501_147_dialog_content = "Hablando de eso, eso es cierto. Aquí estás, de vuelta en Longzhou a salvo sin The Compass.",
  ui_story_5038_50381501_148_dialog_content = "Lo has hecho increíblemente bien, Yuebai.",
  ui_story_5038_50381501_149_dialog_content = "Debo confesar, Guildmaster.",
  ui_story_5038_50381501_150_dialog_content = "De hecho, teníamos The Compass, pero decidí dejarlo pasar.",
  ui_story_5038_50381501_151_dialog_content = "Dejas...",
  ui_story_5038_50381501_152_dialog_content = "Sentí que no estaba bien cómo explotamos The Compass.",
  ui_story_5038_50381501_153_dialog_content = "Mi conciencia está tranquila, pero el hecho es que perdí un activo valioso.",
  ui_story_5038_50381501_154_dialog_content = "Por lo tanto, aceptaré cualquier castigo que elijas.",
  ui_story_5038_50381501_155_dialog_content = "Jajajaja. ¿Estás confesando un pecado o lanzando una acusación?",
  ui_story_5038_50381501_156_dialog_content = "¿Aprendiste a esconder espadas en tus palabras del Señor Zhong allá?",
  ui_story_5038_50381501_157_dialog_content = "Esa no era mi intención, señor.",
  ui_story_5038_50381501_158_dialog_content = "No era un tesoro valioso, sino un último esfuerzo para navegar el mar.",
  ui_story_5038_50381501_159_dialog_content = "Debería alegrarme de que ya no tengas que depender de él.",
  ui_story_5038_50381501_160_dialog_content = "Gracias por su benevolencia, Guildmaster.",
  ui_story_5038_50381501_161_dialog_content = "¿Por qué eres tan formal, hija mía?",
  ui_story_5038_50381501_162_dialog_content = "Encabezaste una ruta marítima para Lin Guild por tu cuenta. Es posible que pronto seas el próximo Guildmaster.",
  ui_story_5038_50381501_163_dialog_content = "¡¿Qué?!",
  ui_story_5038_50381501_164_dialog_content = "Señor, usted exagera...",
  ui_story_5038_50381501_165_dialog_content = "No no soy. Te lo mereces.",
  ui_story_5038_50381501_166_dialog_content = "Espero que dejes atrás tus orígenes. Todo está en el pasado.",
  ui_story_5038_50381501_167_dialog_content = "Lo que Lin puede hacer, Mu Yuebai también lo puede hacer.",
  ui_story_5038_50381501_168_dialog_content = "¡Sí señor!",
  ui_story_5038_50381501_169_dialog_content = "Ahora bien, eso es suficiente balbuceo de mí.",
  ui_story_5038_50381501_170_dialog_content = "Está frío afuera. ¿Por qué no vienen todos y disfrutan de una buena comida?",
  ui_story_5038_50381501_171_dialog_content = "Sí, ¿qué estamos esperando todavía? ¡El Guildmaster ha hablado!",
  ui_story_5038_50381501_172_dialog_content = "¡Vamos, podemos hablar dentro!",
  ui_story_5038_50381501_173_dialog_content = "<color=#e8d9bb>Baraja, baraja...</color>",
  ui_story_5038_50381501_174_dialog_content = "¿Debería entrar yo también?",
  ui_story_5038_50381501_175_dialog_content = "Por supuesto. ¿Por qué, tienes algún lugar para estar?",
  ui_story_5038_50381501_176_dialog_content = "No pero...",
  ui_story_5038_50381501_177_dialog_content = "Me siento raro aprovechando una comida del gremio como un extraño...",
  ui_story_5038_50381501_178_dialog_content = "¿Un forastero? ¡No después de que ayudaste a Shadowind a superar todo ese problema!",
  ui_story_5038_50381501_179_dialog_content = "Mira, todos ya se están llenando.",
  ui_story_5038_50381501_180_dialog_content = "Buen vino y buena cocina... ¡No hace falta que me lo preguntes dos veces!",
  ui_story_5038_50381501_181_dialog_content = "¡Las mesas de los hogares ricos deben estar llenas de todo tipo de cosas deliciosas! ¡Vamos, Jiu!",
  ui_story_5038_50381501_182_dialog_content = "¡Cuidado al cruzar el umbral, Su Alteza!",
  ui_story_5038_50381501_183_dialog_content = "Wow, todos desaparecieron en un abrir y cerrar de ojos...",
  ui_story_5038_50381501_184_dialog_content = "Por eso te dije que no te preocuparas.",
  ui_story_5038_50381501_185_dialog_content = "Siéntase libre de quedarse aquí durante su estadía en Longzhou.",
  ui_story_5038_50381501_186_dialog_content = "Cuando el Shadowind zarpe de nuevo, te escoltaré de regreso a Astra.",
  ui_story_5038_50381501_187_dialog_content = "¿Quedarte con los Lin? no debo molestarte...",
  ui_story_5038_50381501_188_dialog_content = "Oh por favor. No vayas a recoger la cortesía estereotipada de Longzhou ahora.",
  ui_story_5038_50381501_189_dialog_content = "Entra antes de que se acabe la comida.",
  ui_story_5038_50381501_190_dialog_content = "(Longzhou es un lugar muy bullicioso y bullicioso).",
  ui_story_5038_50381501_191_dialog_content = "(Nadie podría sentirse solo en medio de las masas animadas).",
  ui_story_5038_50381501_192_dialog_content = "<color=#e8d9bb>Varios días después</color>",
  ui_story_5038_50381501_193_dialog_content = "¿Ir a Shadowind? ¿Ahora?",
  ui_story_5038_50381501_194_dialog_content = "Sí, Yuebai reunió a todos juntos. Eres la última persona.",
  ui_story_5038_50381501_195_dialog_content = "Pero no quiero hacer otro viaje, así que ¿por qué debería ir?",
  ui_story_5038_50381501_196_dialog_content = "No te preocupes, no es otro viaje. No te llevaremos a Astra.",
  ui_story_5038_50381501_197_dialog_content = "Ella tampoco me dijo los detalles, ¡así que supongo que lo averiguaremos!",
  ui_story_5038_50381501_198_dialog_content = "Bien, me iré, ya que no estamos muy lejos del muelle.",
  ui_story_5038_50381501_199_dialog_content = "¡Ese es el espíritu!",
  ui_story_5038_50381501_200_dialog_content = "¿Cómo te trata Longzhou? PlayerName? ¿Divirtiéndose?",
  ui_story_5038_50381501_201_dialog_content = "Todavía es algo nuevo para mí, y me da miedo hablar con los lugareños.",
  ui_story_5038_50381501_202_dialog_content = "Además, no tengo ni idea de adónde ir.",
  ui_story_5038_50381501_203_dialog_content = "Vaya, parece que los Lin no son buenos anfitriones.",
  ui_story_5038_50381501_204_dialog_content = "Ven a verme más tarde y te mostraré los alrededores.",
  ui_story_5038_50381501_205_dialog_content = "Claro, ¡eso suena genial!",
  ui_story_5038_50381501_206_dialog_content = "Por cierto, hay una cosa...",
  ui_story_5038_50381501_207_dialog_content = "¿Qué es?",
  ui_story_5038_50381501_208_dialog_content = "Traje una carta conmigo a Longzhou.",
  ui_story_5038_50381501_209_dialog_content = "Pasé los últimos dos días tratando de localizar la dirección del destinatario, pero no pude.",
  ui_story_5038_50381501_210_dialog_content = "Y ayer, accidentalmente derramé agua sobre el sobre.",
  ui_story_5038_50381501_211_dialog_content = "El sello de cera se disolvió y una pila de <color=#FFB400>papel rojo</color> salió volando.",
  ui_story_5038_50381501_212_dialog_content = "¡¿Papel rojo?!",
  ui_story_5038_50381501_213_dialog_content = "Sí. Parecían recortes de mariposas. Se juntaron y se fueron volando.",
  ui_story_5038_50381501_214_dialog_content = "No había nada más en el sobre. No estoy seguro de si esto cuenta como entregado.",
  ui_story_5038_50381501_215_dialog_content = "Mmm...",
  ui_story_5038_50381501_216_dialog_content = "¿Alguna idea sobre eso, Tianxian?",
  ui_story_5038_50381501_217_dialog_content = "Intrigante...",
  ui_story_5038_50381501_218_dialog_content = "No te preocupes por eso. El remitente consiguió su deseo.",
  ui_story_5038_50381501_X218_dialog_content = "Las mariposas aman las flores. Encontrarán su destino.",
  ui_story_5038_50381501_219_dialog_content = "Tu parte está hecha.",
  ui_story_5038_50381501_220_dialog_content = "¿Eso es? ¿Así?",
  ui_story_5038_50381501_221_dialog_content = "Por supuesto.",
  ui_story_5038_50381501_X221_dialog_content = "Nunca esperé que llegara aquí, desde el otro lado del mar.",
  ui_story_5038_50381501_X222_dialog_content = "<size=35>Las bendiciones y las desgracias existen en tándem. Efectivamente, nuestra bendita supervivencia no se manifestó de la nada.</size>",
  ui_story_5038_50381501_X223_dialog_content = "<size=35>Ahora...</size>",
  ui_story_5038_50381501_X224_dialog_content = "¿Qué? ¿Qué quieres decir?",
  ui_story_5038_50381501_X225_dialog_content = "Nada, no importa. Estaba hablando conmigo mismo.",
  ui_story_5038_50381501_222_dialog_content = "Oye, ahí está el muelle.",
  ui_story_5038_50381501_223_dialog_content = "apresurémonos",
  ui_story_5038_50381501_224_dialog_content = "¿Están clavados los clavos?",
  ui_story_5038_50381501_225_dialog_content = "¡Sí! ¿Alguien necesita uñas sobrantes?",
  ui_story_5038_50381501_226_dialog_content = "¡Mira, aquí vienen las dos últimas personas!",
  ui_story_5038_50381501_227_dialog_content = "Te hemos estado esperando.",
  ui_story_5038_50381501_228_dialog_content = "¡Todos están aquí ahora, Capitán!",
  ui_story_5038_50381501_229_dialog_content = "¿Todos presentes?",
  ui_story_5038_50381501_230_dialog_content = "Bien, pongámonos manos a la obra.",
  ui_story_5038_50381501_231_dialog_content = "¿Qué estamos haciendo aquí, Capitán?",
  ui_story_5038_50381501_232_dialog_content = "Hemos pasado por mucho juntos.",
  ui_story_5038_50381501_233_dialog_content = "Por lo tanto, seremos testigos de este momento juntos.",
  ui_story_5038_50381501_234_dialog_content = "¿Este momento?",
  ui_story_5038_50381501_235_dialog_content = "¡Capitán!",
  ui_story_5038_50381501_236_dialog_content = "Las reparaciones están hechas. Todos los controles completos.",
  ui_story_5038_50381501_237_dialog_content = "¡Shadowind está como nuevo!",
  ui_story_5038_50381501_238_dialog_content = "<size=45>¡Hurra!</size>",
  ui_story_5038_50381501_239_dialog_content = "¡Guau! ¡El barco está arreglado!",
  ui_story_5038_50381501_240_dialog_content = "Sí. Finalmente.",
  ui_story_5038_50381501_241_dialog_content = "Ahora ella realmente ha completado su viaje.",
  ui_story_5038_50381501_242_dialog_content = "Su viaje ha sido un ciclo interminable de daños y reparaciones. Hoy, finalmente ha terminado.",
  ui_story_5038_50381501_243_dialog_content = "Este viaje ha llegado a un final satisfactorio.",
  ui_story_5038_50381501_244_dialog_content = "¡Esto es genial! ¡Casi olvido cómo se veía el Shadowind originalmente!",
  ui_story_5038_50381501_245_dialog_content = "Todo está nuevo y pulido, no hay ni un rasguño... es un poco difícil acostumbrarse.",
  ui_story_5038_50381501_246_dialog_content = "Siéntase libre de explorar más tarde.",
  ui_story_5038_50381501_247_dialog_content = "Pero por ahora, necesito que todos ustedes hagan una cosa más.",
  ui_story_5038_50381501_248_dialog_content = "¿Qué es?",
  ui_story_5038_50381501_249_dialog_content = "Es una costumbre que los artesanos graben su nombre en el trabajo del que están más orgullosos.",
  ui_story_5038_50381501_250_dialog_content = "Por muchas reparaciones que hicimos a lo largo del viaje, todos aquí jugaron un papel importante para que el barco volviera a su antigua gloria.",
  ui_story_5038_50381501_251_dialog_content = "Me gustaría ver vuestros nombres adornando este nuevo Shadowind.",
  ui_story_5038_50381501_252_dialog_content = "Grabemos nuestros nombres en la icónica y tradicional \"oreja de conejo\".",
  ui_story_5038_50381501_253_dialog_content = "¡Oh, eso suena divertido!",
  ui_story_5038_50381501_254_dialog_content = "¡Gran idea! ¡Me encanta!",
  ui_story_5038_50381501_255_dialog_content = "Espero que a nadie le importe mi terrible guión...",
  ui_story_5038_50381501_256_dialog_content = "Veo que todos están de acuerdo.",
  ui_story_5038_50381501_257_dialog_content = "Entonces, comencemos con nuestro amigo del extranjero.",
  ui_story_5038_50381501_258_dialog_content = "¡¿Estás hablando de mí?!",
  ui_story_5038_50381501_259_dialog_content = "Sí. Es costumbre que los invitados vayan primero en Longzhou.",
  ui_story_5038_50381501_260_dialog_content = "Aquí está el cincel. Graba tu nombre donde prefieras.",
  ui_story_5038_50381501_261_dialog_content = "Esto es un poco incómodo.",
  ui_story_5038_50381501_262_dialog_content = "Y no creo que nadie pueda leer mi nombre...",
  ui_story_5038_50381501_263_dialog_content = "Eso es aún mejor. ¡No sabremos si te equivocas!",
  ui_story_5038_50381501_264_dialog_content = "Es un privilegio ir primero. Puedes elegir el mejor y más destacado lugar.",
  ui_story_5038_50381501_265_dialog_content = "Sí, ¿qué hay para ser incómodo?",
  ui_story_5038_50381501_266_dialog_content = "Vale todo está bien...",
  ui_story_5038_50381501_267_dialog_content = "Empiezo entonces.",
  ui_story_5038_50381501_268_dialog_content = "Sí, hazlo.",
  ui_story_5038_50381501_269_dialog_content = "(Mano, sostenga el cincel quieto y no lo sacuda.)",
  ui_story_5038_50381501_270_dialog_content = "(Vamos con este punto en el borde aquí.)",
  ui_story_5038_50381501_271option_content = "PlayerName",
  ui_story_5038_50381501_272_dialog_content = "¡Ahí tienes! ¡Eso se ve genial!",
  ui_story_5038_50381501_273_dialog_content = "¡Hazlo más grande para que podamos verlo!",
  ui_story_5038_50381501_274_dialog_content = "(Nadie puede dejar una marca en el océano).",
  ui_story_5038_50381501_275_dialog_content = "(Todo en su superficie es efímero, ya sean aguas tranquilas o olas turbulentas).",
  ui_story_5038_50381501_276_dialog_content = "(Sin embargo, siempre habrá quienes lo intenten).",
  ui_story_5038_50381501_277_dialog_content = "(Intente, como yo, grabar su nombre donde pueda permanecer para siempre).",
  ui_story_5038_50381501_278_dialog_content = "(Acompañará al Shadowind en su viaje entre los continentes).",
  ui_story_5038_50381501_279_dialog_content = "(No tiene la magnitud para cambiar el mar.)",
  ui_story_5038_50381501_280_dialog_content = "(Pero tal vez para algunos, mi nombre se convierta en sinónimo de sus aguas).",
  ui_story_5038_50381501_281_dialog_content = "PlayerName",
  ui_story_5038_50381501_282_dialog_content = "Continuará..."
}
return config
